    <script>
        // --- Sound Generation (Web Audio API) ---
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        function playSound(type) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();

            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);

            if (type === 'buy') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(440, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(880, audioCtx.currentTime + 0.1);
                gainNode.gain.setValueAtTime(0.3, audioCtx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.3);
            } else if (type === 'sell') {
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(600, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(300, audioCtx.currentTime + 0.15);
                gainNode.gain.setValueAtTime(0.3, audioCtx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.3);
            }
        }

        // --- Game State ---
        const STARTING_CASH = 10000;
        let gameState = {
            cash: STARTING_CASH,
            portfolio: {}, // { AAPL: { shares: 10, avgCost: 150.50 } }
            selectedSymbol: 'AAPL',
            tickInterval: null
        };

        // Simulated Market Data Configuration
        const MAX_HISTORY = 60; // Keep last 60 ticks
        const marketData = {
            'AAPL': { name: 'Apple Inc.', basePrice: 175.50, vol: 0.002, trend: 0.0001, history: [], color: '#3b82f6' },
            'TSLA': { name: 'Tesla, Inc.', basePrice: 210.20, vol: 0.005, trend: 0.000, history: [], color: '#ef4444' },
            'MSFT': { name: 'Microsoft Corp.', basePrice: 330.10, vol: 0.0015, trend: 0.0002, history: [], color: '#10b981' },
            'AMZN': { name: 'Amazon.com, Inc.', basePrice: 135.40, vol: 0.003, trend: -0.0001, history: [], color: '#f59e0b' },
            'NVDA': { name: 'NVIDIA Corp.', basePrice: 450.80, vol: 0.006, trend: 0.0005, history: [], color: '#84cc16' }
        };

        let chartInstance = null;

        // --- Initialization ---
        function initMarket() {
            // Generate initial history to fill the chart
            for (let symbol in marketData) {
                let currentPrice = marketData[symbol].basePrice;
                let momentum = 0;
                for (let i = 0; i < MAX_HISTORY; i++) {
                    let stock = marketData[symbol];
                    let shock = (Math.random() - 0.5) * stock.vol;
                    momentum = momentum * 0.8 + shock;
                    currentPrice = currentPrice * (1 + momentum + stock.trend);
                    stock.history.push(currentPrice);
                }
            }
        }

        function startGame() {
            document.getElementById('start-screen').classList.add('hidden');
            document.getElementById('game-ui').classList.remove('hidden');
            document.getElementById('game-ui').classList.add('flex');

            initMarket();
            buildTicker();
            initChart();
            updateUI();

            // Start simulation loop
            gameState.tickInterval = setInterval(tick, 1000);

            // Event listeners
            document.getElementById('trade-qty').addEventListener('input', updateEstTotal);
        }

        // --- Simulation Logic ---
        function tick() {
            for (let symbol in marketData) {
                let stock = marketData[symbol];
                let currentPrice = stock.history[stock.history.length - 1];

                // Random walk with momentum and drift
                let shock = (Math.random() - 0.5) * stock.vol;
                stock.momentum = (stock.momentum || 0) * 0.7 + shock;
                let newPrice = currentPrice * (1 + stock.momentum + stock.trend);

                // Prevent extreme drops below 1
                if (newPrice < 1) newPrice = 1 + Math.random(); 

                stock.history.push(newPrice);
                if (stock.history.length > MAX_HISTORY) {
                    stock.history.shift();
                }
            }
            updateChart();
            updateUI();
            updateEstTotal();
        }

        // --- Trading Mechanics ---
        function setQty(type) {
            const input = document.getElementById('trade-qty');
            const price = marketData[gameState.selectedSymbol].history.slice(-1)[0];

            if (type === 'max') {
                const maxShares = Math.floor(gameState.cash / price);
                input.value = maxShares > 0 ? maxShares : 1;
            }
            updateEstTotal();
        }

        function updateEstTotal() {
            const qty = parseInt(document.getElementById('trade-qty').value) || 0;
            const price = marketData[gameState.selectedSymbol].history.slice(-1)[0];
            document.getElementById('est-total').innerText = formatMoney(qty * price);
        }

        function executeTrade(action) {
            const symbol = gameState.selectedSymbol;
            const qty = parseInt(document.getElementById('trade-qty').value);
            const price = marketData[symbol].history[marketData[symbol].history.length - 1];
            const totalValue = qty * price;

            if (isNaN(qty) || qty <= 0) return;

            if (action === 'buy') {
                if (gameState.cash >= totalValue) {
                    gameState.cash -= totalValue;
                    if (!gameState.portfolio[symbol]) {
                        gameState.portfolio[symbol] = { shares: 0, avgCost: 0 };
                    }

                    // Calculate new average cost
                    const oldTotalCost = gameState.portfolio[symbol].shares * gameState.portfolio[symbol].avgCost;
                    const newTotalCost = oldTotalCost + totalValue;
                    gameState.portfolio[symbol].shares += qty;
                    gameState.portfolio[symbol].avgCost = newTotalCost / gameState.portfolio[symbol].shares;

                    playSound('buy');
                    flashElement('cash-display', 'flash-red');
                } else {
                    alert("Not enough cash!");
                }
            } else if (action === 'sell') {
                if (gameState.portfolio[symbol] && gameState.portfolio[symbol].shares >= qty) {
                    gameState.cash += totalValue;
                    gameState.portfolio[symbol].shares -= qty;

                    if (gameState.portfolio[symbol].shares === 0) {
                        delete gameState.portfolio[symbol];
                    }

                    playSound('sell');
                    flashElement('cash-display', 'flash-green');
                }
            }

            updateUI();
        }

        // --- UI Updates ---
        function formatMoney(amount) {
            return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
        }

        function flashElement(id, className) {
            const el = document.getElementById(id);
            el.classList.remove('flash-green', 'flash-red');
            void el.offsetWidth; // trigger reflow
            el.classList.add(className);
            setTimeout(() => el.classList.remove(className), 500);
        }

        function selectSymbol(symbol) {
            gameState.selectedSymbol = symbol;

            // Update active state in ticker
            document.querySelectorAll('.ticker-item').forEach(el => {
                if(el.dataset.symbol === symbol) {
                    el.classList.add('bg-slate-700', 'border-blue-500');
                    el.classList.remove('border-transparent');
                } else {
                    el.classList.remove('bg-slate-700', 'border-blue-500');
                    el.classList.add('border-transparent');
                }
            });

            // Update Chart Data & Colors
            chartInstance.data.datasets[0].data = marketData[symbol].history;
            chartInstance.data.datasets[0].borderColor = marketData[symbol].color;
            chartInstance.data.datasets[0].backgroundColor = createGradient(chartInstance.ctx, marketData[symbol].color);
            chartInstance.update();

            document.getElementById('chart-title').innerText = symbol;
            document.getElementById('chart-title').nextElementSibling.innerText = marketData[symbol].name;

            updateUI();
            updateEstTotal();
        }

        function buildTicker() {
            const strip = document.getElementById('ticker-strip');
            strip.innerHTML = '';
            for (let symbol in marketData) {
                const btn = document.createElement('button');
                btn.className = `ticker-item flex flex-col items-start p-2 rounded border-2 border-transparent hover:bg-slate-700 transition-colors min-w-[120px]`;
                btn.dataset.symbol = symbol;
                btn.onclick = () => selectSymbol(symbol);

                btn.innerHTML = `
                    <span class="font-bold">${symbol}</span>
                    <span class="mono text-sm" id="tick-${symbol}">--</span>
                `;
                strip.appendChild(btn);
            }
            // Select first initially
            selectSymbol('AAPL');
        }

        function updateUI() {
            let portfolioValue = 0;

            // Update Ticker prices and colors
            for (let symbol in marketData) {
                const history = marketData[symbol].history;
                const price = history[history.length - 1];
                const prevPrice = history[history.length - 2];
                const tickEl = document.getElementById(`tick-${symbol}`);

                if (tickEl) {
                    tickEl.innerText = price.toFixed(2);
                    if (price > prevPrice) {
                        tickEl.className = 'mono text-sm price-up';
                    } else if (price < prevPrice) {
                        tickEl.className = 'mono text-sm price-down';
                    }
                }
            }

            // Update Main Chart Header
            const selStock = marketData[gameState.selectedSymbol];
            const currP = selStock.history[selStock.history.length - 1];
            const prevP = selStock.history[selStock.history.length - 2];
            const change = currP - prevP;
            const pctChange = (change / prevP) * 100;

            const priceEl = document.getElementById('chart-price');
            priceEl.innerText = formatMoney(currP);
            priceEl.className = `mono text-4xl font-bold ${change >= 0 ? 'price-up' : 'price-down'}`;

            document.getElementById('chart-change').innerText = `${change > 0 ? '+' : ''}${change.toFixed(2)} (${pctChange.toFixed(2)}%)`;
            document.getElementById('chart-change').className = `mono text-sm ${change >= 0 ? 'price-up' : 'price-down'}`;

            // Update Buy/Sell Buttons State
            const qty = parseInt(document.getElementById('trade-qty').value) || 0;
            const canSell = gameState.portfolio[gameState.selectedSymbol] && gameState.portfolio[gameState.selectedSymbol].shares > 0;

            const sellBtn = document.getElementById('btn-sell');
            if (canSell) {
                sellBtn.classList.remove('opacity-50', 'cursor-not-allowed');
            } else {
                sellBtn.classList.add('opacity-50', 'cursor-not-allowed');
            }

            // Update Portfolio List
            const posList = document.getElementById('positions-list');
            const emptyMsg = document.getElementById('empty-portfolio');

            if (Object.keys(gameState.portfolio).length === 0) {
                posList.innerHTML = '';
                posList.appendChild(emptyMsg);
                emptyMsg.style.display = 'block';
            } else {
                posList.innerHTML = '';
                for (let sym in gameState.portfolio) {
                    const pos = gameState.portfolio[sym];
                    const currentSymPrice = marketData[sym].history.slice(-1)[0];
                    const posValue = pos.shares * currentSymPrice;
                    portfolioValue += posValue;

                    const profit = posValue - (pos.shares * pos.avgCost);
                    const profitPct = (profit / (pos.shares * pos.avgCost)) * 100;

                    const pClass = profit >= 0 ? 'price-up' : 'price-down';

                    posList.innerHTML += `
                        <div class="bg-slate-900 p-3 rounded flex justify-between items-center border border-slate-700 cursor-pointer hover:border-slate-500 transition-colors" onclick="selectSymbol('${sym}')">
                            <div>
                                <div class="font-bold">${sym} <span class="text-xs font-normal text-slate-400">x${pos.shares}</span></div>
                                <div class="text-xs text-slate-400">Avg: ${formatMoney(pos.avgCost)}</div>
                            </div>
                            <div class="text-right">
                                <div class="mono font-semibold">${formatMoney(posValue)}</div>
                                <div class="mono text-xs ${pClass}">${profit > 0 ? '+' : ''}${formatMoney(profit)} (${profitPct.toFixed(2)}%)</div>
                            </div>
                        </div>
                    `;
                }
            }

            // Update Top Bar Totals
            const totalNetWorth = gameState.cash + portfolioValue;
            const totalPL = totalNetWorth - STARTING_CASH;

            document.getElementById('cash-display').innerText = formatMoney(gameState.cash);
            document.getElementById('net-worth').innerText = formatMoney(totalNetWorth);

            const plEl = document.getElementById('total-pl');
            plEl.innerText = `${totalPL >= 0 ? '+' : ''}${formatMoney(totalPL)}`;
            plEl.className = `mono text-lg font-bold ${totalPL > 0 ? 'price-up' : (totalPL < 0 ? 'price-down' : 'text-slate-300')}`;
        }

        // --- Chart Configuration ---
        function createGradient(ctx, color) {
            const gradient = ctx.createLinearGradient(0, 0, 0, 400);
            // Convert hex to rgb for rgba
            let r = parseInt(color.slice(1, 3), 16);
            let g = parseInt(color.slice(3, 5), 16);
            let b = parseInt(color.slice(5, 7), 16);
            gradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, 0.5)`);
            gradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0.0)`);
            return gradient;
        }

        function initChart() {
            const ctx = document.getElementById('mainChart').getContext('2d');

            Chart.defaults.color = '#94a3b8';
            Chart.defaults.font.family = "'JetBrains Mono', monospace";

            chartInstance = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: Array(MAX_HISTORY).fill(''), // Dummy labels for X axis length
                    datasets: [{
                        label: 'Price',
                        data: marketData[gameState.selectedSymbol].history,
                        borderColor: marketData[gameState.selectedSymbol].color,
                        borderWidth: 2,
                        backgroundColor: createGradient(ctx, marketData[gameState.selectedSymbol].color),
                        fill: true,
                        pointRadius: 0,
                        pointHoverRadius: 4,
                        tension: 0.1
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    animation: {
                        duration: 0 // Disable animation for snappy tick updates
                    },
                    interaction: {
                        intersect: false,
                        mode: 'index',
                    },
                    plugins: {
                        legend: { display: false },
                        tooltip: {
                            backgroundColor: 'rgba(15, 23, 42, 0.9)',
                            titleColor: '#fff',
                            bodyColor: '#fff',
                            borderColor: '#334155',
                            borderWidth: 1,
                            callbacks: {
                                label: function(context) {
                                    return formatMoney(context.parsed.y);
                                },
                                title: () => null
                            }
                        }
                    },
                    scales: {
                        x: {
                            display: false, // Hide X axis labels (just representing time abstractly)
                            grid: { display: false }
                        },
                        y: {
                            position: 'right',
                            grid: {
                                color: '#334155',
                                drawBorder: false
                            },
                            ticks: {
                                callback: function(value) { return formatMoney(value); }
                            }
                        }
                    }
                }
            });
        }

        function updateChart() {
            if(chartInstance) {
                // Ensure length is consistent
                const data = marketData[gameState.selectedSymbol].history;
                chartInstance.data.datasets[0].data = data;
                chartInstance.update();
            }
        }
    </script>
</body>
