        <div id="start-screen" class="absolute inset-0 flex flex-col items-center justify-center bg-black/80 pointer-events-auto backdrop-blur-sm">
            <h1 class="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-pink-500 to-purple-500 mb-2 drop-shadow-[0_0_10px_rgba(236,72,153,0.8)]">SENPAI ROYALE</h1>
            <p class="text-xl text-gray-300 mb-8 italic">Notice them? No. Survive them.</p>

            <div class="bg-gray-900/80 p-6 rounded-lg border border-pink-500/50 mb-8 max-w-md text-center shadow-[0_0_15px_rgba(236,72,153,0.3)]">
                <p class="mb-2"><span class="font-bold text-pink-400">WASD</span> to Move</p>
                <p class="mb-2"><span class="font-bold text-pink-400">Mouse</span> to Aim & Click to Shoot</p>
                <p class="text-sm text-gray-400 mt-4">The red zone shrinks. Stay inside to survive. Reject the incoming horde.</p>
            </div>

            <button id="start-btn" class="px-8 py-3 bg-pink-600 hover:bg-pink-500 text-white font-bold rounded text-xl transition-transform hover:scale-105 shadow-[0_0_15px_rgba(236,72,153,0.5)]">
                START GAME
            </button>
        </div>

        <!-- Game Over Screen -->
        <div id="game-over-screen" class="hidden absolute inset-0 flex flex-col items-center justify-center bg-red-900/90 pointer-events-auto backdrop-blur-md">
            <h1 class="text-6xl font-black text-white mb-4 drop-shadow-lg">CAUGHT!</h1>
            <p class="text-2xl mb-2">You survived for <span id="final-time" class="font-bold text-yellow-300">0</span> seconds.</p>
            <p class="text-xl mb-8">Kouhais rejected: <span id="final-score" class="font-bold text-pink-300">0</span></p>

            <button id="restart-btn" class="px-8 py-3 bg-white text-red-900 hover:bg-gray-200 font-bold rounded text-xl transition-transform hover:scale-105 shadow-lg">
                PLAY AGAIN
            </button>
        </div>

    </div>

<script>
/**
 * Audio System (Web Audio API)
 */
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

function playSound(type) {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const osc = audioCtx.createOscillator();
    const gainNode = audioCtx.createGain();

    osc.connect(gainNode);
    gainNode.connect(audioCtx.destination);

    const now = audioCtx.currentTime;

    switch(type) {
        case 'shoot':
            osc.type = 'square';
            osc.frequency.setValueAtTime(400, now);
            osc.frequency.exponentialRampToValueAtTime(100, now + 0.1);
            gainNode.gain.setValueAtTime(0.05, now);
            gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
            osc.start(now);
            osc.stop(now + 0.1);
            break;
        case 'hit':
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.exponentialRampToValueAtTime(50, now + 0.1);
            gainNode.gain.setValueAtTime(0.1, now);
            gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
            osc.start(now);
            osc.stop(now + 0.1);
            break;
        case 'damage':
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(150, now);
            osc.frequency.exponentialRampToValueAtTime(80, now + 0.3);
            gainNode.gain.setValueAtTime(0.2, now);
            gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
            osc.start(now);
            osc.stop(now + 0.3);
            break;
        case 'gameover':
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(100, now);
            osc.frequency.linearRampToValueAtTime(20, now + 1);
            gainNode.gain.setValueAtTime(0.3, now);
            gainNode.gain.linearRampToValueAtTime(0.001, now + 1);
            osc.start(now);
            osc.stop(now + 1);
            break;
    }
}

/**
 * Game Setup & Canvas
 */
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d', { alpha: false }); // Optimize

let canvasWidth, canvasHeight;
function resize() {
    canvasWidth = window.innerWidth;
    canvasHeight = window.innerHeight;
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
}
window.addEventListener('resize', resize);
resize();

// UI Elements
const uiStart = document.getElementById('start-screen');
const uiHUD = document.getElementById('hud');
const uiGameOver = document.getElementById('game-over-screen');
const elScore = document.getElementById('score');
const elHpBar = document.getElementById('hp-bar');
const elZoneWarning = document.getElementById('zone-warning');
const elFinalScore = document.getElementById('final-score');
const elFinalTime = document.getElementById('final-time');

// Game State
let gameState = 'START'; // START, PLAYING, GAMEOVER
let lastTime = 0;
let score = 0;
let startTime = 0;

// World settings
const WORLD_SIZE = 3000;
let camera = { x: 0, y: 0 };

// Input
const keys = { w: false, a: false, s: false, d: false };
const mouse = { x: 0, y: 0, down: false };

window.addEventListener('keydown', e => {
    const k = e.key.toLowerCase();
    if(keys.hasOwnProperty(k)) keys[k] = true;
});
window.addEventListener('keyup', e => {
    const k = e.key.toLowerCase();
    if(keys.hasOwnProperty(k)) keys[k] = false;
});
window.addEventListener('mousemove', e => {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
});
window.addEventListener('mousedown', e => {
    if(gameState === 'PLAYING') mouse.down = true;
});
window.addEventListener('mouseup', e => {
    mouse.down = false;
});

/**
 * Game Entities
 */

class Player {
    constructor() {
        this.x = WORLD_SIZE / 2;
        this.y = WORLD_SIZE / 2;
        this.radius = 15;
        this.speed = 300; // pixels per second
        this.maxHp = 100;
        this.hp = this.maxHp;
        this.color = '#ec4899'; // Pink
        this.shootCooldown = 0;
        this.fireRate = 0.15; // seconds
    }

    update(dt) {
        let dx = 0, dy = 0;
        if(keys.w) dy -= 1;
        if(keys.s) dy += 1;
        if(keys.a) dx -= 1;
        if(keys.d) dx += 1;

        // Normalize diagonal movement
        if(dx !== 0 && dy !== 0) {
            const length = Math.sqrt(dx*dx + dy*dy);
            dx /= length;
            dy /= length;
        }

        this.x += dx * this.speed * dt;
        this.y += dy * this.speed * dt;

        // Constrain to world bounds
        this.x = Math.max(this.radius, Math.min(WORLD_SIZE - this.radius, this.x));
        this.y = Math.max(this.radius, Math.min(WORLD_SIZE - this.radius, this.y));

        // Shooting
        this.shootCooldown -= dt;
        if(mouse.down && this.shootCooldown <= 0) {
            this.shoot();
        }

        // Zone damage check
        const distToCenter = Math.hypot(this.x - WORLD_SIZE/2, this.y - WORLD_SIZE/2);
        if (distToCenter > zone.radius) {
            this.hp -= 15 * dt; // 15 dmg per second outside zone
            elZoneWarning.textContent = "OUTSIDE SAFE ZONE!";
        } else {
            elZoneWarning.textContent = "";
        }

        // Update HP bar
        elHpBar.style.width = Math.max(0, (this.hp / this.maxHp) * 100) + '%';
        if (this.hp <= 0) gameOver();
    }

    shoot() {
        this.shootCooldown = this.fireRate;
        // Calculate world mouse position based on camera
        const mouseWorldX = mouse.x + camera.x;
        const mouseWorldY = mouse.y + camera.y;

        const angle = Math.atan2(mouseWorldY - this.y, mouseWorldX - this.x);

        // Spawn bullet
        bullets.push(new Bullet(this.x, this.y, angle));
        playSound('shoot');

        // Slight recoil
        this.x -= Math.cos(angle) * 2;
        this.y -= Math.sin(angle) * 2;
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.x, this.y);

        // Calculate angle to mouse for rotation (drawing tie/face)
        const mouseWorldX = mouse.x + camera.x;
        const mouseWorldY = mouse.y + camera.y;
        const angle = Math.atan2(mouseWorldY - this.y, mouseWorldX - this.x);
        ctx.rotate(angle);

        // Body
        ctx.beginPath();
        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.lineWidth = 2;
        ctx.strokeStyle = '#fff';
        ctx.stroke();

        // Glasses/Direction indicator
        ctx.fillStyle = '#fff';
        ctx.fillRect(this.radius - 5, -8, 6, 4);
        ctx.fillRect(this.radius - 5, 4, 6, 4);

        ctx.restore();
    }
}

class Bullet {
    constructor(x, y, angle) {
        this.x = x + Math.cos(angle) * 20;
        this.y = y + Math.sin(angle) * 20;
        this.vx = Math.cos(angle) * 800;
        this.vy = Math.sin(angle) * 800;
        this.radius = 4;
        this.color = '#fbbf24'; // Yellow
        this.life = 1.5; // seconds
    }
    update(dt) {
        this.x += this.vx * dt;
        this.y += this.vy * dt;
        this.life -= dt;
    }
    draw(ctx) {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.radius = 12;
        this.speed = 150 + Math.random() * 100;
        this.hp = 2;
        this.color = '#ef4444'; // Red
        this.wobbleOffset = Math.random() * Math.PI * 2;
    }
    update(dt) {
        // Move towards player
        const angle = Math.atan2(player.y - this.y, player.x - this.x);

        // Add some wobble to movement
        const wobble = Math.sin(Date.now() / 200 + this.wobbleOffset) * 0.5;

        this.x += Math.cos(angle + wobble) * this.speed * dt;
        this.y += Math.sin(angle + wobble) * this.speed * dt;

        // Zone damage to enemies
        const distToCenter = Math.hypot(this.x - WORLD_SIZE/2, this.y - WORLD_SIZE/2);
        if (distToCenter > zone.radius) {
            this.hp -= 5 * dt;
        }
    }
    draw(ctx) {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.lineWidth = 1;
        ctx.strokeStyle = '#7f1d1d';
        ctx.stroke();

        // Eyes (creepy kouhai)
        const angle = Math.atan2(player.y - this.y, player.x - this.x);
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(angle);
        ctx.fillStyle = 'white';
        ctx.beginPath(); ctx.arc(this.radius/2, -4, 3, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(this.radius/2, 4, 3, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = 'black';
        ctx.beginPath(); ctx.arc(this.radius/2 + 1, -4, 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(this.radius/2 + 1, 4, 1.5, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    }
}

class Particle {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 200 + 50;
        this.vx = Math.cos(angle) * speed;
        this.vy = Math.sin(angle) * speed;
        this.radius = Math.random() * 3 + 1;
        this.color = color;
        this.life = Math.random() * 0.5 + 0.2;
        this.maxLife = this.life;
    }
    update(dt) {
        this.x += this.vx * dt;
        this.y += this.vy * dt;
        this.life -= dt;
        this.radius *= 0.95; // Shrink
    }
    draw(ctx) {
        ctx.globalAlpha = Math.max(0, this.life / this.maxLife);
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.globalAlpha = 1.0;
    }
}

class Zone {
    constructor() {
        this.x = WORLD_SIZE / 2;
        this.y = WORLD_SIZE / 2;
        this.radius = WORLD_SIZE; // Start large
        this.targetRadius = 100;
        this.shrinkTime = 120; // Seconds to reach target
        this.initialRadius = this.radius;
    }
    update(dt) {
        if (this.radius > this.targetRadius) {
            const shrinkRate = (this.initialRadius - this.targetRadius) / this.shrinkTime;
            this.radius -= shrinkRate * dt;
        }
    }
    draw(ctx) {
        // Draw the safe ring
        ctx.beginPath();
        ctx.arc(this.x, this.y, Math.max(0, this.radius), 0, Math.PI * 2);
        ctx.lineWidth = 5;
        ctx.strokeStyle = 'rgba(59, 130, 246, 0.8)'; // Blue border
        ctx.stroke();
    }
    drawOverlay(ctx, camX, camY, w, h) {
        // Draw red tint outside zone. 
        // Efficient approach: draw a huge rect over screen, then cut out the circle.
        ctx.save();
        ctx.fillStyle = 'rgba(220, 38, 38, 0.25)'; // Red tint
        ctx.fillRect(camX, camY, w, h);

        ctx.globalCompositeOperation = 'destination-out';
        ctx.beginPath();
        ctx.arc(this.x, this.y, Math.max(0, this.radius), 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }
}

// Global Entities
let player;
let bullets = [];
let enemies = [];
let particles = [];
let zone;
let enemySpawnTimer = 0;

/**
 * Game Logic
 */
function initGame() {
    player = new Player();
    bullets = [];
    enemies = [];
    particles = [];
    zone = new Zone();
    score = 0;
    elScore.innerText = score;
    startTime = Date.now();
    gameState = 'PLAYING';

    // Hide UI
    uiStart.classList.add('hidden');
    uiGameOver.classList.add('hidden');
    uiHUD.classList.remove('hidden');

    if(audioCtx.state === 'suspended') audioCtx.resume();
}

function spawnEnemies(dt) {
    // Increase spawn rate over time
    const timeAlive = (Date.now() - startTime) / 1000;
    const baseRate = 1.0;
    const currentRate = Math.max(0.2, baseRate - (timeAlive * 0.01)); // gets faster

    enemySpawnTimer -= dt;
    if(enemySpawnTimer <= 0) {
        enemySpawnTimer = currentRate;

        // Spawn outside camera view
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.max(canvasWidth, canvasHeight) / 2 + 100;
        const spawnX = player.x + Math.cos(angle) * dist;
        const spawnY = player.y + Math.sin(angle) * dist;

        // Only spawn if within world bounds
        if(spawnX > 0 && spawnX < WORLD_SIZE && spawnY > 0 && spawnY < WORLD_SIZE) {
            enemies.push(new Enemy(spawnX, spawnY));
        }
    }
}

function createExplosion(x, y, color, count) {
    for(let i=0; i<count; i++) {
        particles.push(new Particle(x, y, color));
    }
}

function checkCollisions() {
    // Bullet vs Enemy
    for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        let hit = false;
        for (let j = enemies.length - 1; j >= 0; j--) {
            const e = enemies[j];
            const dist = Math.hypot(b.x - e.x, b.y - e.y);
            if (dist < b.radius + e.radius) {
                e.hp--;
                bullets.splice(i, 1);
                hit = true;
                playSound('hit');
                createExplosion(b.x, b.y, b.color, 3);

                if (e.hp <= 0) {
                    enemies.splice(j, 1);
                    score++;
                    elScore.innerText = score;
                    createExplosion(e.x, e.y, e.color, 15);
                }
                break; // bullet dead, move to next bullet
            }
        }
    }

    // Enemy vs Player
    for (let i = enemies.length - 1; i >= 0; i--) {
        const e = enemies[i];
        const dist = Math.hypot(player.x - e.x, player.y - e.y);
        if (dist < player.radius + e.radius) {
            // Damage player, push enemy back slightly
            player.hp -= 10;
            playSound('damage');

            const angle = Math.atan2(e.y - player.y, e.x - player.x);
            e.x += Math.cos(angle) * 30;
            e.y += Math.sin(angle) * 30;

            // Screen shake effect could go here

            if (player.hp <= 0) {
                gameOver();
                return;
            }
        }
    }
}

function gameOver() {
    gameState = 'GAMEOVER';
    playSound('gameover');

    uiHUD.classList.add('hidden');
    uiGameOver.classList.remove('hidden');

    const timeSurvived = Math.floor((Date.now() - startTime) / 1000);
    elFinalTime.innerText = timeSurvived;
    elFinalScore.innerText = score;
}

/**
 * Main Game Loop
 */
function update(dt) {
    if (gameState !== 'PLAYING') return;

    player.update(dt);
    zone.update(dt);

    // Camera follow player
    camera.x = player.x - canvasWidth / 2;
    camera.y = player.y - canvasHeight / 2;

    // Constrain camera to world bounds
    camera.x = Math.max(0, Math.min(WORLD_SIZE - canvasWidth, camera.x));
    camera.y = Math.max(0, Math.min(WORLD_SIZE - canvasHeight, camera.y));

    spawnEnemies(dt);

    // Update bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
        bullets[i].update(dt);
        if (bullets[i].life <= 0) bullets.splice(i, 1);
    }

    // Update enemies
    for (let i = enemies.length - 1; i >= 0; i--) {
        enemies[i].update(dt);
        if(enemies[i].hp <= 0) {
             createExplosion(enemies[i].x, enemies[i].y, enemies[i].color, 10);
             enemies.splice(i, 1);
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        particles[i].update(dt);
        if (particles[i].life <= 0) particles.splice(i, 1);
    }

    checkCollisions();
}

function drawBackground(ctx, camX, camY) {
    // Fill base
    ctx.fillStyle = '#222';
    ctx.fillRect(camX, camY, canvasWidth, canvasHeight);

    // Draw grid lines
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    const gridSize = 100;

    const startX = Math.floor(camX / gridSize) * gridSize;
    const startY = Math.floor(camY / gridSize) * gridSize;

    ctx.beginPath();
    for (let x = startX; x < camX + canvasWidth; x += gridSize) {
        ctx.moveTo(x, camY);
        ctx.lineTo(x, camY + canvasHeight);
    }
    for (let y = startY; y < camY + canvasHeight; y += gridSize) {
        ctx.moveTo(camX, y);
        ctx.lineTo(camX + canvasWidth, y);
    }
    ctx.stroke();

    // World Boundaries
    ctx.strokeStyle = '#ff0055';
    ctx.lineWidth = 5;
    ctx.strokeRect(0, 0, WORLD_SIZE, WORLD_SIZE);
}

function draw() {
    // Clear whole canvas (ignore transform)
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    if (gameState === 'PLAYING') {
        ctx.save();
        // Apply camera translation
        ctx.translate(-camera.x, -camera.y);

        drawBackground(ctx, camera.x, camera.y);

        zone.draw(ctx);

        particles.forEach(p => p.draw(ctx));
        bullets.forEach(b => b.draw(ctx));
        enemies.forEach(e => e.draw(ctx));
        player.draw(ctx);

        // Draw zone damage overlay
        zone.drawOverlay(ctx, camera.x, camera.y, canvasWidth, canvasHeight);

        ctx.restore();
    }
}

function gameLoop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    let dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    // Cap dt to prevent huge jumps if tab is inactive
    if (dt > 0.1) dt = 0.1;

    update(dt);
    draw();

    requestAnimationFrame(gameLoop);
}

// Button Listeners
document.getElementById('start-btn').addEventListener('click', initGame);
document.getElementById('restart-btn').addEventListener('click', initGame);

// Start Loop
requestAnimationFrame(gameLoop);

</script>
</body>
</html>
