            <h1 class="text-6xl font-bold text-white mb-2 text-center" style="text-shadow: 0 0 10px #ff0000;">BLOCK STRIKE</h1>
            <p class="text-gray-300 mb-8 text-center max-w-md">WASD to Move. Mouse to Look. Left Click to Shoot. Right Click to Scope. Space to Jump. R to Reload.</p>
            <button id="start-btn" class="btn">CLICK TO DEPLOY</button>
        </div>

        <!-- Game Over Screen -->
        <div id="game-over-screen" class="screen hidden">
            <h1 class="text-6xl font-bold text-red-600 mb-2">YOU DIED</h1>
            <p class="text-2xl text-white mb-8">FINAL SCORE: <span id="final-score">0</span></p>
            <button id="restart-btn" class="btn">PLAY AGAIN</button>
        </div>
    </div>

<script>
/**
 * Simple PointerLockControls implementation
 */
class PointerLockControls {
    constructor(camera, domElement) {
        this.camera = camera;
        this.domElement = domElement;
        this.isLocked = false;
        this.euler = new THREE.Euler(0, 0, 0, 'YXZ');
        this.PI_2 = Math.PI / 2;
        this.connect();
    }
    onMouseMove(event) {
        if (!this.isLocked) return;
        const movementX = event.movementX || event.mozMovementX || event.webkitMovementX || 0;
        const movementY = event.movementY || event.mozMovementY || event.webkitMovementY || 0;
        this.euler.setFromQuaternion(this.camera.quaternion);
        this.euler.y -= movementX * 0.002;
        this.euler.x -= movementY * 0.002;
        this.euler.x = Math.max(-this.PI_2, Math.min(this.PI_2, this.euler.x));
        this.camera.quaternion.setFromEuler(this.euler);
    }
    onPointerlockChange() {
        this.isLocked = document.pointerLockElement === this.domElement;
    }
    connect() {
        document.addEventListener('mousemove', this.onMouseMove.bind(this), false);
        document.addEventListener('pointerlockchange', this.onPointerlockChange.bind(this), false);
    }
    lock() { this.domElement.requestPointerLock(); }
    unlock() { document.exitPointerLock(); }
}

// --- Audio System (Web Audio API Synth) ---
const AudioContext = window.AudioContext || window.webkitAudioContext;
let audioCtx;

function initAudio() {
    if (!audioCtx) audioCtx = new AudioContext();
    if (audioCtx.state === 'suspended') audioCtx.resume();
}

function playSound(type) {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    const now = audioCtx.currentTime;

    if (type === 'shoot') {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(150, now);
        osc.frequency.exponentialRampToValueAtTime(40, now + 0.1);
        gain.gain.setValueAtTime(0.3, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        osc.start(now); osc.stop(now + 0.1);
    } else if (type === 'hit') {
        osc.type = 'square';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(200, now + 0.05);
        gain.gain.setValueAtTime(0.5, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
        osc.start(now); osc.stop(now + 0.05);
    } else if (type === 'empty') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, now);
        gain.gain.setValueAtTime(0.1, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
        osc.start(now); osc.stop(now + 0.05);
    } else if (type === 'reload') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(300, now);
        osc.frequency.linearRampToValueAtTime(400, now + 0.5);
        gain.gain.setValueAtTime(0.2, now);
        gain.gain.linearRampToValueAtTime(0, now + 0.5);
        osc.start(now); osc.stop(now + 0.5);
    } else if (type === 'damage') {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(100, now);
        osc.frequency.exponentialRampToValueAtTime(50, now + 0.2);
        gain.gain.setValueAtTime(0.6, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
        osc.start(now); osc.stop(now + 0.2);
    }
}

// --- Game Engine Setup ---
const container = document.getElementById('game-container');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB); // Sky
scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
container.appendChild(renderer.domElement);

const controls = new PointerLockControls(camera, document.body);
const raycaster = new THREE.Raycaster();

// --- Lighting ---
const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 0.6);
hemiLight.position.set(0, 200, 0);
scene.add(hemiLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(100, 200, 50);
dirLight.castShadow = true;
dirLight.shadow.camera.top = 50; dirLight.shadow.camera.bottom = -50;
dirLight.shadow.camera.left = -50; dirLight.shadow.camera.right = 50;
scene.add(dirLight);

// --- Environment Generation (Map) ---
const groundGeo = new THREE.PlaneGeometry(200, 200);
const groundMat = new THREE.MeshLambertMaterial({ color: 0x3d5c3a }); // Grass green
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

const obstacles = [];
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const matBuilding = new THREE.MeshLambertMaterial({ color: 0x888888 });
const matCrate = new THREE.MeshLambertMaterial({ color: 0x8b5a2b });

// Generate random "houses" and crates
for (let i = 0; i < 40; i++) {
    const isBuilding = Math.random() > 0.5;
    const mesh = new THREE.Mesh(boxGeo, isBuilding ? matBuilding : matCrate);

    const sizeX = isBuilding ? Math.random() * 8 + 4 : Math.random() * 2 + 1;
    const sizeY = isBuilding ? Math.random() * 6 + 4 : Math.random() * 2 + 1;
    const sizeZ = isBuilding ? Math.random() * 8 + 4 : Math.random() * 2 + 1;

    mesh.scale.set(sizeX, sizeY, sizeZ);

    // Avoid spawning on origin
    let px, pz;
    do {
        px = (Math.random() - 0.5) * 150;
        pz = (Math.random() - 0.5) * 150;
    } while (Math.abs(px) < 10 && Math.abs(pz) < 10);

    mesh.position.set(px, sizeY / 2, pz);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    scene.add(mesh);
    obstacles.push(mesh);
}

// --- Player Weapon (Visual) ---
const weaponGroup = new THREE.Group();
camera.add(weaponGroup);
scene.add(camera);

// AK Style Blocky Gun
const gunMat = new THREE.MeshPhongMaterial({ color: 0x222222 });
const woodMat = new THREE.MeshPhongMaterial({ color: 0x5c3a21 });

const barrel = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.6), gunMat);
barrel.position.set(0, 0, -0.3);
const body = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.15, 0.4), gunMat);
body.position.set(0, -0.05, 0);
const stock = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.1, 0.3), woodMat);
stock.position.set(0, -0.1, 0.3);
const mag = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.2, 0.1), gunMat);
mag.position.set(0, -0.2, -0.05);
mag.rotation.x = Math.PI / 8;

weaponGroup.add(barrel); weaponGroup.add(body); weaponGroup.add(stock); weaponGroup.add(mag);

// Position weapon relative to camera
const weaponRestPos = new THREE.Vector3(0.3, -0.3, -0.5);
const weaponAimPos = new THREE.Vector3(0, -0.2, -0.4);
weaponGroup.position.copy(weaponRestPos);

// Muzzle Flash
const flashGeo = new THREE.PlaneGeometry(0.2, 0.2);
const flashMat = new THREE.MeshBasicMaterial({ color: 0xffff00, transparent: true, opacity: 0, side: THREE.DoubleSide });
const muzzleFlash = new THREE.Mesh(flashGeo, flashMat);
muzzleFlash.position.set(0, 0, -0.6);
weaponGroup.add(muzzleFlash);

// --- Game State & Variables ---
let gameState = 'start'; // start, play, over
let lastTime = performance.now();

// Player Logic
const player = {
    velocity: new THREE.Vector3(),
    direction: new THREE.Vector3(),
    speed: 15,
    hp: 100,
    maxHp: 100,
    score: 0,
    canJump: false,
    height: 1.6,
    radius: 0.5
};

// Weapon Logic
const weapon = {
    ammo: 30,
    maxAmmo: 30,
    reserve: 90,
    fireRate: 100, // ms between shots
    lastFire: 0,
    isFiring: false,
    isReloading: false,
    recoil: 0,
    isAiming: false
};

// Enemy Logic
const enemies = [];
const enemyGeo = new THREE.BoxGeometry(1, 2, 1);
const enemyMat = new THREE.MeshLambertMaterial({ color: 0xff0000 });

function spawnEnemy() {
    if (gameState !== 'play') return;
    if (enemies.length > 15) return; // Max enemies

    const enemy = new THREE.Mesh(enemyGeo, enemyMat);
    let px, pz;
    // Spawn away from player
    do {
        px = (Math.random() - 0.5) * 180;
        pz = (Math.random() - 0.5) * 180;
    } while (new THREE.Vector2(px, pz).distanceTo(new THREE.Vector2(camera.position.x, camera.position.z)) < 30);

    enemy.position.set(px, 1, pz);
    enemy.castShadow = true;

    // Enemy data
    enemy.userData = {
        hp: 50,
        speed: Math.random() * 2 + 2,
        isDead: false
    };

    scene.add(enemy);
    enemies.push(enemy);
}

// Spawn timer
setInterval(spawnEnemy, 2000);

// --- Input Handling ---
const keys = { w: false, a: false, s: false, d: false, space: false };

document.addEventListener('keydown', (e) => {
    if (gameState !== 'play') return;
    switch(e.code) {
        case 'KeyW': keys.w = true; break;
        case 'KeyA': keys.a = true; break;
        case 'KeyS': keys.s = true; break;
        case 'KeyD': keys.d = true; break;
        case 'Space': 
            if (player.canJump) { player.velocity.y += 10; player.canJump = false; }
            break;
        case 'KeyR': reload(); break;
    }
});

document.addEventListener('keyup', (e) => {
    switch(e.code) {
        case 'KeyW': keys.w = false; break;
        case 'KeyA': keys.a = false; break;
        case 'KeyS': keys.s = false; break;
        case 'KeyD': keys.d = false; break;
    }
});

document.addEventListener('mousedown', (e) => {
    if (gameState !== 'play' || !controls.isLocked) return;
    if (e.button === 0) { // Left click
        weapon.isFiring = true;
    } else if (e.button === 2) { // Right click - Aim
        weapon.isAiming = true;
    }
});

document.addEventListener('mouseup', (e) => {
    if (e.button === 0) {
        weapon.isFiring = false;
    } else if (e.button === 2) {
        weapon.isAiming = false;
    }
});

// Prevent context menu
document.addEventListener('contextmenu', e => e.preventDefault());

// --- UI Elements ---
const uiStart = document.getElementById('start-screen');
const uiHUD = document.getElementById('hud');
const uiGameOver = document.getElementById('game-over-screen');
const elHP = document.getElementById('hp-val');
const elScore = document.getElementById('score-val');
const elAmmo = document.getElementById('ammo-val');
const elDamageOverlay = document.getElementById('damage-overlay');

document.getElementById('start-btn').addEventListener('click', () => {
    initAudio();
    startGame();
});

document.getElementById('restart-btn').addEventListener('click', () => {
    startGame();
});

function updateHUD() {
    elHP.innerText = Math.floor(player.hp);
    elHP.className = player.hp > 50 ? 'text-green-400' : (player.hp > 20 ? 'text-yellow-400' : 'text-red-500');
    elScore.innerText = player.score;
    elAmmo.innerText = `${weapon.ammo}/${weapon.reserve}`;
}

function showDamage() {
    playSound('damage');
    elDamageOverlay.style.opacity = 1;
    setTimeout(() => { elDamageOverlay.style.opacity = 0; }, 150);
}

// --- Game Logic ---
function startGame() {
    gameState = 'play';
    uiStart.classList.add('hidden');
    uiGameOver.classList.add('hidden');
    uiHUD.classList.remove('hidden');

    // Reset Player
    player.hp = player.maxHp;
    player.score = 0;
    player.velocity.set(0,0,0);
    camera.position.set(0, player.height, 0);
    camera.rotation.set(0,0,0);

    // Reset Weapon
    weapon.ammo = weapon.maxAmmo;
    weapon.reserve = 90;
    weapon.isReloading = false;
    weapon.isAiming = false;

    // Clear Enemies
    enemies.forEach(e => scene.remove(e));
    enemies.length = 0;

    updateHUD();
    controls.lock();
    lastTime = performance.now();
}

function gameOver() {
    gameState = 'over';
    controls.unlock();
    uiHUD.classList.add('hidden');
    uiGameOver.classList.remove('hidden');
    document.getElementById('final-score').innerText = player.score;
}

function reload() {
    if (weapon.isReloading || weapon.ammo === weapon.maxAmmo || weapon.reserve <= 0) return;
    weapon.isReloading = true;
    playSound('reload');

    // Simple reload animation
    const ogRotX = weaponGroup.rotation.x;
    weaponGroup.rotation.x -= 0.5;

    setTimeout(() => {
        const needed = weapon.maxAmmo - weapon.ammo;
        const take = Math.min(needed, weapon.reserve);
        weapon.ammo += take;
        weapon.reserve -= take;
        weapon.isReloading = false;
        weaponGroup.rotation.x = ogRotX;
        updateHUD();
    }, 1500);
}

function fireWeapon() {
    const time = performance.now();
    if (time - weapon.lastFire < weapon.fireRate) return;
    if (weapon.isReloading) return;

    if (weapon.ammo <= 0) {
        if (time - weapon.lastFire > 200) { playSound('empty'); weapon.lastFire = time; }
        return;
    }

    weapon.ammo--;
    weapon.lastFire = time;
    updateHUD();
    playSound('shoot');

    // Muzzle Flash
    muzzleFlash.material.opacity = 1;
    muzzleFlash.rotation.z = Math.random() * Math.PI;
    setTimeout(() => { muzzleFlash.material.opacity = 0; }, 50);

    // Recoil (visual + camera)
    weapon.recoil = 0.05;
    controls.euler.x += (Math.random() * 0.02) + 0.01;
    controls.euler.y += (Math.random() - 0.5) * 0.01;
    camera.quaternion.setFromEuler(controls.euler);

    // Raycast for hit detection
    raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);

    // Check enemies
    const intersects = raycaster.intersectObjects(enemies);
    if (intersects.length > 0) {
        const hitEnemy = intersects[0].object;
        hitEnemy.userData.hp -= weapon.isAiming ? 30 : 20; // more damage scoped
        playSound('hit');

        // Visual hit marker (flash enemy white)
        hitEnemy.material.emissive.setHex(0xffffff);
        setTimeout(() => { if(hitEnemy) hitEnemy.material.emissive.setHex(0x000000); }, 50);

        if (hitEnemy.userData.hp <= 0 && !hitEnemy.userData.isDead) {
            hitEnemy.userData.isDead = true;
            scene.remove(hitEnemy);
            enemies.splice(enemies.indexOf(hitEnemy), 1);
            player.score += 100;
            updateHUD();
        }
    }
}

// Simple collision against obstacles (AABB)
function checkCollision(pos, radius) {
    const playerBox = new THREE.Box3().setFromCenterAndSize(
        new THREE.Vector3(pos.x, pos.y, pos.z),
        new THREE.Vector3(radius*2, player.height, radius*2)
    );

    for (let obs of obstacles) {
        const obsBox = new THREE.Box3().setFromObject(obs);
        if (playerBox.intersectsBox(obsBox)) {
            return true;
        }
    }
    // Boundaries
    if (Math.abs(pos.x) > 99 || Math.abs(pos.z) > 99) return true;
    return false;
}

// --- Main Loop ---
function animate() {
    requestAnimationFrame(animate);

    const time = performance.now();
    const delta = (time - lastTime) / 1000;
    lastTime = time;

    if (gameState === 'play') {
        // --- Player Movement & Physics ---
        player.velocity.x -= player.velocity.x * 10.0 * delta;
        player.velocity.z -= player.velocity.z * 10.0 * delta;
        player.velocity.y -= 30.0 * delta; // Gravity

        player.direction.z = Number(keys.w) - Number(keys.s);
        player.direction.x = Number(keys.d) - Number(keys.a);
        player.direction.normalize();

        const speedMod = weapon.isAiming ? 0.5 : 1.0;

        if (keys.w || keys.s) player.velocity.z -= player.direction.z * player.speed * speedMod * delta;
        if (keys.a || keys.d) player.velocity.x -= player.direction.x * player.speed * speedMod * delta;

        // Apply movement vector relative to camera direction
        const moveVec = new THREE.Vector3(player.velocity.x * delta, 0, player.velocity.z * delta);
        moveVec.applyEuler(new THREE.Euler(0, controls.euler.y, 0, 'YXZ'));

        // Collision Check X
        camera.position.x += moveVec.x;
        if (checkCollision(camera.position, player.radius)) {
            camera.position.x -= moveVec.x;
        }

        // Collision Check Z
        camera.position.z += moveVec.z;
        if (checkCollision(camera.position, player.radius)) {
            camera.position.z -= moveVec.z;
        }

        camera.position.y += player.velocity.y * delta;

        if (camera.position.y < player.height) {
            player.velocity.y = 0;
            camera.position.y = player.height;
            player.canJump = true;
        }

        // --- Weapon Mechanics ---
        if (weapon.isFiring) fireWeapon();

        // Scope / Aiming
        const targetFOV = weapon.isAiming ? 40 : 75;
        camera.fov += (targetFOV - camera.fov) * 10 * delta;
        camera.updateProjectionMatrix();

        // Weapon Sway & Position
        const targetPos = weapon.isAiming ? weaponAimPos : weaponRestPos;
        weaponGroup.position.lerp(targetPos, 15 * delta);

        // Recover recoil
        if (weapon.recoil > 0) {
            weaponGroup.position.z += weapon.recoil;
            weapon.recoil -= 0.5 * delta;
            if (weapon.recoil < 0) weapon.recoil = 0;
        }

        // --- Enemy AI ---
        const playerPos2D = new THREE.Vector2(camera.position.x, camera.position.z);

        for (let i = enemies.length - 1; i >= 0; i--) {
            const enemy = enemies[i];
            if (enemy.userData.isDead) continue;

            const enemyPos2D = new THREE.Vector2(enemy.position.x, enemy.position.z);
            const dist = enemyPos2D.distanceTo(playerPos2D);

            if (dist > 1.5) {
                // Move towards player
                const dir = new THREE.Vector2().subVectors(playerPos2D, enemyPos2D).normalize();
                enemy.position.x += dir.x * enemy.userData.speed * delta;
                enemy.position.z += dir.y * enemy.userData.speed * delta;
                enemy.lookAt(camera.position.x, enemy.position.y, camera.position.z);
            } else {
                // Attack player
                if (Math.random() < 0.05) { // Attack rate
                    player.hp -= 5;
                    updateHUD();
                    showDamage();
                    if (player.hp <= 0) gameOver();
                }
            }
        }
    }

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start loop
animate();

</script>
</body>
</html>
