            <!-- GAME OVER -->
            <div id="screen-gameover" class="hidden flex-grow flex flex-col items-center justify-center gap-4">
                <h2 class="text-3xl font-bold text-red-600">FATAL ERROR: SQUAD WIPED</h2>
                <div class="win95-panel p-4 text-center">
                    <p>Waves Survived: <span id="final-wave" class="font-bold">0</span></p>
                    <p>Total Cats Exploited: <span id="total-cats" class="font-bold">0</span></p>
                </div>
                <button id="btn-restart" class="win95-button mt-4">Reboot System</button>
            </div>

        </div>

        <!-- Status Bar -->
        <div class="border-t-2 border-gray-400 border-b-white border-l-gray-400 border-r-white bg-[#c0c0c0] px-2 py-0.5 text-xs flex justify-between">
            <span id="status-text">Ready.</span>
            <span>Memory: 640K OK</span>
        </div>
    </div>

    <script>
        // --- Audio System (Web Audio API) ---
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        function playSound(type) {
            if(audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.connect(gain);
            gain.connect(audioCtx.destination);

            const now = audioCtx.currentTime;

            if (type === 'click') {
                osc.type = 'square';
                osc.frequency.setValueAtTime(400, now);
                osc.frequency.exponentialRampToValueAtTime(800, now + 0.05);
                gain.gain.setValueAtTime(0.1, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
                osc.start(now);
                osc.stop(now + 0.05);
            } else if (type === 'hit') {
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(200 + Math.random()*100, now);
                osc.frequency.exponentialRampToValueAtTime(50, now + 0.1);
                gain.gain.setValueAtTime(0.2, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
                osc.start(now);
                osc.stop(now + 0.1);
            } else if (type === 'buy') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(600, now);
                osc.frequency.setValueAtTime(800, now + 0.1);
                gain.gain.setValueAtTime(0.1, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.2);
                osc.start(now);
                osc.stop(now + 0.2);
            } else if (type === 'die') {
                osc.type = 'square';
                osc.frequency.setValueAtTime(150, now);
                osc.frequency.exponentialRampToValueAtTime(40, now + 0.3);
                gain.gain.setValueAtTime(0.2, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.3);
                osc.start(now);
                osc.stop(now + 0.3);
            }
        }

        // --- Game Logic ---

        const catFaces = ['🐱','😸','😹','😻','😼','😽','🙀','😿','😾'];

        class Cat {
            constructor(isEnemy, wave) {
                this.id = Math.random().toString(36).substr(2, 9);
                this.isEnemy = isEnemy;
                this.face = catFaces[Math.floor(Math.random() * catFaces.length)];

                // Stat scaling
                let baseHp = isEnemy ? 15 : 20;
                let baseAtk = isEnemy ? 2 : 4;
                let spdVariance = Math.random() * 0.4 + 0.8; // 0.8 to 1.2

                let scale = 1 + (wave * 0.2);
                if(isEnemy) scale *= 0.8; // Enemies slightly weaker per unit

                this.maxHp = Math.floor(baseHp * scale + Math.random()*10);
                this.hp = this.maxHp;
                this.atk = Math.floor(baseAtk * scale + Math.random()*3);

                // Attack cooldown in ms (lower is faster)
                this.maxCooldown = Math.floor((1500 - (wave * 10)) * spdVariance);
                if(this.maxCooldown < 500) this.maxCooldown = 500;
                this.currentCooldown = Math.floor(Math.random() * this.maxCooldown);

                this.cost = Math.floor((this.maxHp + this.atk*3) / 4);
                this.name = isEnemy ? `Stray Lv${wave}` : `Gen ${Math.floor(Math.random()*99)}`;
            }
        }

        const GAME = {
            state: 'START', // START, BUY, BATTLE, GAMEOVER
            wave: 1,
            money: 50,
            playerCats: [],
            shopCats: [],
            enemyCats: [],
            maxRoster: 5,
            battleInterval: null,
            totalCatsBought: 0,

            init() {
                this.bindEvents();
            },

            bindEvents() {
                document.getElementById('btn-start').addEventListener('click', () => { playSound('click'); this.changeState('BUY'); });
                document.getElementById('btn-next-wave').addEventListener('click', () => { playSound('click'); this.changeState('BATTLE'); });
                document.getElementById('btn-reroll').addEventListener('click', () => { 
                    playSound('click'); 
                    if(this.money >= 2) {
                        this.money -= 2;
                        this.generateShop();
                        this.updateBuyUI();
                    }
                });
                document.getElementById('btn-continue').addEventListener('click', () => { 
                    playSound('click'); 
                    this.changeState('BUY'); 
                });
                document.getElementById('btn-restart').addEventListener('click', () => { 
                    playSound('click'); 
                    this.resetGame(); 
                    this.changeState('BUY'); 
                });

                // Add sound to title bar clicks for flavor
                document.querySelectorAll('.win95-btn-close').forEach(btn => {
                    btn.addEventListener('click', () => playSound('click'));
                });
            },

            resetGame() {
                this.wave = 1;
                this.money = 50;
                this.playerCats = [];
                this.totalCatsBought = 0;
            },

            changeState(newState) {
                // Hide all
                ['start', 'buy', 'battle', 'gameover'].forEach(s => {
                    document.getElementById(`screen-${s}`).classList.add('hidden');
                });

                this.state = newState;
                document.getElementById(`screen-${newState.toLowerCase()}`).classList.remove('hidden');

                if (newState === 'BUY') {
                    this.setStatus('Buying Phase. Build your squad.');
                    this.generateShop();
                    this.updateBuyUI();
                } else if (newState === 'BATTLE') {
                    this.setStatus(`Combat engaged. Wave ${this.wave}.`);
                    this.startBattle();
                } else if (newState === 'GAMEOVER') {
                    this.setStatus('System Halted.');
                    document.getElementById('final-wave').textContent = this.wave;
                    document.getElementById('total-cats').textContent = this.totalCatsBought;
                }
            },

            setStatus(text) {
                document.getElementById('status-text').textContent = text;
            },

            // --- BUY PHASE ---

            generateShop() {
                this.shopCats = [];
                for(let i=0; i<3; i++) {
                    this.shopCats.push(new Cat(false, this.wave));
                }
            },

            updateBuyUI() {
                document.getElementById('ui-wave').textContent = this.wave;
                document.getElementById('ui-money').textContent = this.money;

                const btnNext = document.getElementById('btn-next-wave');
                btnNext.disabled = this.playerCats.length === 0;

                this.renderCatCards(this.playerCats, 'player-squad', true);
                this.renderCatCards(this.shopCats, 'shop-cats', false);
            },

            renderCatCards(cats, containerId, isPlayerOwned) {
                const container = document.getElementById(containerId);
                container.innerHTML = '';

                cats.forEach((cat, index) => {
                    const card = document.createElement('div');
                    card.className = 'cat-card win95-button flex flex-col items-center';
                    if(!isPlayerOwned && this.money < cat.cost) {
                        card.style.opacity = '0.5';
                    }

                    card.innerHTML = `
                        <div class="cat-sprite">${cat.face}</div>
                        <div class="font-bold truncate w-full">${cat.name}</div>
                        <div class="text-[10px]">HP: ${cat.hp}</div>
                        <div class="text-[10px]">ATK: ${cat.atk}</div>
                        <div class="text-[10px]">SPD: ${(1000/cat.maxCooldown).toFixed(1)}/s</div>
                        ${!isPlayerOwned ? `<div class="mt-1 font-bold text-green-700">$${cat.cost}</div>` : 
                           `<div class="mt-1 text-[9px] text-red-600 hover:underline">Sell $${Math.floor(cat.cost/2)}</div>`}
                    `;

                    if (!isPlayerOwned) {
                        card.onclick = () => this.buyCat(index);
                    } else {
                        // Sell functionality on the sell text
                        const sellBtn = card.querySelector('.text-red-600');
                        if(sellBtn) {
                            sellBtn.onclick = (e) => {
                                e.stopPropagation();
                                this.sellCat(index);
                            }
                        }
                    }
                    container.appendChild(card);
                });
            },

            buyCat(index) {
                const cat = this.shopCats[index];
                if (this.money >= cat.cost && this.playerCats.length < this.maxRoster) {
                    playSound('buy');
                    this.money -= cat.cost;
                    this.playerCats.push(cat);
                    this.shopCats.splice(index, 1);
                    this.totalCatsBought++;
                    this.updateBuyUI();
                } else if (this.playerCats.length >= this.maxRoster) {
                    this.setStatus('Roster is full!');
                } else {
                    this.setStatus('Insufficient funds.');
                }
            },

            sellCat(index) {
                playSound('click');
                const cat = this.playerCats[index];
                this.money += Math.floor(cat.cost / 2);
                this.playerCats.splice(index, 1);
                this.updateBuyUI();
            },

            // --- BATTLE PHASE ---

            startBattle() {
                document.getElementById('battle-wave-ui').textContent = this.wave;
                document.getElementById('btn-continue').classList.add('hidden');
                document.getElementById('combat-log').innerHTML = '';

                // Heal player cats slightly between waves
                this.playerCats.forEach(c => {
                    c.hp = Math.min(c.maxHp, c.hp + Math.floor(c.maxHp * 0.2));
                    c.currentCooldown = Math.random() * c.maxCooldown; // Reset CD
                });

                // Generate Enemies
                this.enemyCats = [];
                const numEnemies = Math.min(6, 2 + Math.floor(this.wave / 2));
                for(let i=0; i<numEnemies; i++) {
                    this.enemyCats.push(new Cat(true, this.wave));
                }

                this.renderBattleCards();

                // Start combat loop
                if(this.battleInterval) clearInterval(this.battleInterval);
                this.lastTick = Date.now();
                this.battleInterval = setInterval(() => this.combatTick(), 50); // 20 ticks per second
            },

            renderBattleCards() {
                this._renderBattleSide(this.playerCats, 'battle-player-side', false);
                this._renderBattleSide(this.enemyCats, 'battle-enemy-side', true);
            },

            _renderBattleSide(cats, containerId, isEnemy) {
                const container = document.getElementById(containerId);
                container.innerHTML = '';
                cats.forEach(cat => {
                    const card = document.createElement('div');
                    card.id = `battle-cat-${cat.id}`;
                    card.className = `cat-card ${isEnemy ? 'enemy' : ''} ${cat.hp <= 0 ? 'dead' : ''}`;

                    const hpPercent = Math.max(0, (cat.hp / cat.maxHp) * 100);

                    card.innerHTML = `
                        <div class="cat-sprite">${cat.face}</div>
                        <div class="text-[9px] truncate">${cat.name}</div>
                        <div class="text-[9px] font-bold">HP: ${cat.hp}</div>
                        <div class="hp-bar-bg">
                            <div class="hp-bar-fill" style="width: ${hpPercent}%"></div>
                        </div>
                    `;
                    container.appendChild(card);
                });
            },

            logCombat(msg) {
                const log = document.getElementById('combat-log');
                const entry = document.createElement('div');
                entry.textContent = `> ${msg}`;
                log.appendChild(entry);
                log.scrollTop = log.scrollHeight;
            },

            combatTick() {
                const now = Date.now();
                const dt = now - this.lastTick;
                this.lastTick = now;

                let stateChanged = false;

                // Process Player Attacks
                this.playerCats.forEach(cat => {
                    if (cat.hp <= 0) return;
                    cat.currentCooldown += dt;
                    if (cat.currentCooldown >= cat.maxCooldown) {
                        if (this.performAttack(cat, this.enemyCats)) stateChanged = true;
                        cat.currentCooldown = 0;
                    }
                });

                // Process Enemy Attacks
                this.enemyCats.forEach(cat => {
                    if (cat.hp <= 0) return;
                    cat.currentCooldown += dt;
                    if (cat.currentCooldown >= cat.maxCooldown) {
                        if (this.performAttack(cat, this.playerCats)) stateChanged = true;
                        cat.currentCooldown = 0;
                    }
                });

                if (stateChanged) {
                    this.renderBattleCards();
                    this.checkBattleEnd();
                }
            },

            performAttack(attacker, targetArray) {
                const aliveTargets = targetArray.filter(c => c.hp > 0);
                if (aliveTargets.length === 0) return false;

                // Pick random target
                const target = aliveTargets[Math.floor(Math.random() * aliveTargets.length)];

                // Damage calculation (add slight randomness)
                const dmg = Math.max(1, attacker.atk + Math.floor(Math.random()*3 - 1));
                target.hp -= dmg;

                playSound('hit');

                // Visual flash
                const attackerEl = document.getElementById(`battle-cat-${attacker.id}`);
                if(attackerEl) {
                    attackerEl.classList.remove('flash-attack');
                    void attackerEl.offsetWidth; // trigger reflow
                    attackerEl.classList.add('flash-attack');
                }

                this.logCombat(`${attacker.name} hit ${target.name} for ${dmg} DMG.`);

                if (target.hp <= 0) {
                    target.hp = 0;
                    playSound('die');
                    this.logCombat(`*** ${target.name} perished. ***`);
                }
                return true;
            },

            checkBattleEnd() {
                const playerAlive = this.playerCats.some(c => c.hp > 0);
                const enemyAlive = this.enemyCats.some(c => c.hp > 0);

                if (!playerAlive || !enemyAlive) {
                    clearInterval(this.battleInterval);

                    if (!playerAlive) {
                        this.logCombat("SYSTEM FAILURE: All cats dead.");
                        setTimeout(() => this.changeState('GAMEOVER'), 1500);
                    } else {
                        const reward = 10 + (this.wave * 5);
                        this.money += reward;
                        this.logCombat(`VICTORY! Earned $${reward}.`);
                        this.setStatus(`Wave ${this.wave} Cleared.`);

                        // Clean up dead player cats
                        this.playerCats = this.playerCats.filter(c => c.hp > 0);

                        this.wave++;
                        document.getElementById('btn-continue').classList.remove('hidden');
                    }
                }
            }
        };

        // Initialize
        window.onload = () => GAME.init();

    </script>
</body>
</html>
