            <div class="flex justify-center gap-2 mb-4" id="win-stars">
                <!-- Stars injected here -->
            </div>
            <button class="btn" onclick="resetGame()">Replay</button>
        </div>
    </div>
</div>

<script>
    // Audio Context Setup
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    let audioCtx = new AudioContext();

    function playSound(type) {
        if (audioCtx.state === 'suspended') audioCtx.resume();
        const osc = audioCtx.createOscillator();
        const gainNode = audioCtx.createGain();
        osc.connect(gainNode);
        gainNode.connect(audioCtx.destination);

        const now = audioCtx.currentTime;
        if (type === 'cut') {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.exponentialRampToValueAtTime(300, now + 0.1);
            gainNode.gain.setValueAtTime(0.5, now);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
            osc.start(now);
            osc.stop(now + 0.1);
        } else if (type === 'star') {
            osc.type = 'square';
            osc.frequency.setValueAtTime(600, now);
            osc.frequency.setValueAtTime(800, now + 0.1);
            gainNode.gain.setValueAtTime(0.3, now);
            gainNode.gain.linearRampToValueAtTime(0, now + 0.3);
            osc.start(now);
            osc.stop(now + 0.3);
        } else if (type === 'win') {
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(400, now);
            osc.frequency.linearRampToValueAtTime(600, now + 0.1);
            osc.frequency.linearRampToValueAtTime(800, now + 0.2);
            gainNode.gain.setValueAtTime(0.5, now);
            gainNode.gain.linearRampToValueAtTime(0, now + 0.5);
            osc.start(now);
            osc.stop(now + 0.5);
        }
    }

    // Matter.js aliases
    const Engine = Matter.Engine,
          Render = Matter.Render,
          Runner = Matter.Runner,
          Bodies = Matter.Bodies,
          Composite = Matter.Composite,
          Constraint = Matter.Constraint,
          Events = Matter.Events,
          Vector = Matter.Vector;

    // Game Variables
    let engine, runner;
    let canvas = document.getElementById('game-canvas');
    let ctx = canvas.getContext('2d');
    let width, height;

    let gameState = 'MENU'; // MENU, PLAYING, GAMEOVER, WIN
    let score = 0;
    let swipeTrail = [];
    let isDrawing = false;

    // Entities
    let candy, monster, ropes = [], stars = [], obstacles = [];
    const CANDY_RADIUS = 20;

    // Line intersection utility
    function intersects(a, b, c, d) {
        let det, gamma, lambda;
        det = (a.x - b.x) * (c.y - d.y) - (a.y - b.y) * (c.x - d.x);
        if (det === 0) return false;
        lambda = ((c.y - d.y) * (c.x - a.x) + (d.x - c.x) * (c.y - a.y)) / det;
        gamma = ((b.y - a.y) * (c.x - a.x) + (a.x - b.x) * (c.y - a.y)) / det;
        return (0 < lambda && lambda < 1) && (0 < gamma && gamma < 1);
    }

    function initPhysics() {
        engine = Engine.create();
        engine.world.gravity.y = 1;
        runner = Runner.create();
        Runner.run(runner, engine);

        Events.on(engine, 'collisionStart', handleCollisions);
    }

    function resizeCanvas() {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width;
        canvas.height = height;
    }

    function buildLevel() {
        Composite.clear(engine.world);
        Engine.clear(engine);
        ropes = [];
        stars = [];
        obstacles = [];
        score = 0;
        updateHUD();

        const cx = width / 2;

        // Candy
        candy = Bodies.circle(cx, height * 0.2, CANDY_RADIUS, {
            restitution: 0.5,
            frictionAir: 0.01,
            density: 0.005,
            label: 'candy'
        });

        // Anchors & Ropes (Medium Level Design)
        // Two ropes holding candy at top, one blocking platform below
        const anchorL = { x: cx - 100, y: height * 0.1 };
        const anchorR = { x: cx + 100, y: height * 0.1 };
        const anchorB = { x: cx - 120, y: height * 0.4 };

        function createRope(pointA, bodyB, length) {
            const rope = Constraint.create({
                pointA: pointA,
                bodyB: bodyB,
                length: length,
                stiffness: 0.8,
                damping: 0.1,
                render: { visible: false }
            });
            ropes.push(rope);
            Composite.add(engine.world, rope);
        }

        createRope(anchorL, candy, 150);
        createRope(anchorR, candy, 150);
        createRope(anchorB, candy, 200);

        // Obstacles (Static)
        const platform = Bodies.rectangle(cx, height * 0.55, 150, 20, { 
            isStatic: true, 
            label: 'obstacle',
            render: { fillStyle: '#8d6e63' }
        });
        obstacles.push(platform);

        // Stars (Sensors)
        const starPos = [
            { x: cx, y: height * 0.35 },
            { x: cx + 120, y: height * 0.5 },
            { x: cx - 50, y: height * 0.7 }
        ];

        starPos.forEach((pos, i) => {
            let star = Bodies.circle(pos.x, pos.y, 15, {
                isStatic: true,
                isSensor: true,
                label: 'star',
                id: i
            });
            stars.push(star);
        });

        // Monster (Sensor)
        monster = Bodies.circle(cx + 80, height * 0.85, 40, {
            isStatic: true,
            isSensor: true,
            label: 'monster'
        });

        Composite.add(engine.world, [candy, platform, monster, ...stars]);
    }

    function handleCollisions(event) {
        if (gameState !== 'PLAYING') return;

        const pairs = event.pairs;
        for (let i = 0; i < pairs.length; i++) {
            const bodyA = pairs[i].bodyA;
            const bodyB = pairs[i].bodyB;

            const isCandy = bodyA.label === 'candy' || bodyB.label === 'candy';
            const otherBody = bodyA.label === 'candy' ? bodyB : bodyA;

            if (isCandy) {
                if (otherBody.label === 'star' && !otherBody.collected) {
                    otherBody.collected = true;
                    score++;
                    playSound('star');
                    updateHUD();
                    // Move star offscreen
                    Matter.Body.setPosition(otherBody, {x: -100, y: -100});
                } else if (otherBody.label === 'monster') {
                    winGame();
                }
            }
        }
    }

    function updateHUD() {
        for(let i=1; i<=3; i++) {
            document.getElementById(`star${i}`).classList.toggle('active', score >= i);
        }
    }

    // Input Handling
    function handleTouchStart(e) {
        if (gameState !== 'PLAYING') return;
        e.preventDefault();
        isDrawing = true;
        const touch = e.touches ? e.touches[0] : e;
        swipeTrail = [{ x: touch.clientX, y: touch.clientY }];
    }

    function handleTouchMove(e) {
        if (!isDrawing || gameState !== 'PLAYING') return;
        e.preventDefault();
        const touch = e.touches ? e.touches[0] : e;
        const currentPt = { x: touch.clientX, y: touch.clientY };
        const lastPt = swipeTrail[swipeTrail.length - 1];

        // Check cuts
        for (let i = ropes.length - 1; i >= 0; i--) {
            let rope = ropes[i];
            let p1 = rope.pointA || rope.bodyA.position;
            let p2 = rope.bodyB.position;

            // Adjust constraint endpoints
            let absP1 = { x: p1.x + (rope.pointA?0:rope.pointA.x), y: p1.y + (rope.pointA?0:rope.pointA.y) };
            let absP2 = { x: p2.x + rope.pointB.x, y: p2.y + rope.pointB.y };

            if (intersects(lastPt, currentPt, absP1, absP2)) {
                Composite.remove(engine.world, rope);
                ropes.splice(i, 1);
                playSound('cut');
            }
        }

        swipeTrail.push(currentPt);
        if (swipeTrail.length > 10) swipeTrail.shift();
    }

    function handleTouchEnd(e) {
        isDrawing = false;
        swipeTrail = [];
    }

    canvas.addEventListener('touchstart', handleTouchStart, {passive: false});
    canvas.addEventListener('touchmove', handleTouchMove, {passive: false});
    canvas.addEventListener('touchend', handleTouchEnd);
    canvas.addEventListener('mousedown', handleTouchStart);
    canvas.addEventListener('mousemove', handleTouchMove);
    window.addEventListener('mouseup', handleTouchEnd);

    // Custom Rendering
    function draw() {
        requestAnimationFrame(draw);

        ctx.clearRect(0, 0, width, height);

        if (gameState === 'MENU') return;

        // Draw Ropes
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#8B4513';
        ctx.setLineDash([10, 5]);
        ropes.forEach(rope => {
            let p1 = rope.pointA;
            let p2 = { x: rope.bodyB.position.x + rope.pointB.x, y: rope.bodyB.position.y + rope.pointB.y };
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();

            // Draw anchor pin
            ctx.fillStyle = '#666';
            ctx.beginPath();
            ctx.arc(p1.x, p1.y, 6, 0, Math.PI*2);
            ctx.fill();
        });
        ctx.setLineDash([]);

        // Draw Obstacles
        ctx.fillStyle = '#6d4c41';
        obstacles.forEach(obs => {
            ctx.save();
            ctx.translate(obs.position.x, obs.position.y);
            ctx.rotate(obs.angle);
            ctx.fillRect(-obs.bounds.max.x + obs.position.x, -obs.bounds.max.y + obs.position.y, obs.bounds.max.x - obs.bounds.min.x, obs.bounds.max.y - obs.bounds.min.y);
            ctx.restore();
        });

        // Draw Stars
        stars.forEach(star => {
            if (!star.collected) {
                ctx.save();
                ctx.translate(star.position.x, star.position.y);
                // Simple pulse animation
                let scale = 1 + Math.sin(Date.now() / 200) * 0.1;
                ctx.scale(scale, scale);

                ctx.fillStyle = '#ffd166';
                ctx.beginPath();
                for (let i = 0; i < 5; i++) {
                    ctx.lineTo(Math.cos((18 + i * 72) * Math.PI / 180) * 15, -Math.sin((18 + i * 72) * Math.PI / 180) * 15);
                    ctx.lineTo(Math.cos((54 + i * 72) * Math.PI / 180) * 7, -Math.sin((54 + i * 72) * Math.PI / 180) * 7);
                }
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
                ctx.restore();
            }
        });

        // Draw Monster (Om Nom style)
        ctx.save();
        ctx.translate(monster.position.x, monster.position.y);
        ctx.fillStyle = '#06d6a0'; // Green
        ctx.beginPath();
        ctx.arc(0, 0, 40, 0, Math.PI, true); // Top half
        ctx.lineTo(40, 20);
        ctx.lineTo(-40, 20);
        ctx.fill();

        // Eyes
        ctx.fillStyle = 'white';
        ctx.beginPath(); ctx.arc(-15, -15, 10, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, -15, 10, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = 'black';
        ctx.beginPath(); ctx.arc(-15 + Math.sin(Date.now()/500)*2, -15, 4, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(15 + Math.sin(Date.now()/500)*2, -15, 4, 0, Math.PI*2); ctx.fill();

        // Mouth
        let isCandyClose = Matter.Vector.magnitude(Matter.Vector.sub(candy.position, monster.position)) < 150;
        ctx.fillStyle = isCandyClose ? '#111' : '#333';
        ctx.beginPath();
        if (isCandyClose) {
            ctx.ellipse(0, 5, 25, 15, 0, 0, Math.PI*2);
        } else {
            ctx.ellipse(0, 5, 20, 5, 0, 0, Math.PI*2);
        }
        ctx.fill();
        ctx.restore();

        // Draw Candy
        ctx.save();
        ctx.translate(candy.position.x, candy.position.y);
        ctx.rotate(candy.angle);
        ctx.fillStyle = '#ef476f'; // Red/Pink
        ctx.beginPath();
        ctx.arc(0, 0, CANDY_RADIUS, 0, Math.PI * 2);
        ctx.fill();

        // Candy Swirl detail
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.arc(0, 0, CANDY_RADIUS - 5, 0, Math.PI);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(0, 0, CANDY_RADIUS - 12, Math.PI, Math.PI*2);
        ctx.stroke();
        ctx.restore();

        // Draw Swipe Trail
        if (swipeTrail.length > 1) {
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 4;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(swipeTrail[0].x, swipeTrail[0].y);
            for (let i = 1; i < swipeTrail.length; i++) {
                ctx.lineTo(swipeTrail[i].x, swipeTrail[i].y);
            }
            ctx.stroke();
        }

        // Game Over Check
        if (candy.position.y > height + CANDY_RADIUS || candy.position.x < -100 || candy.position.x > width + 100) {
            loseGame();
        }
    }

    // State Management
    function startGame() {
        document.getElementById('start-screen').classList.add('hidden');
        document.getElementById('hud').classList.remove('hidden');
        if(!engine) initPhysics();
        buildLevel();
        gameState = 'PLAYING';
    }

    function loseGame() {
        if (gameState !== 'PLAYING') return;
        gameState = 'GAMEOVER';
        document.getElementById('game-over-screen').classList.remove('hidden');
        document.getElementById('hud').classList.add('hidden');
    }

    function winGame() {
        if (gameState !== 'PLAYING') return;
        gameState = 'WIN';
        playSound('win');

        // Hide candy
        Matter.Body.setPosition(candy, {x: -1000, y: -1000});
        Matter.Body.setStatic(candy, true);

        setTimeout(() => {
            document.getElementById('win-screen').classList.remove('hidden');
            document.getElementById('hud').classList.add('hidden');

            // Populate stars in win screen
            const winStars = document.getElementById('win-stars');
            winStars.innerHTML = '';
            for(let i=0; i<3; i++) {
                let svg = `<svg class="star-icon ${i < score ? 'active' : ''}" viewBox="0 0 24 24" style="width: 50px; height: 50px;"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon></svg>`;
                winStars.innerHTML += svg;
            }
        }, 500);
    }

    function resetGame() {
        document.getElementById('game-over-screen').classList.add('hidden');
        document.getElementById('win-screen').classList.add('hidden');
        document.getElementById('hud').classList.remove('hidden');
        buildLevel();
        gameState = 'PLAYING';
    }

    // Init
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
    draw();

</script>
