            this.draw();

            // Update Attack Box position based on facing direction
            this.attackBox.position.y = this.position.y + 20;
            if (this.facingRight) {
                this.attackBox.position.x = this.position.x + this.width;
            } else {
                this.attackBox.position.x = this.position.x - this.attackBox.width;
            }

            // Movement & Physics
            this.position.x += this.velocity.x;
            this.position.y += this.velocity.y;

            // Gravity
            if (this.position.y + this.height + this.velocity.y >= groundLevel) {
                this.velocity.y = 0;
                this.position.y = groundLevel - this.height;
            } else {
                this.velocity.y += gravity;
            }

            // Screen bounds
            if (this.position.x < 0) this.position.x = 0;
            if (this.position.x + this.width > canvas.width) this.position.x = canvas.width - this.width;

            // Cooldowns
            if (this.attackCooldown > 0) this.attackCooldown--;
        }

        attack() {
            if (this.attackCooldown === 0 && !this.dead) {
                this.isAttacking = true;
                playSound('swing');
                setTimeout(() => {
                    this.isAttacking = false;
                }, 100);
                this.attackCooldown = 30; // Frames before next attack
            }
        }

        takeHit(damage) {
            this.health -= damage;
            this.hitFlashTimer = 10;
            playSound('hit');

            // Create blood/shadow particles
            for(let i=0; i<10; i++) {
                particles.push(new Particle({
                    position: {
                        x: this.position.x + this.width/2,
                        y: this.position.y + this.height/4
                    },
                    velocity: {
                        x: (Math.random() - 0.5) * 8,
                        y: (Math.random() - 0.5) * 8
                    },
                    color: 'red'
                }));
            }

            if (this.health <= 0) {
                this.health = 0;
                this.dead = true;
                determineWinner();
            }

            // Knockback
            this.velocity.y = -5;
            this.velocity.x = this.facingRight ? -5 : 5;
        }
    }

    // Instantiate Fighters
    let player;
    let enemy;

    function initFighters() {
        player = new Fighter({
            position: { x: 200, y: 0 },
            velocity: { x: 0, y: 0 },
            color: 'black' // Shadow style
        });

        enemy = new Fighter({
            position: { x: 750, y: 0 },
            velocity: { x: 0, y: 0 },
            color: '#1a1a1a', // Slightly off-black to distinguish if overlap
            isEnemy: true
        });
    }

    // Draw Background
    function drawBackground() {
        // Sunset gradient
        const bgGradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
        bgGradient.addColorStop(0, '#ff7b00');
        bgGradient.addColorStop(0.5, '#ff2a00');
        bgGradient.addColorStop(1, '#330000');
        ctx.fillStyle = bgGradient;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Ground
        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(0, groundLevel, canvas.width, canvas.height - groundLevel);

        // Distant mountains (Silhouette)
        ctx.beginPath();
        ctx.moveTo(0, groundLevel);
        ctx.lineTo(150, 300);
        ctx.lineTo(300, groundLevel);
        ctx.lineTo(600, 200);
        ctx.lineTo(900, groundLevel);
        ctx.lineTo(canvas.width, groundLevel);
        ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
        ctx.fill();
    }

    function enemyAI() {
        if (enemy.dead || player.dead) {
            enemy.velocity.x = 0;
            return;
        }

        const distanceX = player.position.x - enemy.position.x;

        // Face player
        enemy.facingRight = distanceX > 0;

        // Move towards player
        if (Math.abs(distanceX) > 100) {
            enemy.velocity.x = enemy.facingRight ? 3 : -3;
        } else {
            enemy.velocity.x = 0;
            // Attack randomly when close
            if (Math.random() < 0.05) {
                enemy.attack();
            }
        }
    }

    function animate() {
        if (gameState !== 'PLAYING') return;

        gameLoop = requestAnimationFrame(animate);

        drawBackground();

        // Handle Particles
        for (let i = particles.length - 1; i >= 0; i--) {
            const p = particles[i];
            if (p.alpha <= 0) {
                particles.splice(i, 1);
            } else {
                p.update();
            }
        }

        player.update();
        enemy.update();

        // Player Movement
        player.velocity.x = 0;
        if (!player.dead) {
            if (keys.a.pressed && player.lastKey === 'a') {
                player.velocity.x = -5;
                player.facingRight = false;
            } else if (keys.d.pressed && player.lastKey === 'd') {
                player.velocity.x = 5;
                player.facingRight = true;
            }
        }

        // Run AI
        enemyAI();

        // Collision Detection - Player attacks Enemy
        if (
            player.isAttacking &&
            rectangularCollision({ rectangle1: player, rectangle2: enemy })
        ) {
            player.isAttacking = false; // Only hit once per swing
            enemy.takeHit(10);
            enemyHealthBar.style.width = enemy.health + '%';
        }

        // Collision Detection - Enemy attacks Player
        if (
            enemy.isAttacking &&
            rectangularCollision({ rectangle1: enemy, rectangle2: player })
        ) {
            enemy.isAttacking = false;
            player.takeHit(10);
            playerHealthBar.style.width = player.health + '%';
        }
    }

    // Input Listeners
    window.addEventListener('keydown', (e) => {
        if (gameState !== 'PLAYING' || player.dead) return;

        switch (e.key.toLowerCase()) {
            case 'd':
                keys.d.pressed = true;
                player.lastKey = 'd';
                break;
            case 'a':
                keys.a.pressed = true;
                player.lastKey = 'a';
                break;
            case 'w':
                if (player.velocity.y === 0) player.velocity.y = -15; // Jump
                break;
            case ' ': // Spacebar to attack
                player.attack();
                break;
        }
    });

    window.addEventListener('keyup', (e) => {
        switch (e.key.toLowerCase()) {
            case 'd':
                keys.d.pressed = false;
                break;
            case 'a':
                keys.a.pressed = false;
                break;
        }
    });

    // Game Control Functions
    function startGame() {
        startScreen.style.display = 'none';
        gameState = 'PLAYING';
        initFighters();
        drawBackground(); // Initial draw
        decreaseTimer();
        animate();

        // Initial setup to ensure audio context is unblocked
        if (audioCtx.state === 'suspended') audioCtx.resume();
    }

    function resetGame() {
        gameOverScreen.style.display = 'none';
        timer = 60;
        timerElem.innerText = timer;
        playerHealthBar.style.width = '100%';
        enemyHealthBar.style.width = '100%';
        particles.length = 0;
        gameState = 'PLAYING';
        initFighters();
        decreaseTimer();
        animate();
    }

    // Initial Render behind start screen
    initFighters();
    drawBackground();
    player.draw();
    enemy.draw();

</script>
</body>
</html>
