    <script>
        /**
         * Aletheia Engine
         * Handles the unconcealing mechanic, canvas rendering, and audio.
         */

        const State = {
            START: 0,
            PLAYING: 1,
            END: 2
        };

        let currentState = State.START;

        // Elements
        const startScreen = document.getElementById('start-screen');
        const endScreen = document.getElementById('end-screen');
        const startBtn = document.getElementById('start-btn');
        const canvas = document.getElementById('gestell-canvas');
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        const truthLayer = document.getElementById('truth-layer');
        const interactionLayer = document.getElementById('interaction-layer');
        const progressFill = document.getElementById('progress-fill');

        // Audio Setup
        let audioCtx;
        let droneOsc;
        let droneGain;
        let filter;

        // Mechanics
        let pointer = { x: -1000, y: -1000, active: false };
        let brushSize = 80;
        let docHeight = 0;
        let asciiChars = "01010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101"; // Matrix vibe

        function initAudio() {
            try {
                audioCtx = new (window.AudioContext || window.webkitAudioContext)();

                // Base Drone
                droneOsc = audioCtx.createOscillator();
                droneOsc.type = 'sawtooth';
                droneOsc.frequency.setValueAtTime(45, audioCtx.currentTime); // Low sub drone

                // Filter to make it muddy initially
                filter = audioCtx.createBiquadFilter();
                filter.type = 'lowpass';
                filter.frequency.setValueAtTime(200, audioCtx.currentTime);
                filter.Q.value = 1;

                droneGain = audioCtx.createGain();
                droneGain.gain.setValueAtTime(0, audioCtx.currentTime);
                droneGain.gain.linearRampToValueAtTime(0.15, audioCtx.currentTime + 2);

                droneOsc.connect(filter);
                filter.connect(droneGain);
                droneGain.connect(audioCtx.destination);

                droneOsc.start();
            } catch (e) {
                console.log("Audio not supported or blocked");
            }
        }

        function updateAudioFilter(scrollRatio) {
            if (!filter) return;
            // As user scrolls down, open the filter to reveal higher frequencies (clearing)
            const minFreq = 200;
            const maxFreq = 2000;
            const newFreq = minFreq + (maxFreq - minFreq) * scrollRatio;
            filter.frequency.setTargetAtTime(newFreq, audioCtx.currentTime, 0.1);

            // Adjust pitch slightly for tension release
            const baseFreq = 45;
            droneOsc.frequency.setTargetAtTime(baseFreq + (scrollRatio * 10), audioCtx.currentTime, 0.1);
        }

        function resizeCanvas() {
            // Need to cover the entire scrollable height
            docHeight = Math.max(
                document.body.scrollHeight, document.documentElement.scrollHeight,
                document.body.offsetHeight, document.documentElement.offsetHeight,
                document.body.clientHeight, document.documentElement.clientHeight
            );

            // If canvas is already sized and doc height hasn't changed much, don't redraw
            // to preserve the user's "scratchings"
            if (Math.abs(canvas.height - docHeight) < 50 && canvas.width === window.innerWidth) {
                return; 
            }

            // Save current state to restore if resizing
            let tempCanvas;
            if (canvas.width > 0 && canvas.height > 0) {
                tempCanvas = document.createElement('canvas');
                tempCanvas.width = canvas.width;
                tempCanvas.height = canvas.height;
                tempCanvas.getContext('2d').drawImage(canvas, 0, 0);
            }

            canvas.width = window.innerWidth;
            canvas.height = docHeight;
            interactionLayer.style.height = `${docHeight}px`;

            drawGestellBackground();

            // Restore
            if (tempCanvas) {
                ctx.globalCompositeOperation = 'destination-out';
                ctx.drawImage(tempCanvas, 0, 0);
                ctx.globalCompositeOperation = 'source-over';
            }

            // Adjust brush size based on screen
            brushSize = window.innerWidth < 768 ? 60 : 100;
        }

        function drawGestellBackground() {
            // Fill with dark matrix green/black
            ctx.fillStyle = '#050a05';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw noise
            ctx.fillStyle = 'rgba(20, 100, 30, 0.4)';
            ctx.font = '14px "Fira Code", monospace';

            const cols = Math.floor(canvas.width / 14);
            const rows = Math.floor(canvas.height / 20);

            for (let i = 0; i < cols; i++) {
                for (let j = 0; j < rows; j++) {
                    if (Math.random() > 0.3) {
                        const char = asciiChars[Math.floor(Math.random() * asciiChars.length)];
                        ctx.fillText(char, i * 14, j * 20);
                    }
                }
            }
        }

        function startGame() {
            startScreen.classList.add('hidden');
            setTimeout(() => {
                startScreen.style.display = 'none';
            }, 2000);

            currentState = State.PLAYING;
            initAudio();
            resizeCanvas();

            // Start continuous noise update loop for the non-cleared areas
            requestAnimationFrame(animateNoise);
        }

        // Add subtle shifting to the background to represent the active system
        let lastFrame = 0;
        function animateNoise(timestamp) {
            if (currentState !== State.PLAYING) return;

            if (timestamp - lastFrame > 100) { // Update every 100ms
                // Only update a small random portion to save performance
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = '#050a05';
                ctx.font = '14px "Fira Code", monospace';

                for(let k=0; k<50; k++) {
                    let x = Math.random() * canvas.width;
                    let y = Math.random() * canvas.height;

                    // Check if this area is already cleared (crude check by reading pixel alpha)
                    // Reading pixels is slow, so we just blindly draw over. 
                    // To prevent drawing over cleared text, we rely on the continuous erasing below.
                    // Actually, a better way is to draw noise to an offscreen canvas and mask it, 
                    // but for simplicity, we'll skip animated noise and rely on the static texture + user interaction.
                    // The static texture feels more like a solid wall to break down.
                }
                lastFrame = timestamp;
            }

            // Apply easing to continuous erasing if pointer is active
            if (pointer.active) {
                erase(pointer.x, pointer.y);
            }

            requestAnimationFrame(animateNoise);
        }

        function erase(x, y) {
            ctx.globalCompositeOperation = 'destination-out';

            // Create radial gradient for smooth edges
            const grad = ctx.createRadialGradient(x, y, brushSize * 0.2, x, y, brushSize);
            grad.addColorStop(0, 'rgba(0,0,0,1)');
            grad.addColorStop(1, 'rgba(0,0,0,0)');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(x, y, brushSize, 0, Math.PI * 2);
            ctx.fill();

            ctx.globalCompositeOperation = 'source-over'; // Reset
        }

        function handleMove(e) {
            if (currentState !== State.PLAYING) return;

            let clientX, clientY;
            if (e.touches) {
                clientX = e.touches[0].clientX;
                clientY = e.touches[0].clientY;
            } else {
                clientX = e.clientX;
                clientY = e.clientY;
            }

            // Calculate exact position on canvas considering scroll
            pointer.x = clientX;
            pointer.y = clientY + window.scrollY;
            pointer.active = true;

            erase(pointer.x, pointer.y);
        }

        function handleEnd() {
            pointer.active = false;
        }

        function checkProgress() {
            if (currentState !== State.PLAYING) return;

            const scrollY = window.scrollY;
            const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
            let ratio = 0;

            if (maxScroll > 0) {
                ratio = scrollY / maxScroll;
            }

            progressFill.style.width = `${ratio * 100}%`;
            updateAudioFilter(ratio);

            // Check End Condition
            if (ratio >= 0.98) {
                triggerEnd();
            }
        }

        function triggerEnd() {
            currentState = State.END;
            endScreen.style.display = 'flex';
            setTimeout(() => {
                endScreen.classList.remove('hidden');

                // Fade out drone, play final chord
                if (droneGain) {
                    droneGain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 3);
                }
            }, 100);
        }

        // Event Listeners
        startBtn.addEventListener('click', startGame);

        window.addEventListener('mousemove', handleMove, { passive: true });
        window.addEventListener('touchmove', handleMove, { passive: true });
        window.addEventListener('touchstart', handleMove, { passive: true });
        window.addEventListener('touchend', handleEnd);

        window.addEventListener('scroll', () => {
            checkProgress();
            // Optional: simulate revealing as you scroll down blindly
            // pointer.x = window.innerWidth / 2;
            // pointer.y = window.scrollY + (window.innerHeight / 2);
            // erase(pointer.x, pointer.y);
        }, { passive: true });

        window.addEventListener('resize', () => {
            if(currentState === State.PLAYING) {
                resizeCanvas();
            }
        });

        // Initialize empty canvas on load
        resizeCanvas();

    </script>
</body>
</html>
