<script>
    // --- Engine & Canvas Setup ---
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;

    window.addEventListener('resize', () => {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    });

    // --- Audio System ---
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    let engineOsc, engineGain;

    function initAudio() {
        if(audioCtx.state === 'suspended') audioCtx.resume();
        if(!engineOsc) {
            engineOsc = audioCtx.createOscillator();
            engineOsc.type = 'sawtooth';
            engineGain = audioCtx.createGain();
            engineGain.gain.value = 0;

            // Simple lowpass filter to muffle the harsh sawtooth
            const filter = audioCtx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.value = 1000;

            engineOsc.connect(filter);
            filter.connect(engineGain);
            engineGain.connect(audioCtx.destination);
            engineOsc.start();
        }
    }

    function updateAudio(speedStr, maxSpeed) {
        if(!engineOsc) return;
        const speedRatio = speedStr / maxSpeed;
        // Pitch mapping
        engineOsc.frequency.setTargetAtTime(100 + (speedRatio * 300), audioCtx.currentTime, 0.1);
        // Volume mapping
        engineGain.gain.setTargetAtTime(0.05 + (speedRatio * 0.1), audioCtx.currentTime, 0.1);
    }

    function playBoostSound() {
        if(!audioCtx) return;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'square';
        osc.frequency.setValueAtTime(400, audioCtx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(800, audioCtx.currentTime + 0.5);
        gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.5);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.5);
    }

    // --- Constants & Config ---
    const fps = 60;
    const step = 1/fps;
    const roadWidth = 2000;
    const segmentLength = 200;
    const rumbleLength = 3;
    const drawDistance = 300;
    const fieldOfView = 100;
    const cameraHeight = 1000;
    const cameraDepth = 1 / Math.tan((fieldOfView/2) * Math.PI/180);
    const maxSpeed = segmentLength/step;
    const accel =  maxSpeed/5;
    const breaking = -maxSpeed;
    const decel = -maxSpeed/5;
    const offRoadDecel = -maxSpeed/2;
    const offRoadLimit = maxSpeed/4;
    const totalLaps = 3;

    // --- Colors (Neon Synthwave Palette) ---
    const COLORS = {
        SKY: '#050510',
        TREE: '#000000',
        FOG: '#050510',
        LIGHT: { road: '#1a1a2e', grass: '#0a0a1a', rumble: '#00ffff', lane: '#ff00ff' },
        DARK:  { road: '#111122', grass: '#050510', rumble: '#005555' },
        START: { road: '#ffffff', grass: '#0a0a1a', rumble: '#ffffff' }
    };

    // --- Game State Variables ---
    let segments = [];
    let trackLength = 0;
    let position = 0;      // camera Z
    let playerX = 0;       // player X offset from center of road (-1 to 1)
    let playerZ = cameraHeight * cameraDepth; // player relative Z
    let speed = 0;
    let currentLap = 1;
    let lapTime = 0;
    let bestLapTime = 9999;
    let totalTime = 0;
    let isPlaying = false;

    // Boost system
    let boostAmount = 100;
    let isBoosting = false;

    // Input state
    let keys = { ArrowUp:false, ArrowDown:false, ArrowLeft:false, ArrowRight:false, w:false, a:false, s:false, d:false, Shift:false };

    // --- Track Generation ---
    function resetRoad() {
        segments = [];

        const ROAD = {LENGTH: {NONE: 0, SHORT: 25, MEDIUM: 50, LONG: 100}, CURVE: {NONE: 0, EASY: 2, MEDIUM: 4, HARD: 6}};

        function addSegment(curve, y) {
            const n = segments.length;
            segments.push({
                index: n,
                p1: { world: { y: lastY(), z:  n   *segmentLength }, camera: {}, screen: {} },
                p2: { world: { y: y,       z: (n+1)*segmentLength }, camera: {}, screen: {} },
                curve: curve,
                color: Math.floor(n/rumbleLength)%2 ? COLORS.DARK : COLORS.LIGHT
            });
        }

        function lastY() { return (segments.length === 0) ? 0 : segments[segments.length-1].p2.world.y; }

        function addRoad(enter, hold, leave, curve, y) {
            const startY = lastY();
            const endY = startY + (y * segmentLength);
            let n;
            for(n=0; n<enter; n++) addSegment(easeIn(0, curve, n/enter), easeInOut(startY, endY, n/(enter+hold+leave)));
            for(n=0; n<hold;  n++) addSegment(curve, easeInOut(startY, endY, (enter+n)/(enter+hold+leave)));
            for(n=0; n<leave; n++) addSegment(easeInOut(curve, 0, n/leave), easeInOut(startY, endY, (enter+hold+n)/(enter+hold+leave)));
        }

        function addStraight(num) { addRoad(num, num, num, 0, 0); }
        function addCurve(num, curve, height) { addRoad(num, num, num, curve, height); }
        function easeIn(a,b,percent) { return a + (b-a)*Math.pow(percent,2); }
        function easeInOut(a,b,percent) { return a + (b-a)*((-Math.cos(percent*Math.PI)/2) + 0.5); }

        // Build Track (Procedural-ish)
        addStraight(ROAD.LENGTH.SHORT);
        addCurve(ROAD.LENGTH.MEDIUM, ROAD.CURVE.EASY, 0);
        addStraight(ROAD.LENGTH.SHORT);
        addCurve(ROAD.LENGTH.LONG, ROAD.CURVE.MEDIUM, 20);
        addCurve(ROAD.LENGTH.LONG, -ROAD.CURVE.MEDIUM, -20);
        addStraight(ROAD.LENGTH.MEDIUM);
        addCurve(ROAD.LENGTH.SHORT, ROAD.CURVE.HARD, 40);
        addStraight(ROAD.LENGTH.SHORT);
        addCurve(ROAD.LENGTH.LONG, -ROAD.CURVE.HARD, -40);
        addStraight(ROAD.LENGTH.LONG);

        // Start line color
        for(let n=0; n<rumbleLength; n++) segments[segments.length-1-n].color = COLORS.START;

        trackLength = segments.length * segmentLength;
    }

    // --- Math & Projection ---
    function project(p, cameraX, cameraY, cameraZ, cameraDepth, width, height, roadWidth) {
        p.camera.x     = (p.world.x || 0) - cameraX;
        p.camera.y     = (p.world.y || 0) - cameraY;
        p.camera.z     = (p.world.z || 0) - cameraZ;
        p.screen.scale = cameraDepth/p.camera.z;
        p.screen.x     = Math.round((width/2)  + (p.screen.scale * p.camera.x  * width/2));
        p.screen.y     = Math.round((height/2) - (p.screen.scale * p.camera.y  * height/2));
        p.screen.w     = Math.round(             (p.screen.scale * roadWidth   * width/2));
    }

    function findSegment(z) {
        return segments[Math.floor(z/segmentLength) % segments.length];
    }

    // --- Core Game Loop ---
    let lastTime = 0;

    function frame(time) {
        if(!isPlaying) return;

        let dt = (time - lastTime) / 1000;
        if(dt > 0.1) dt = 0.1; // cap dt
        lastTime = time;

        update(step); // Fixed timestep update
        render();

        requestAnimationFrame(frame);
    }

    function update(dt) {
        let playerSegment = findSegment(position+playerZ);
        let speedPercent  = speed/maxSpeed;
        let dx            = dt * 2 * speedPercent; // steering speed
        let startPosition = position;

        // --- Controls ---
        let accelerating = keys.ArrowUp || keys.w;
        let braking      = keys.ArrowDown || keys.s;
        let left         = keys.ArrowLeft || keys.a;
        let right        = keys.ArrowRight || keys.d;

        isBoosting = (keys.Shift) && boostAmount > 0 && speed > 0;

        if (left)  playerX = playerX - dx;
        else if (right) playerX = playerX + dx;

        // Centrifugal force
        playerX = playerX - (dx * speedPercent * playerSegment.curve * 3);

        // --- Physics ---
        let currentMaxSpeed = maxSpeed;
        let currentAccel = accel;

        if(isBoosting) {
            currentMaxSpeed = maxSpeed * 1.5;
            currentAccel = accel * 2;
            boostAmount -= dt * 20;
        } else {
            if(boostAmount < 100) boostAmount += dt * 5; // recharge
        }

        if (accelerating) {
            speed += currentAccel * dt;
        } else if (braking) {
            speed += breaking * dt;
        } else {
            speed += decel * dt;
        }

        // Off road physics
        if ((playerX < -1 || playerX > 1)) {
            if (speed > offRoadLimit) speed += offRoadDecel * dt;
            // Bumpiness off-road
            playerZ = cameraHeight * cameraDepth + (Math.random() * 20 - 10);
        } else {
            playerZ = cameraHeight * cameraDepth; // smooth on road
        }

        // Clamp speed
        speed = Math.max(0, Math.min(speed, currentMaxSpeed));

        // Move forward
        position += speed * dt;

        // Lap logic
        if (position > trackLength) {
            position -= trackLength;
            if(lapTime > 0) {
                if(lapTime < bestLapTime) bestLapTime = lapTime;
                currentLap++;
                if(currentLap > totalLaps) {
                    endGame();
                }
            }
            lapTime = 0;
        }

        lapTime += dt;
        totalTime += dt;

        updateAudio(speed, maxSpeed);
        updateUI();
    }

    // --- Rendering ---
    function render() {
        ctx.fillStyle = COLORS.SKY;
        ctx.fillRect(0, 0, width, height);

        // Draw background elements (Stars/Grid for Synthwave feel)
        drawBackground();

        let baseSegment = findSegment(position);
        let basePercent = (position%segmentLength)/segmentLength;
        let playerSegment = findSegment(position+playerZ);
        let playerPercent = ((position+playerZ)%segmentLength)/segmentLength;
        let playerY = interpolate(playerSegment.p1.world.y, playerSegment.p2.world.y, playerPercent);
        let maxy = height;

        let x  = 0;
        let dx = - (baseSegment.curve * basePercent);

        // Render Track
        for(let n=0; n<drawDistance; n++) {
            let segment = segments[(baseSegment.index + n) % segments.length];
            segment.looped = segment.index < baseSegment.index;
            segment.fog = exponentialFog(n/drawDistance, 3);
            segment.clip = maxy;

            project(segment.p1, (playerX * roadWidth) - x,      playerY + cameraHeight, position - (segment.looped ? trackLength : 0), cameraDepth, width, height, roadWidth);
            project(segment.p2, (playerX * roadWidth) - x - dx, playerY + cameraHeight, position - (segment.looped ? trackLength : 0), cameraDepth, width, height, roadWidth);

            x  = x + dx;
            dx = dx + segment.curve;

            if ((segment.p1.camera.z <= cameraDepth) || (segment.p2.screen.y >= maxy) || (segment.p2.screen.y >= segment.p1.screen.y))
                continue;

            RenderSegment(ctx, width, 
                segment.color.grass, segment.color.rumble, segment.color.road,
                segment.p1.screen.x, segment.p1.screen.y, segment.p1.screen.w,
                segment.p2.screen.x, segment.p2.screen.y, segment.p2.screen.w, segment.fog
            );

            // Center lane markings
            if(segment.color.lane && (segment.index % 4 === 0 || segment.index % 4 === 1)) {
                let laneW1 = segment.p1.screen.w * 0.02;
                let laneW2 = segment.p2.screen.w * 0.02;
                RenderPolygon(ctx, 
                    segment.p1.screen.x - laneW1/2, segment.p1.screen.y, 
                    segment.p1.screen.x + laneW1/2, segment.p1.screen.y,
                    segment.p2.screen.x + laneW2/2, segment.p2.screen.y, 
                    segment.p2.screen.x - laneW2/2, segment.p2.screen.y, 
                    segment.color.lane);
            }

            maxy = segment.p1.screen.y;
        }

        // Draw Player Car
        drawCar();
    }

    function RenderSegment(ctx, width, colorGrass, colorRumble, colorRoad, x1, y1, w1, x2, y2, w2, fog) {
        // Grass
        ctx.fillStyle = colorGrass;
        ctx.fillRect(0, y2, width, y1 - y2);

        // Rumble
        let r1 = w1/Math.max(6, 2*w1/100);
        let r2 = w2/Math.max(6, 2*w2/100);
        RenderPolygon(ctx, x1-w1-r1, y1, x1-w1, y1, x2-w2, y2, x2-w2-r2, y2, colorRumble);
        RenderPolygon(ctx, x1+w1+r1, y1, x1+w1, y1, x2+w2, y2, x2+w2+r2, y2, colorRumble);

        // Road
        RenderPolygon(ctx, x1-w1, y1, x1+w1, y1, x2+w2, y2, x2-w2, y2, colorRoad);

        // Fog
        if (fog > 0 && fog < 1) {
            RenderPolygon(ctx, 0, y1, width, y1, width, y2, 0, y2, `rgba(5,5,16,${fog})`);
        }
    }

    function RenderPolygon(ctx, x1, y1, x2, y2, x3, y3, x4, y4, color) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.lineTo(x3, y3); ctx.lineTo(x4, y4);
        ctx.closePath();
        ctx.fill();
    }

    function drawBackground() {
        // Neon Sun
        ctx.beginPath();
        ctx.arc(width/2, height/2 + 50, 150, 0, Math.PI, true);

        // Gradient for sun
        let grad = ctx.createLinearGradient(0, height/2 - 100, 0, height/2 + 50);
        grad.addColorStop(0, '#ff00ff');
        grad.addColorStop(1, '#ffaa00');
        ctx.fillStyle = grad;
        ctx.fill();

        // Sun lines
        ctx.fillStyle = COLORS.SKY;
        for(let i=0; i<5; i++) {
            ctx.fillRect(width/2 - 200, height/2 + 10 - i*15, 400, 4 + i*2);
        }

        // Horizon line glow
        ctx.shadowBlur = 20;
        ctx.shadowColor = '#0ff';
        ctx.strokeStyle = '#0ff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, height/2);
        ctx.lineTo(width, height/2);
        ctx.stroke();
        ctx.shadowBlur = 0;
    }

    function drawCar() {
        const carW = 160;
        const carH = 60;
        const destX = width/2;
        const destY = height - 120 - (playerZ - cameraHeight*cameraDepth)*0.2; // slight vertical bounce

        ctx.save();
        ctx.translate(destX, destY);

        // Tilt based on steering/curve
        let tilt = (keys.ArrowLeft || keys.a) ? -0.1 : (keys.ArrowRight || keys.d) ? 0.1 : 0;
        ctx.rotate(tilt);

        // Car Body (Stylized Synthwave Car)
        ctx.fillStyle = '#111';
        ctx.strokeStyle = isBoosting ? '#0ff' : '#f0f'; // Change color on boost
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = ctx.strokeStyle;

        // Base
        ctx.beginPath();
        ctx.moveTo(-carW/2, carH/2);
        ctx.lineTo(carW/2, carH/2);
        ctx.lineTo(carW/2 - 20, -carH/2);
        ctx.lineTo(-carW/2 + 20, -carH/2);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Windshield
        ctx.fillStyle = '#0ff';
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.moveTo(-carW/4, -10);
        ctx.lineTo(carW/4, -10);
        ctx.lineTo(carW/4 - 10, -carH/2 + 5);
        ctx.lineTo(-carW/4 + 10, -carH/2 + 5);
        ctx.closePath();
        ctx.fill();

        // Taillights
        ctx.fillStyle = '#f00';
        ctx.shadowColor = '#f00';
        ctx.shadowBlur = 20;
        ctx.fillRect(-carW/2 + 10, carH/2 - 15, 30, 10);
        ctx.fillRect(carW/2 - 40, carH/2 - 15, 30, 10);

        // Boost Flames
        if(isBoosting) {
            ctx.fillStyle = '#0ff';
            ctx.shadowColor = '#fff';
            ctx.beginPath();
            ctx.moveTo(-carW/2 + 25, carH/2);
            ctx.lineTo(-carW/2 + 25, carH/2 + 20 + Math.random()*20);
            ctx.lineTo(-carW/2 + 15, carH/2);
            ctx.fill();

            ctx.beginPath();
            ctx.moveTo(carW/2 - 25, carH/2);
            ctx.lineTo(carW/2 - 25, carH/2 + 20 + Math.random()*20);
