        // --- Object Materials ---
        const cloudMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, transparent: true, opacity: 0.8 });
        const towerMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const fuelMat = new THREE.MeshStandardMaterial({ color: 0x00ff00, emissive: 0x00aa00 });
        const coinMat = new THREE.MeshStandardMaterial({ color: 0xffd700, emissive: 0xaa8800 });

        // --- Functions ---

        function getTargetPosition() {
            return {
                x: targetLane * LANE_WIDTH,
                y: 3 + (targetAlt * ALT_STEP),
