        function spawnObstacle(zPos) {
            const lane = Math.floor(Math.random() * 3) - 1;
            const alt = Math.floor(Math.random() * 3) - 1;

            let mesh;
            const type = Math.random() > 0.5 ? 'cloud' : 'tower';
            let radius = 1.5;

            if (type === 'cloud') {
                mesh = new THREE.Mesh(new THREE.DodecahedronGeometry(2), cloudMat);
                mesh.position.set(lane * LANE_WIDTH, 3 + (alt * ALT_STEP), zPos);
                radius = 2;
            } else {
                mesh = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.5, 10), towerMat);
                // Towers come from ground, so alt is fixed relative to ground
                mesh.position.set(lane * LANE_WIDTH, 0, zPos);
                radius = 1.5;
            }

            mesh.castShadow = true;
            mesh.receiveShadow = true;
            scene.add(mesh);
            activeObstacles.push({ mesh, type, radius });
        }

        function spawnCollectible(zPos) {
            const lane = Math.floor(Math.random() * 3) - 1;
            const alt = Math.floor(Math.random() * 3) - 1;

            const isFuel = Math.random() > 0.7; // 30% chance for fuel, 70% for coin
            let mesh, radius;

            if (isFuel) {
                mesh = new THREE.Mesh(new THREE.OctahedronGeometry(0.8), fuelMat);
