            const length = 50;
            // Spawn 1-2 obstacles per chunk
            for(let i=0; i<2; i++) {
                if(Math.random() > 0.3) spawnObstacle(zStart - Math.random() * length);
            }
            // Spawn 1-3 collectibles
            for(let i=0; i<3; i++) {
                if(Math.random() > 0.2) spawnCollectible(zStart - Math.random() * length);
            }
        }

        function resetGame() {
            score = 0;
