            [...activeObstacles, ...activeCollectibles].forEach(obj => {
                scene.remove(obj.mesh);
                if(obj.mesh.geometry) obj.mesh.geometry.dispose();
            });
            activeObstacles.length = 0;
            activeCollectibles.length = 0;

            // Generate initial path
            for(let i=1; i<=4; i++) {
                generateChunk(-i * 50);
