        function checkCollisions() {
            const pBox = new THREE.Box3().setFromObject(body);

            // Obstacles
            for (let i = activeObstacles.length - 1; i >= 0; i--) {
                const obs = activeObstacles[i];
                // Simple distance check for performance
                const dist = playerGroup.position.distanceTo(obs.mesh.position);

                if (dist < obs.radius + 1.0) {
                    gameOver(obs.type === 'cloud' ? 'Flew into a storm!' : 'Hit a tower!');
                    return;
                }
            }

            // Collectibles
            for (let i = activeCollectibles.length - 1; i >= 0; i--) {
                const col = activeCollectibles[i];
                const dist = playerGroup.position.distanceTo(col.mesh.position);

                if (dist < col.radius + 1.5) {
                    if (col.isFuel) {
                        fuel = Math.min(MAX_FUEL, fuel + 25);
                        playSound('fuel');
                    } else {
                        score += 50;
                        playSound('coin');
                    }

                    scene.remove(col.mesh);
                    activeCollectibles.splice(i, 1);
                    updateUI();
                }
            }
        }

        function gameOver(reason) {
            gameState = 'OVER';
            playSound('crash');
            document.getElementById('hud').classList.add('hidden');
            document.getElementById('gameOverScreen').classList.remove('hidden');
