        // --- Main Loop ---
        function animate(currentTime) {
            requestAnimationFrame(animate);

            if (!lastTime) lastTime = currentTime;
            const dt = (currentTime - lastTime) / 1000; // Delta time in seconds
            lastTime = currentTime;

            if (gameState === 'PLAY') {
                // Logic updates
                distanceTraveled += currentSpeed * dt;
                score += currentSpeed * dt * 0.1;
                fuel -= 5 * dt; // Consume fuel
                currentSpeed += 0.5 * dt; // Gradually increase speed

                if (fuel <= 0) {
                    gameOver('Out of Fuel!');
                }

                // Animate Propeller
                propeller.rotation.z += 20 * dt;

                // Move Player (Lerp to target)
                const targetPos = getTargetPosition();
                playerGroup.position.x += (targetPos.x - playerGroup.position.x) * 10 * dt;
                playerGroup.position.y += (targetPos.y - playerGroup.position.y) * 10 * dt;

                // Banking animation based on horizontal movement
                const bankAngle = (targetPos.x - playerGroup.position.x) * -0.2;
                playerGroup.rotation.z += (bankAngle - playerGroup.rotation.z) * 10 * dt;

                // Pitch animation based on vertical movement
                const pitchAngle = (targetPos.y - playerGroup.position.y) * 0.2;
                playerGroup.rotation.x += (pitchAngle - playerGroup.rotation.x) * 10 * dt;

                // Move world (objects towards player +Z)
                const moveDist = currentSpeed * dt;

                const updateObjArray = (arr) => {
                    for (let i = arr.length - 1; i >= 0; i--) {
                        arr[i].mesh.position.z += moveDist;

                        // Rotate coins
                        if(arr[i].mesh.geometry.type === 'TorusGeometry') {
                            arr[i].mesh.rotation.y += 3 * dt;
                        }

                        // Remove passed objects
                        if (arr[i].mesh.position.z > 10) {
                            scene.remove(arr[i].mesh);
                            arr.splice(i, 1);
                        }
                    }
                };

                updateObjArray(activeObstacles);
                updateObjArray(activeCollectibles);

                // Spawn new chunks
                if (Math.floor(distanceTraveled) % 50 === 0) {
                    generateChunk(-150); // Spawn ahead
                    distanceTraveled++; // prevent multiple triggers
                }

                checkCollisions();

                // Throttle UI updates slightly
                if(Math.random() < 0.2) updateUI();
            }

            renderer.render(scene, camera);
        }

        // --- Input Handling ---
        function handleMove(dir) {
            if (gameState !== 'PLAY') return;
            if (dir === 'LEFT' && targetLane > -1) targetLane--;
            if (dir === 'RIGHT' && targetLane < 1) targetLane++;
            if (dir === 'UP' && targetAlt < 1) targetAlt++;
            if (dir === 'DOWN' && targetAlt > -1) targetAlt--;
        }

        window.addEventListener('keydown', (e) => {
            switch(e.key.toLowerCase()) {
                case 'a': case 'arrowleft': handleMove('LEFT'); break;
                case 'd': case 'arrowright': handleMove('RIGHT'); break;
                case 'w': case 'arrowup': handleMove('UP'); break;
                case 's': case 'arrowdown': handleMove('DOWN'); break;
            }
        });

        // Touch/Swipe controls
        let touchStartX = 0;
        let touchStartY = 0;

        window.addEventListener('touchstart', e => {
            touchStartX = e.changedTouches[0].screenX;
            touchStartY = e.changedTouches[0].screenY;
        }, {passive: false});

        window.addEventListener('touchend', e => {
            if (gameState !== 'PLAY') return;
            const touchEndX = e.changedTouches[0].screenX;
            const touchEndY = e.changedTouches[0].screenY;

            const dx = touchEndX - touchStartX;
            const dy = touchEndY - touchStartY;

            // Determine dominant swipe direction
            if (Math.abs(dx) > Math.abs(dy)) {
                if (Math.abs(dx) > 30) { // Threshold
                    if (dx > 0) handleMove('RIGHT');
                    else handleMove('LEFT');
                }
            } else {
                if (Math.abs(dy) > 30) {
                    if (dy > 0) handleMove('DOWN'); // Swipe down to dive
                    else handleMove('UP'); // Swipe up to climb
                }
            }
        }, {passive: false});

        // Prevent default touch actions (scrolling)
        document.addEventListener('touchmove', function(e) { e.preventDefault(); }, { passive: false });

        // --- UI Buttons ---
        document.getElementById('startBtn').addEventListener('click', () => {
            audioCtx.resume();
            document.getElementById('startScreen').classList.add('hidden');
            document.getElementById('hud').classList.remove('hidden');
            resetGame();
            gameState = 'PLAY';
        });

        document.getElementById('restartBtn').addEventListener('click', () => {
            document.getElementById('gameOverScreen').classList.add('hidden');
            document.getElementById('hud').classList.remove('hidden');
            resetGame();
            gameState = 'PLAY';
        });

        // Window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start loop
        requestAnimationFrame(animate);

    </script>
