        }

        button:active {
            transform: scale(0.95);
        }

        /* HUD */
        #hud {
            position: absolute;
            top: 10px;
            left: 10px;
            z-index: 5;
            pointer-events: none;
        }

        .health-bar-container {
            width: 200px;
            height: 20px;
            background: #333;
            border: 2px solid #000;
            margin-bottom: 10px;
        }

        #healthBar {
            width: 100%;
            height: 100%;
            background: #e74c3c;
            transition: width 0.2s;
        }

        /* Hotbar */
        #hotbar {
            position: absolute;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 5px;
            z-index: 5;
        }

        .slot {
            width: 50px;
            height: 50px;
            background: rgba(0, 0, 0, 0.5);
            border: 2px solid #fff;
            display: flex;
            justify-content: center;
            align-items: center;
            cursor: pointer;
            position: relative;
        }

        .slot.active {
            border-color: #f1c40f;
            box-shadow: 0 0 10px #f1c40f;
        }

        .slot-num {
            position: absolute;
            top: 2px;
            left: 2px;
            font-size: 8px;
        }

        #mobile-controls {
            display: none;
            position: absolute;
            bottom: 80px;
            width: 100%;
            justify-content: space-between;
            padding: 0 20px;
            z-index: 5;
        }

        .btn-group { display: flex; gap: 10px; }
        .m-btn {
            width: 60px; height: 60px;
            background: rgba(255,255,255,0.2);
            border: 2px solid rgba(255,255,255,0.5);
            border-radius: 50%;
            color: white; font-size: 20px; font-weight: bold;
        }

        @media (max-width: 768px) {
            #mobile-controls { display: flex; }
            h1 { font-size: 2rem; }
            .slot { width: 40px; height: 40px; }
        }
    </style>
</head>
<body>

    <!-- Start Screen -->
    <div id="startScreen" class="overlay">
        <h1>Webaria</h1>
        <p>A miniature sandbox RPG.</p>
        <p>WASD / Arrows to move & jump.<br>Click to mine/attack.<br>Right-click or Shift+Click to place blocks.<br>1-4 to select blocks.</p>
        <button id="startBtn">PLAY GAME</button>
    </div>

    <!-- Game Over Screen -->
    <div id="gameOverScreen" class="overlay hidden">
        <h1 style="color: #e74c3c;">YOU DIED</h1>
        <button id="restartBtn">RESPAWN</button>
    </div>

    <!-- HUD -->
    <div id="hud" class="hidden">
        <div class="health-bar-container">
            <div id="healthBar"></div>
        </div>
        <div style="font-size: 10px;">Score: <span id="scoreDisplay">0</span></div>
    </div>

    <!-- Hotbar -->
    <div id="hotbar" class="hidden">
        <!-- Filled by JS -->
    </div>

    <div id="mobile-controls" class="hidden">
        <div class="btn-group">
            <button class="m-btn" id="btn-left">←</button>
            <button class="m-btn" id="btn-right">→</button>
        </div>
        <div class="btn-group">
            <button class="m-btn" id="btn-action" style="border-radius:10px; width: 80px;">MINE</button>
            <button class="m-btn" id="btn-jump">↑</button>
        </div>
    </div>

    <canvas id="gameCanvas"></canvas>

    <script>
        /**
         * Webaria - HTML5 Canvas Terraria-like Game
         */

        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d', { alpha: false }); // Optimize

        // UI Elements
        const startScreen = document.getElementById('startScreen');
        const gameOverScreen = document.getElementById('gameOverScreen');
        const hud = document.getElementById('hud');
        const hotbarUI = document.getElementById('hotbar');
        const healthBar = document.getElementById('healthBar');
        const scoreDisplay = document.getElementById('scoreDisplay');
        const mobileControls = document.getElementById('mobile-controls');

        // Game Configuration
        const TILE_SIZE = 32;
        const CHUNK_WIDTH = 64;
        const CHUNK_HEIGHT = 64; // Max depth
        const GRAVITY = 0.4;
        const TERMINAL_VELOCITY = 12;
        const FRICTION = 0.8;
        const BUILD_REACH = 5 * TILE_SIZE;

        // Block Dictionary
        const BLOCKS = {
            AIR: 0,
            DIRT: 1,
            GRASS: 2,
            STONE: 3,
            WOOD: 4,
            LEAVES: 5,
            GOLD: 6
        };

        const BLOCK_COLORS = {
            [BLOCKS.DIRT]: { main: '#795548', top: '#8D6E63', side: '#5D4037' },
            [BLOCKS.GRASS]: { main: '#795548', top: '#4CAF50', side: '#5D4037' },
            [BLOCKS.STONE]: { main: '#7f8c8d', top: '#95a5a6', side: '#bdc3c7' }, // Inverted shading for stone
            [BLOCKS.WOOD]: { main: '#8B4513', top: '#A0522D', side: '#6B3E11' },
            [BLOCKS.LEAVES]: { main: '#2ecc71', top: '#27ae60', side: '#229954', transparent: true },
            [BLOCKS.GOLD]: { main: '#f1c40f', top: '#f39c12', side: '#e67e22' }
        };

        const INVENTORY_ITEMS = [BLOCKS.DIRT, BLOCKS.WOOD, BLOCKS.STONE, BLOCKS.GOLD];

        // State variables
        let gameState = 'START'; // START, PLAYING, GAMEOVER
        let map = [];
        let enemies = [];
        let particles = [];
        let camera = { x: 0, y: 0 };
        let score = 0;
        let selectedSlot = 0;
        let time = 0; // for day/night cycle

        // Input handling
        const keys = { w: false, a: false, s: false, d: false, space: false, shift: false };
        const mouse = { x: 0, y: 0, leftDown: false, rightDown: false, worldX: 0, worldY: 0 };

        // --- ENTITIES ---

        class Player {
            constructor(x, y) {
                this.w = 20;
                this.h = 44;
                this.x = x;
                this.y = y;
                this.vx = 0;
                this.vy = 0;
                this.speed = 4;
                this.jumpForce = 8.5;
                this.grounded = false;
                this.maxHealth = 100;
                this.health = this.maxHealth;
                this.color = '#3498db';
                this.miningCooldown = 0;
                this.facingRight = true;
                this.invulnerableTime = 0;
            }

            update() {
                if (this.health <= 0) {
                    die();
                    return;
                }

                if (this.invulnerableTime > 0) this.invulnerableTime--;
                if (this.miningCooldown > 0) this.miningCooldown--;

                // Movement
                if (keys.a) { this.vx -= 1; this.facingRight = false; }
                if (keys.d) { this.vx += 1; this.facingRight = true; }

                this.vx *= FRICTION;

                // Cap speed
                if (this.vx > this.speed) this.vx = this.speed;
                if (this.vx < -this.speed) this.vx = -this.speed;

                // Jumping
                if ((keys.w || keys.space) && this.grounded) {
                    this.vy = -this.jumpForce;
                    this.grounded = false;
                    createParticles(this.x + this.w/2, this.y + this.h, '#fff', 5);
                }

                // Gravity
                this.vy += GRAVITY;
                if (this.vy > TERMINAL_VELOCITY) this.vy = TERMINAL_VELOCITY;

                // --- Collision Detection (X and Y separately) ---
                this.grounded = false;

                // X Collision
                this.x += this.vx;
                if (this.checkCollision(this.x, this.y)) {
                    // Resolve
                    if (this.vx > 0) { // Moving right
                        this.x = Math.floor((this.x + this.w) / TILE_SIZE) * TILE_SIZE - this.w - 0.01;
                    } else if (this.vx < 0) { // Moving left
                        this.x = Math.floor(this.x / TILE_SIZE) * TILE_SIZE + TILE_SIZE + 0.01;
                    }
                    this.vx = 0;
                }

                // Y Collision
                this.y += this.vy;
                if (this.checkCollision(this.x, this.y)) {
                    // Resolve
                    if (this.vy > 0) { // Falling
                        this.y = Math.floor((this.y + this.h) / TILE_SIZE) * TILE_SIZE - this.h - 0.01;
                        this.grounded = true;
                    } else if (this.vy < 0) { // Hitting head
                        this.y = Math.floor(this.y / TILE_SIZE) * TILE_SIZE + TILE_SIZE + 0.01;
                    }
                    this.vy = 0;
                }

                // Map bounds constraints
                if (this.x < 0) this.x = 0;
                if (this.x + this.w > CHUNK_WIDTH * TILE_SIZE) this.x = CHUNK_WIDTH * TILE_SIZE - this.w;
                if (this.y > CHUNK_HEIGHT * TILE_SIZE) this.health = 0; // Fall off world
            }

            checkCollision(x, y) {
                // Check corners of bounding box
                const left = Math.floor(x / TILE_SIZE);
                const right = Math.floor((x + this.w) / TILE_SIZE);
                const top = Math.floor(y / TILE_SIZE);
                const bottom = Math.floor((y + this.h) / TILE_SIZE);

                for (let c = left; c <= right; c++) {
                    for (let r = top; r <= bottom; r++) {
                        if (getBlock(c, r) !== BLOCKS.AIR && getBlock(c, r) !== BLOCKS.LEAVES) {
                            return true;
                        }
                    }
                }
                return false;
            }

            draw() {
                // Flash if invulnerable
                if (this.invulnerableTime > 0 && Math.floor(Date.now() / 100) % 2 === 0) return;

                // Body
                ctx.fillStyle = this.color;
                ctx.fillRect(this.x, this.y, this.w, this.h);

                // Head (lighter)
                ctx.fillStyle = '#5dade2';
                ctx.fillRect(this.x, this.y, this.w, this.w);

                // Eyes
                ctx.fillStyle = '#fff';
                const eyeX = this.facingRight ? this.x + 12 : this.x + 4;
                ctx.fillRect(eyeX, this.y + 6, 4, 4);
                ctx.fillStyle = '#000';
                ctx.fillRect(this.facingRight ? eyeX + 2 : eyeX, this.y + 6, 2, 4);

                // Draw aiming line/indicator if mining
                const dist = Math.hypot(mouse.worldX - (this.x+this.w/2), mouse.worldY - (this.y+this.h/2));
                if (dist < BUILD_REACH && gameState === 'PLAYING') {
                    const tx = Math.floor(mouse.worldX / TILE_SIZE) * TILE_SIZE;
                    const ty = Math.floor(mouse.worldY / TILE_SIZE) * TILE_SIZE;
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
                    ctx.lineWidth = 2;
                    ctx.strokeRect(tx, ty, TILE_SIZE, TILE_SIZE);
                }
            }

            takeDamage(amount, knockbackX) {
                if (this.invulnerableTime > 0) return;
                this.health -= amount;
                this.vx += knockbackX;
                this.vy -= 4; // pop up
                this.invulnerableTime = 60; // 1 second roughly
                healthBar.style.width = Math.max(0, (this.health / this.maxHealth) * 100) + '%';
                createParticles(this.x + this.w/2, this.y + this.h/2, '#e74c3c', 10);
                playSound(400, 'square', 0.1); // hit sound
            }
        }

        class Slime {
            constructor(x, y) {
                this.x = x;
                this.y = y;
                this.w = 24;
                this.h = 16;
                this.vx = (Math.random() > 0.5 ? 1 : -1) * 1.5;
                this.vy = 0;
                this.health = 20;
                this.jumpTimer = Math.random() * 100;
                this.color = `hsla(${120 + Math.random()*60}, 70%, 50%, 0.8)`;
            }

            update() {
                this.vy += GRAVITY;
                if (this.vy > TERMINAL_VELOCITY) this.vy = TERMINAL_VELOCITY;

                // AI Logic
                this.jumpTimer--;
                if (this.jumpTimer <= 0 && this.vy === 0) {
                    this.vy = -6; // jump
                    this.jumpTimer = 60 + Math.random() * 60;
                }

                // Move X
                this.x += this.vx;
                if (this.checkCollision(this.x, this.y)) {
                    this.x -= this.vx;
                    this.vx *= -1; // Turn around
                }

                // Move Y
                this.y += this.vy;
                if (this.checkCollision(this.x, this.y)) {
                    if (this.vy > 0) {
                        this.y = Math.floor((this.y + this.h) / TILE_SIZE) * TILE_SIZE - this.h - 0.01;
                    }
                    this.vy = 0;
                }

                // Player interaction
                if (player && gameState === 'PLAYING') {
                    // Damage player
                    if (this.x < player.x + player.w && this.x + this.w > player.x &&
                        this.y < player.y + player.h && this.y + this.h > player.y) {
                        player.takeDamage(10, this.x < player.x ? 5 : -5);
                    }
                }
            }

            checkCollision(x, y) {
                const left = Math.floor(x / TILE_SIZE);
                const right = Math.floor((x + this.w) / TILE_SIZE);
                const top = Math.floor(y / TILE_SIZE);
                const bottom = Math.floor((y + this.h) / TILE_SIZE);

                for (let c = left; c <= right; c++) {
                    for (let r = top; r <= bottom; r++) {
                        if (getBlock(c, r) !== BLOCKS.AIR && getBlock(c, r) !== BLOCKS.LEAVES) {
                            return true;
                        }
                    }
                }
                return false;
            }

            draw() {
                ctx.fillStyle = this.color;
                // Squish effect based on vertical velocity
                let drawH = this.h;
                let drawY = this.y;
                let drawW = this.w;
                let drawX = this.x;

                if (this.vy !== 0) {
                    drawH = this.h + Math.abs(this.vy);
                    drawY = this.y - Math.abs(this.vy)/2;
                    drawW = this.w - Math.abs(this.vy)/2;
                    drawX = this.x + Math.abs(this.vy)/4;
                }

                ctx.beginPath();
                ctx.roundRect(drawX, drawY, drawW, drawH, 5);
                ctx.fill();

                // Eyes
                ctx.fillStyle = '#fff';
                ctx.fillRect(this.x + 4, this.y + 4, 4, 4);
                ctx.fillRect(this.x + 16, this.y + 4, 4, 4);
                ctx.fillStyle = '#000';
                ctx.fillRect(this.vx > 0 ? this.x + 6 : this.x + 4, this.y + 6, 2, 2);
                ctx.fillRect(this.vx > 0 ? this.x + 18 : this.x + 16, this.y + 6, 2, 2);
            }
        }

        class Particle {
            constructor(x, y, color) {
                this.x = x;
                this.y = y;
                this.vx = (Math.random() - 0.5) * 4;
                this.vy = (Math.random() - 0.5) * 4 - 2;
                this.life = 1.0;
                this.decay = Math.random() * 0.05 + 0.02;
                this.color = color;
                this.size = Math.random() * 4 + 2;
            }
            update() {
                this.vy += GRAVITY * 0.5;
                this.x += this.vx;
                this.y += this.vy;
                this.life -= this.decay;
            }
            draw() {
                ctx.globalAlpha = this.life;
                ctx.fillStyle = this.color;
                ctx.fillRect(this.x, this.y, this.size, this.size);
                ctx.globalAlpha = 1.0;
            }
        }

        let player;

        // --- WORLD GENERATION ---

        function generateWorld() {
            map = new Array(CHUNK_WIDTH).fill(0).map(() => new Array(CHUNK_HEIGHT).fill(BLOCKS.AIR));
            enemies = [];

            // Simple 1D Perlin-esque noise
            let heights = [];
            let h = CHUNK_HEIGHT / 3;
            for (let i = 0; i < CHUNK_WIDTH; i++) {
                heights.push(Math.floor(h));
                h += (Math.random() - 0.5) * 3;
                if (h < 5) h = 5;
                if (h > CHUNK_HEIGHT - 10) h = CHUNK_HEIGHT - 10;
            }

            // Smooth heights
            for(let k=0; k<2; k++) {
                for (let i = 1; i < CHUNK_WIDTH - 1; i++) {
                    heights[i] = Math.floor((heights[i-1] + heights[i] + heights[i+1]) / 3);
                }
            }

            for (let x = 0; x < CHUNK_WIDTH; x++) {
                const surfaceY = heights[x];
                for (let y = 0; y < CHUNK_HEIGHT; y++) {
                    if (y < surfaceY) {
                        map[x][y] = BLOCKS.AIR;
                    } else if (y === surfaceY) {
                        map[x][y] = BLOCKS.GRASS;
                        // Spawn trees
                        if (Math.random() < 0.1 && x > 2 && x < CHUNK_WIDTH - 2) {
                            generateTree(x, y - 1);
                        }
                        // Spawn slimes
                        if (Math.random() < 0.05) {
                            enemies.push(new Slime(x * TILE_SIZE, (y - 1) * TILE_SIZE));
                        }
                    } else if (y > surfaceY && y < surfaceY + 4 + Math.random()*3) {
                        map[x][y] = BLOCKS.DIRT;
                    } else {
                        // Caves and ores
                        if (Math.random() > 0.15) { // 85% stone
                            map[x][y] = BLOCKS.STONE;
                            // Gold ore
                            if (Math.random() < 0.02) map[x][y] = BLOCKS.GOLD;
                        } else {
                            map[x][y] = BLOCKS.AIR; // Cave
                        }
                    }
                }
            }

            // Bedrock
            for (let x = 0; x < CHUNK_WIDTH; x++) {
                map[x][CHUNK_HEIGHT-1] = BLOCKS.STONE;
            }

            // Init Player
            const spawnX = Math.floor(CHUNK_WIDTH / 2);
            let spawnY = 0;
            while (map[spawnX][spawnY] === BLOCKS.AIR) { spawnY++; }
            player = new Player(spawnX * TILE_SIZE, (spawnY - 2) * TILE_SIZE);
        }

        function generateTree(x, y) {
            const height = Math.floor(Math.random() * 3) + 4;
            // Trunk
            for (let i = 0; i < height; i++) {
                if (y - i >= 0) map[x][y - i] = BLOCKS.WOOD;
            }
            // Leaves
            const leafTopY = y - height;
            for (let lx = x - 2; lx <= x + 2; lx++) {
                for (let ly = leafTopY - 2; ly <= leafTopY + 1; ly++) {
                    // Make it somewhat circular
                    if (Math.abs(lx - x) === 2 && Math.abs(ly - leafTopY) === 2) continue;
                    if (lx >= 0 && lx < CHUNK_WIDTH && ly >= 0) {
                        if (map[lx][ly] === BLOCKS.AIR) {
                            map[lx][ly] = BLOCKS.LEAVES;
                        }
                    }
                }
            }
        }

        function getBlock(x, y) {
            if (x < 0 || x >= CHUNK_WIDTH || y < 0 || y >= CHUNK_HEIGHT) return BLOCKS.AIR;
            return map[x][y];
        }

        function setBlock(x, y, type) {
            if (x >= 0 && x < CHUNK_WIDTH && y >= 0 && y < CHUNK_HEIGHT) {
                map[x][y] = type;
            }
        }

        // --- CORE GAME LOOP ---

        function resize() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
            ctx.imageSmoothingEnabled = false; // Pixel art style

            // Adjust mobile controls visibility based on touch
            if ('ontouchstart' in window) {
                mobileControls.style.display = 'flex';
                hotbarUI.style.bottom = '160px'; // Move up to make room
            }
        }

        function init() {
            resize();
            window.addEventListener('resize', resize);

            // Generate hotbar UI
            hotbarUI.innerHTML = '';
            INVENTORY_ITEMS.forEach((item, index) => {
                const slot = document.createElement('div');
                slot.className = `slot ${index === 0 ? 'active' : ''}`;
                slot.onclick = () => selectSlot(index);

                const num = document.createElement('div');
                num.className = 'slot-num';
                num.innerText = index + 1;
                slot.appendChild(num);

                // Draw miniature block
                if (BLOCK_COLORS[item]) {
                    const blockDiv = document.createElement('div');
                    blockDiv.style.width = '20px';
                    blockDiv.style.height = '20px';
                    blockDiv.style.backgroundColor = BLOCK_COLORS[item].main;
                    blockDiv.style.borderTop = `2px solid ${BLOCK_COLORS[item].top}`;
                    blockDiv.style.borderLeft = `2px solid ${BLOCK_COLORS[item].top}`;
                    blockDiv.style.borderRight = `2px solid ${BLOCK_COLORS[item].side}`;
                    blockDiv.style.borderBottom = `2px solid ${BLOCK_COLORS[item].side}`;
                    slot.appendChild(blockDiv);
                }

                hotbarUI.appendChild(slot);
            });

            bindInput();
            requestAnimationFrame(loop);
        }

        function selectSlot(index) {
            selectedSlot = index;
            document.querySelectorAll('.slot').forEach((el, i) => {
                el.classList.toggle('active', i === index);
            });
        }

        function startGame() {
            generateWorld();
            score = 0;
            scoreDisplay.innerText = score;
            healthBar.style.width = '100%';
            gameState = 'PLAYING';
            startScreen.classList.add('hidden');
            gameOverScreen.classList.add('hidden');
            hud.classList.remove('hidden');
            hotbarUI.classList.remove('hidden');
        }

        function die() {
            gameState = 'GAMEOVER';
            hud.classList.add('hidden');
            hotbarUI.classList.add('hidden');
            gameOverScreen.classList.remove('hidden');
        }

        function update() {
            if (gameState !== 'PLAYING') return;

            time += 0.005;

            // Update player
            player.update();

            // Camera follow
            let targetCamX = player.x + player.w / 2 - canvas.width / 2;
            let targetCamY = player.y + player.h / 2 - canvas.height / 2;

            // Clamp camera
            targetCamX = Math.max(0, Math.min(targetCamX, CHUNK_WIDTH * TILE_SIZE - canvas.width));
            targetCamY = Math.max(0, Math.min(targetCamY, CHUNK_HEIGHT * TILE_SIZE - canvas.height));

            // Smooth camera
            camera.x += (targetCamX - camera.x) * 0.1;
            camera.y += (targetCamY - camera.y) * 0.1;

            // Handle Mouse Interactions (Mining/Placing/Attacking)
            if ((mouse.leftDown || mouse.rightDown) && player.miningCooldown <= 0) {
                handleAction();
            }

            // Update enemies
            for (let i = enemies.length - 1; i >= 0; i--) {
                enemies[i].update();
                if (enemies[i].health <= 0) {
                    score += 50;
                    scoreDisplay.innerText = score;
                    createParticles(enemies[i].x + enemies[i].w/2, enemies[i].y + enemies[i].h/2, enemies[i].color, 15);
                    enemies.splice(i, 1);
                    playSound(200, 'sawtooth', 0.1);
                }
            }

            // Update particles
            for (let i = particles.length - 1; i >= 0; i--) {
                particles[i].update();
                if (particles[i].life <= 0) particles.splice(i, 1);
            }
        }

        function handleAction() {
            const px = player.x + player.w/2;
            const py = player.y + player.h/2;
            const dist = Math.hypot(mouse.worldX - px, mouse.worldY - py);

            if (dist > BUILD_REACH) return;

            const tx = Math.floor(mouse.worldX / TILE_SIZE);
            const ty = Math.floor(mouse.worldY / TILE_SIZE);

            // Attacking enemies takes priority on left click
            if (mouse.leftDown && !keys.shift) {
                let hitEnemy = false;
                for (let e of enemies) {
                    if (mouse.worldX > e.x && mouse.worldX < e.x + e.w &&
                        mouse.worldY > e.y && mouse.worldY < e.y + e.h) {
                        e.health -= 10;
                        e.vx += player.facingRight ? 5 : -5; // Knockback
                        e.vy -= 3;
                        createParticles(mouse.worldX, mouse.worldY, '#fff', 5);
                        player.miningCooldown = 15;
                        playSound(300, 'square', 0.05);
                        hitEnemy = true;
                        break;
                    }
                }
                if (hitEnemy) return;
            }

            // Mining / Placing Blocks
            const currentBlock = getBlock(tx, ty);

            if (mouse.leftDown && !keys.shift) {
                // Mine
                if (currentBlock !== BLOCKS.AIR) {
                    setBlock(tx, ty, BLOCKS.AIR);
                    player.miningCooldown = 10;
                    if (currentBlock === BLOCKS.GOLD) {
                        score += 100;
                        scoreDisplay.innerText = score;
                        playSound(800, 'sine', 0.1);
                    } else {
                        playSound(150, 'noise', 0.05); // pseudo-noise
                    }
                    createParticles(tx*TILE_SIZE + TILE_SIZE/2, ty*TILE_SIZE + TILE_SIZE/2, BLOCK_COLORS[currentBlock] ? BLOCK_COLORS[currentBlock].main : '#fff', 8);
                }
            } else if (mouse.rightDown || (mouse.leftDown && keys.shift)) {
                // Place
                if (currentBlock === BLOCKS.AIR || currentBlock === BLOCKS.LEAVES) {
                    // Check if player is overlapping target block
                    if (!(player.x < (tx+1)*TILE_SIZE && player.x + player.w > tx*TILE_SIZE &&
                          player.y < (ty+1)*TILE_SIZE && player.y + player.h > ty*TILE_SIZE)) {
                        setBlock(tx, ty, INVENTORY_ITEMS[selectedSlot]);
                        player.miningCooldown = 15;
                        playSound(100, 'square', 0.05);
                    }
                }
            }
        }

        function createParticles(x, y, color, count) {
            for (let i = 0; i < count; i++) {
                particles.push(new Particle(x, y, color));
            }
        }

        function draw() {
            // Sky background based on time
            const dayCycle = Math.sin(time);
            let r=135, g=206, b=235; // Day sky
            if (dayCycle < 0) { // Night
                const intensity = Math.max(0, 1 + dayCycle);
                r = Math.floor(r * intensity);
                g = Math.floor(g * intensity);
                b = Math.floor(b * intensity);
            }
            ctx.fillStyle = `rgb(${r},${g},${b})`;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw Stars at night
            if (dayCycle < 0) {
                ctx.fillStyle = '#fff';
                for(let i=0; i<50; i++) {
                    let sx = (Math.sin(i*123) * 1000 + time*10) % canvas.width;
                    if(sx<0) sx += canvas.width;
                    let sy = (Math.cos(i*321) * 500) % (canvas.height/2);
                    ctx.globalAlpha = Math.random() * Math.abs(dayCycle);
                    ctx.fillRect(sx, Math.abs(sy), 2, 2);
                }
                ctx.globalAlpha = 1.0;
            }

            if (gameState !== 'PLAYING') return;

            ctx.save();
            ctx.translate(-camera.x, -camera.y);

            // Calculate visible grid area
            const startCol = Math.floor(camera.x / TILE_SIZE);
            const endCol = startCol + (canvas.width / TILE_SIZE) + 1;
            const startRow = Math.floor(camera.y / TILE_SIZE);
            const endRow = startRow + (canvas.height / TILE_SIZE) + 1;

            // Draw Map
            for (let c = Math.max(0, startCol); c < Math.min(CHUNK_WIDTH, endCol); c++) {
                for (let r = Math.max(0, startRow); r < Math.min(CHUNK_HEIGHT, endRow); r++) {
                    const block = map[c][r];
                    if (block !== BLOCKS.AIR) {
                        drawBlock(c * TILE_SIZE, r * TILE_SIZE, block);
                    } else if (r > CHUNK_HEIGHT/3) { // Draw background cave wall dirt
                         ctx.fillStyle = '#3e2723';
                         ctx.fillRect(c * TILE_SIZE, r * TILE_SIZE, TILE_SIZE, TILE_SIZE);
                    }
                }
            }

            // Draw Entities
            for (let e of enemies) e.draw();
            player.draw();
            for (let p of particles) p.draw();

            ctx.restore();

            // Screen tint for night
            if (dayCycle < 0) {
                ctx.fillStyle = `rgba(0, 0, 10, ${Math.abs(dayCycle) * 0.5})`;
                ctx.fillRect(0, 0, canvas.width, canvas.height);
            }
        }

        function drawBlock(x, y, type) {
            const colors = BLOCK_COLORS[type];
            if (!colors) return;

            if (colors.transparent) {
                // Leaf styling
                ctx.fillStyle = colors.main;
                ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);
                ctx.fillStyle = colors.side;
                ctx.fillRect(x + 4, y + 4, 8, 8);
                ctx.fillRect(x + 16, y + 16, 8, 8);
                return;
            }

            // Main fill
            ctx.fillStyle = colors.main;
            ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);

            // Shading for 3D/Texture effect
            const thick = 4;

            // Top highlight
            ctx.fillStyle = colors.top;
            ctx.fillRect(x, y, TILE_SIZE, thick);
            ctx.fillRect(x, y, thick, TILE_SIZE);

            // Bottom shadow
            ctx.fillStyle = colors.side;
            ctx.fillRect(x, y + TILE_SIZE - thick, TILE_SIZE, thick);
            ctx.fillRect(x + TILE_SIZE - thick, y, thick, TILE_SIZE);
        }

        function loop() {
            update();
            draw();
            requestAnimationFrame(loop);
        }

        // --- INPUT & UTILS ---

        function updateMousePos(evt) {
            const rect = canvas.getBoundingClientRect();
            // Handle both touch and mouse
            let clientX = evt.clientX;
            let clientY = evt.clientY;

            if (evt.touches && evt.touches.length > 0) {
                clientX = evt.touches[0].clientX;
                clientY = evt.touches[0].clientY;
            }

            mouse.x = clientX - rect.left;
            mouse.y = clientY - rect.top;
            mouse.worldX = mouse.x + camera.x;
            mouse.worldY = mouse.y + camera.y;
        }

        function bindInput() {
            // Keyboard
            window.addEventListener('keydown', e => {
                const k = e.key.toLowerCase();
                if (keys.hasOwnProperty(k)) keys[k] = true;
                if (e.key === 'Shift') keys.shift = true;
                if (['1','2','3','4'].includes(k)) selectSlot(parseInt(k)-1);
            });
            window.addEventListener('keyup', e => {
                const k = e.key.toLowerCase();
                if (keys.hasOwnProperty(k)) keys[k] = false;
                if (e.key === 'Shift') keys.shift = false;
            });

            // Mouse
            canvas.addEventListener('mousemove', updateMousePos);
            canvas.addEventListener('mousedown', e => {
                updateMousePos(e);
                if (e.button === 0) mouse.leftDown = true;
                if (e.button === 2) mouse.rightDown = true;
            });
            canvas.addEventListener('mouseup', e => {
                if (e.button === 0) mouse.leftDown = false;
                if (e.button === 2) mouse.rightDown = false;
            });
            canvas.addEventListener('contextmenu', e => e.preventDefault());

            // Touch interaction for canvas (Mining/Placing)
            canvas.addEventListener('touchstart', e => {
                // Prevent default unless it's on a UI element
                if (e.target === canvas) {
                    e.preventDefault();
                    updateMousePos(e);
                    // Default touch on canvas to mine, use button for mode switch if needed later
                    mouse.leftDown = true; 
                }
            }, {passive: false});
            canvas.addEventListener('touchmove', e => {
                if(mouse.leftDown) updateMousePos(e);
            });
            canvas.addEventListener('touchend', e => {
                mouse.leftDown = false;
                mouse.rightDown = false;
            });

            // Mobile Controls
            const bindBtn = (id, key) => {
                const btn = document.getElementById(id);
                if(!btn) return;
                btn.addEventListener('touchstart', e => { e.preventDefault(); keys[key] = true; });
                btn.addEventListener('touchend', e => { e.preventDefault(); keys[key] = false; });
            };
            bindBtn('btn-left', 'a');
            bindBtn('btn-right', 'd');
            bindBtn('btn-jump', 'w');

            const actionBtn = document.getElementById('btn-action');
            actionBtn.addEventListener('touchstart', e => {
                e.preventDefault();
                // Toggle mode for next canvas click, or simulate shift
                keys.shift = !keys.shift;
                actionBtn.innerText = keys.shift ? "PLACE" : "MINE";
                actionBtn.style.background = keys.shift ? "rgba(241, 196, 15, 0.5)" : "rgba(255,255,255,0.2)";
            });


            // UI Buttons
            document.getElementById('startBtn').addEventListener('click', startGame);
            document.getElementById('restartBtn').addEventListener('click', startGame);
        }

        // Extremely basic Web Audio synth for retro sounds
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        let actx;

        function playSound(freq, type, vol) {
            if (!actx) {
                try { actx = new AudioContext(); } catch(e) { return; }
            }
            if(actx.state === 'suspended') actx.resume();

            const osc = actx.createOscillator();
            const gain = actx.createGain();

            // Fake noise
            if (type === 'noise') {
                 // Too complex for tiny snippet, fallback to square at low freq
                 osc.type = 'square';
                 freq = Math.random() * 100 + 50;
            } else {
                osc.type = type;
            }

            osc.frequency.setValueAtTime(freq, actx.currentTime);
            if (type === 'sawtooth') { // enemy death drop freq
                osc.frequency.exponentialRampToValueAtTime(10, actx.currentTime + 0.2);
            }

            gain.gain.setValueAtTime(vol, actx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, actx.currentTime + 0.1);

            osc.connect(gain);
            gain.connect(actx.destination);
            osc.start();
            osc.stop(actx.currentTime + 0.1);
        }

        // Start
        window.onload = init;

    </script>
</body>
</html>
