        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const dt = clock.getDelta();

            if (state.phase !== 'START') {
                state.time += dt;
                const t = state.time;

                // Phase logic
                if (state.phase === 'OPENING') {
                    // Doors open over 3 seconds
                    const progress = Math.min(t / 3, 1);
                    doorLeft.position.x = -8 - progress * 10;
                    doorRight.position.x = 8 + progress * 10;

                    // Door sound
                    if(state.audioNodes.doorGain) {
                        state.audioNodes.doorGain.gain.value = (1 - progress) * 0.3;
                    }

                    if (t > 3) {
                        state.phase = 'IGNITION';
                        state.time = 0; // reset phase time
                    }
                }
                else if (state.phase === 'IGNITION') {
                    // 2 seconds of building thrust
                    const progress = Math.min(t / 2, 1);
                    state.missile.thrust = progress * 200000; // kN mapping
                    exhaustLight.intensity = progress * 2;

                    // Engine sound build up
                    if(state.audioNodes.engineGain) {
                        state.audioNodes.engineGain.gain.value = progress;
                        state.audioNodes.filter.frequency.value = 100 + progress * 400;
                    }

                    if (t > 2) {
                        state.phase = 'FLIGHT';
                        state.time = 0;
                    }
                }
                else if (state.phase === 'FLIGHT') {
                    // Physics updates
                    state.missile.thrust = 350000 + (t * 10000); // Thrust increases slightly
                    const gravity = 9.81 * state.missile.mass;
                    const netForce = state.missile.thrust - gravity;
                    state.missile.accelY = netForce / state.missile.mass;
                    state.missile.velY += state.missile.accelY * dt;
                    state.missile.y += state.missile.velY * dt;

                    missileGroup.position.y = state.missile.y;

                    // Light follows missile
                    exhaustLight.position.set(0, state.missile.y, 0);

                    // Update HUD
                    elAlt.innerText = state.missile.y.toFixed(0);
                    // Approximation of Mach (343 m/s)
                    elVel.innerText = (state.missile.velY / 343).toFixed(2);
                    elThrust.innerText = (state.missile.thrust / 1000).toFixed(0);

                    // Plasma effect based on speed
                    const mach = state.missile.velY / 343;
                    if (mach > 1) {
                        plasmaMat.opacity = Math.min((mach - 1) / 5, 0.8);
                    }

                    // Audio
                    if(state.audioNodes.filter) {
                        // Pitch goes up as speed increases
                        state.audioNodes.filter.frequency.value = Math.min(500 + state.missile.velY * 2, 5000);
                    }

                    // Cinematic Camera Sequencing
                    // T=0-5: Low Angle
                    // T=5-10: Chase
                    // T=10-15: FPV
                    // T=15-20: Side Tracking
                    // T>20: Wide World
                    if (t > 5 && t <= 10) state.cameraMode = 'CHASE';
                    else if (t > 10 && t <= 15) state.cameraMode = 'FPV';
                    else if (t > 15 && t <= 20) state.cameraMode = 'SIDE_TRACKING';
                    else if (t > 20) {
                        state.cameraMode = 'WIDE_WORLD';
                        // Fade out audio in distance
                        if(state.audioNodes.engineGain) {
                            state.audioNodes.engineGain.gain.value = Math.max(0, 1 - (t-20)/10);
                        }
                    }
                }

                // Particle Emission (Ignition and Flight)
                if (state.phase === 'IGNITION' || state.phase === 'FLIGHT') {
                    const emitCount = state.phase === 'IGNITION' ? 10 : 30;
                    const pos = particlesGeo.attributes.position.array;
                    const life = particlesGeo.attributes.life.array;

                    for(let i=0; i<emitCount; i++) {
                        pIndex = (pIndex + 1) % particleCount;

                        // Spawn at base of missile
                        pos[pIndex*3] = missileGroup.position.x + (Math.random()-0.5)*1.5;
                        pos[pIndex*3+1] = missileGroup.position.y - 1 + (Math.random()-0.5);
                        pos[pIndex*3+2] = missileGroup.position.z + (Math.random()-0.5)*1.5;

                        life[pIndex] = 1.0; // Life 1.0 to 0
                    }
                }

                // Update particles
                const pos = particlesGeo.attributes.position.array;
                const life = particlesGeo.attributes.life.array;
                for(let i=0; i<particleCount; i++) {
                    if (life[i] > 0) {
                        life[i] -= dt * 0.5; // lifespan

                        // move particles down and spread out (exhaust cone)
                        const pY = pos[i*3+1];
                        const diffY = missileGroup.position.y - pY;

                        // If it hit the ground/bunker floor, spread outward
                        if (pY <= -10) {
                            pos[i*3] *= 1.05; // expand X
                            pos[i*3+2] *= 1.05; // expand Z
                            pos[i*3+1] = -10 + Math.random()*2;
                        } else {
                            pos[i*3+1] -= (50 + Math.random()*50) * dt; // Fall down
                            pos[i*3] += (Math.random()-0.5) * 5 * dt;
                            pos[i*3+2] += (Math.random()-0.5) * 5 * dt;
                        }

                        if (life[i] <= 0) {
                            pos[i*3+1] = -10000; // hide
                        }
                    }
                }
                particlesGeo.attributes.position.needsUpdate = true;

                // Fin Vibration during flight
                if(state.phase === 'FLIGHT') {
                    missileGroup.children.forEach((child) => {
                        if(child.geometry.type === 'BoxGeometry') {
                            child.rotation.x = (Math.random()-0.5)*0.05;
                            child.rotation.z = (Math.random()-0.5)*0.05;
                        }
                    });
                }

                updateCamera();
            } else {
                // Idle camera spin before start
                camera.position.set(Math.cos(Date.now()*0.0005)*30, 20, Math.sin(Date.now()*0.0005)*30);
                camera.lookAt(0, 0, 0);
            }

            renderer.render(scene, camera);
        }

        animate();
    </script>
