// --- Board Construction ---
const boardGroup = new THREE.Group();
scene.add(boardGroup);

const squareSize = 1;
const boardOffset = 3.5; // (8 squares - 1) / 2 to center

// Materials
const matLightSquare = new THREE.MeshStandardMaterial({ color: 0xeeeed2, roughness: 0.8, metalness: 0.1 });
const matDarkSquare = new THREE.MeshStandardMaterial({ color: 0x769656, roughness: 0.8, metalness: 0.1 });
const matBoardEdge = new THREE.MeshStandardMaterial({ color: 0x4a3623, roughness: 0.9 });

const matWhitePiece = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3, metalness: 0.1 });
const matBlackPiece = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4, metalness: 0.3 });

// Highlight Materials
const matHighlightSelect = new THREE.MeshBasicMaterial({ color: 0xaaaa00, transparent: true, opacity: 0.5, side: THREE.DoubleSide });
const matHighlightMove = new THREE.MeshBasicMaterial({ color: 0x00aa00, transparent: true, opacity: 0.4, side: THREE.DoubleSide });
const matHighlightCapture = new THREE.MeshBasicMaterial({ color: 0xaa0000, transparent: true, opacity: 0.5, side: THREE.DoubleSide });

// Data structure to hold board meshes and 3d pieces
const squares3D = {}; // mapping 'e4' to mesh
let pieces3D = {};    // mapping 'e4' to piece Group

// Build the 8x8 grid
const boxGeo = new THREE.BoxGeometry(squareSize, 0.2, squareSize);
for (let rank = 0; rank < 8; rank++) {
    for (let file = 0; file < 8; file++) {
        const isLight = (rank + file) % 2 !== 0;
        const squareMat = isLight ? matLightSquare : matDarkSquare;
        const squareMesh = new THREE.Mesh(boxGeo, squareMat);

        const x = file - boardOffset;
        const z = boardOffset - rank; // Invert rank so 1 is at +z, 8 is at -z

        squareMesh.position.set(x, -0.1, z);
        squareMesh.receiveShadow = true;

