// --- Procedural Piece Generation ---
// Utility to merge geometries (simplified approach: group primitives)
function createPiece(type, color) {
    const group = new THREE.Group();
    const mat = color === 'w' ? matWhitePiece : matBlackPiece;

    // Base geometry shared by all pieces
    const baseGeo = new THREE.CylinderGeometry(0.35, 0.4, 0.2, 32);
    const base = new THREE.Mesh(baseGeo, mat);
    base.position.y = 0.1;
    base.castShadow = true;
    base.receiveShadow = true;
