            body = new THREE.Mesh(bodyGeo, mat);
            body.position.y = 0.5;
            topGeo = new THREE.SphereGeometry(0.2, 32, 32);
            top = new THREE.Mesh(topGeo, mat);
            top.position.y = 0.9;
            break;
        case 'r': // Rook
            bodyGeo = new THREE.CylinderGeometry(0.25, 0.3, 0.8, 32);
            body = new THREE.Mesh(bodyGeo, mat);
            body.position.y = 0.6;
            topGeo = new THREE.CylinderGeometry(0.3, 0.25, 0.2, 8); // Hex/Oct top
            top = new THREE.Mesh(topGeo, mat);
            top.position.y = 1.1;
            break;
        case 'n': // Knight (Simplified: leaning cylinder + box head)
            bodyGeo = new THREE.CylinderGeometry(0.2, 0.3, 0.8, 32);
            body = new THREE.Mesh(bodyGeo, mat);
            body.position.y = 0.6;
            body.rotation.x = 0.1; // lean forward slightly

            topGeo = new THREE.BoxGeometry(0.3, 0.4, 0.5);
            top = new THREE.Mesh(topGeo, mat);
            top.position.set(0, 1.0, 0.1);
