        case 'b': // Bishop
            bodyGeo = new THREE.CylinderGeometry(0.15, 0.3, 0.9, 32);
            body = new THREE.Mesh(bodyGeo, mat);
            body.position.y = 0.65;
            topGeo = new THREE.CylinderGeometry(0.01, 0.15, 0.4, 32); // Pointy top
            top = new THREE.Mesh(topGeo, mat);
            top.position.y = 1.3;
