        case 'q': // Queen
            bodyGeo = new THREE.CylinderGeometry(0.2, 0.35, 1.2, 32);
            body = new THREE.Mesh(bodyGeo, mat);
            body.position.y = 0.8;
            topGeo = new THREE.SphereGeometry(0.25, 32, 32);
            top = new THREE.Mesh(topGeo, mat);
            top.position.y = 1.5;
