// Convert logic square ('e4') to Vector3
function getSquarePos(square) {
    if(!square) return new THREE.Vector3(0,0,0);
    const pos = squares3D[square].position.clone();
    pos.y = 0; // Surface level
    return pos;
}

// Initialize Board from logic
function syncBoardToLogic(animate = false) {
    // Clear existing logic-mapped pieces
    for (let sq in pieces3D) {
        if(pieces3D[sq]) {
            boardGroup.remove(pieces3D[sq]);
        }
    }
    pieces3D = {};

    const board = game.board();
    for (let i = 0; i < 8; i++) {
        for (let j = 0; j < 8; j++) {
            const pieceData = board[i][j];
            if (pieceData) {
                const sq = String.fromCharCode(97 + j) + (8 - i);
                const pieceMesh = createPiece(pieceData.type, pieceData.color);

                const pos = getSquarePos(sq);
                pieceMesh.position.copy(pos);

                // Rotation (Black faces white)
                if (pieceData.color === 'b') {
                    pieceMesh.rotation.y = Math.PI;
                }

                // Add data for interaction
                pieceMesh.userData = { square: sq, color: pieceData.color, type: 'piece' };
                // Assign user data to all children so raycaster hits register
                pieceMesh.traverse(child => {
                    if (child.isMesh) child.userData = pieceMesh.userData;
                });

                pieces3D[sq] = pieceMesh;
                boardGroup.add(pieceMesh);

                if(animate) {
                    pieceMesh.position.y = 5;
                    new TWEEN.Tween(pieceMesh.position)
                        .to({ y: 0 }, 1000 + Math.random() * 500)
                        .easing(TWEEN.Easing.Bounce.Out)
                        .start();
                }
            }
        }
    }
}

// --- Interaction (Raycasting) ---
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

function onPointerDown(event) {
    if (gameState !== 'playing') return;

    // Calculate mouse position in normalized device coordinates
    mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

    raycaster.setFromCamera(mouse, camera);

    // Intersect board and pieces
    const intersects = raycaster.intersectObjects(boardGroup.children, true);

    if (intersects.length > 0) {
        // Find first intersection that has user data
        let hit = null;
        for (let i = 0; i < intersects.length; i++) {
            if (intersects[i].object.userData.square) {
                hit = intersects[i].object;
                break;
            }
        }

        if (hit) {
            handleSquareClick(hit.userData.square);
        } else {
            clearSelection();
        }
    } else {
        clearSelection();
    }
}

window.addEventListener('pointerdown', onPointerDown);

function handleSquareClick(square) {
    const pieceOnSquare = game.get(square);
    const turn = game.turn();

    // State 1: Select a piece
    if (!selectedSquare) {
        if (pieceOnSquare && pieceOnSquare.color === turn) {
            selectedSquare = square;
            highlightSelection(square);
            showValidMoves(square);
        }
    } 
    // State 2: Piece already selected, trying to move
    else {
        // Clicked same piece -> deselect
        if (selectedSquare === square) {
            clearSelection();
            return;
        }

        // Clicked another own piece -> change selection
        if (pieceOnSquare && pieceOnSquare.color === turn) {
            selectedSquare = square;
            highlightSelection(square);
            showValidMoves(square);
            return;
        }

        // Try to move
        const move = validMoves.find(m => m.to === square);
        if (move) {
            executeMove(move);
        } else {
            clearSelection();
        }
    }
}

function highlightSelection(square) {
    const pos = getSquarePos(square);
    selectionHighlight.position.set(pos.x, 0.01, pos.z);
    selectionHighlight.visible = true;
}

function showValidMoves(square) {
    // Hide old
    moveHighlights.forEach(h => h.visible = false);

    // Get moves
    validMoves = game.moves({ square: square, verbose: true });

    // Show new
    validMoves.forEach((move, index) => {
        if(index < moveHighlights.length) {
            const pos = getSquarePos(move.to);
            moveHighlights[index].position.set(pos.x, 0.01, pos.z);
            moveHighlights[index].visible = true;

            // Change color if it's a capture
            if(move.flags.includes('c') || move.flags.includes('e')) {
                moveHighlights[index].material = matHighlightCapture;
            } else {
                moveHighlights[index].material = matHighlightMove;
            }
        }
    });
}

function clearSelection() {
    selectedSquare = null;
    validMoves = [];
    selectionHighlight.visible = false;
    moveHighlights.forEach(h => h.visible = false);
}

function executeMove(moveInfo) {
    gameState = 'animating';
    clearSelection();

    const sourceSq = moveInfo.from;
    const targetSq = moveInfo.to;
    const piece3D = pieces3D[sourceSq];

    // Determine if capture
    const isCapture = moveInfo.flags.includes('c') || moveInfo.flags.includes('e');
    let capturedPiece3D = null;

    if (isCapture) {
        // En passant target is different from move target
        const capSq = moveInfo.flags.includes('e') ? targetSq[0] + sourceSq[1] : targetSq;
        capturedPiece3D = pieces3D[capSq];
    }

    // Apply logic move
    game.move(moveInfo.san);

    // Update 3D mapping dictionary early so subsequent clicks don't break during animation
    pieces3D[targetSq] = piece3D;
    delete pieces3D[sourceSq];
    // Update userdata for raycasting
    piece3D.userData.square = targetSq;
    piece3D.traverse(child => { if (child.isMesh) child.userData.square = targetSq; });

    // Animate move
    const targetPos = getSquarePos(targetSq);
    const startPos = piece3D.position.clone();

    // Arc movement
    const dist = startPos.distanceTo(targetPos);
    const height = Math.max(0.5, dist * 0.3); // Jump height based on distance
    const duration = Math.min(800, 300 + dist * 100);

    // Move XZ
    new TWEEN.Tween(piece3D.position)
        .to({ x: targetPos.x, z: targetPos.z }, duration)
        .easing(TWEEN.Easing.Quadratic.InOut)
        .start();

    // Arc Y
    new TWEEN.Tween(piece3D.position)
        .to({ y: height }, duration / 2)
        .easing(TWEEN.Easing.Quadratic.Out)
        .onComplete(() => {
            new TWEEN.Tween(piece3D.position)
                .to({ y: 0 }, duration / 2)
                .easing(TWEEN.Easing.Quadratic.In)
                .onComplete(() => {
                    checkGameState();
                })
                .start();
        })
        .start();

    // Animate Capture
    if (capturedPiece3D) {
        delete pieces3D[capturedPiece3D.userData.square]; // remove from map

        // Shrink and remove
        new TWEEN.Tween(capturedPiece3D.scale)
            .to({ x: 0, y: 0, z: 0 }, duration * 0.6)
            .easing(TWEEN.Easing.Back.In)
            .onComplete(() => {
                boardGroup.remove(capturedPiece3D);
            })
            .start();
    }

    // Handle Castling (move rook)
    if (moveInfo.flags.includes('k') || moveInfo.flags.includes('q')) {
        let rookSource, rookTarget;
        if(moveInfo.color === 'w') {
            if(moveInfo.flags.includes('k')) { rookSource = 'h1'; rookTarget = 'f1'; }
            else { rookSource = 'a1'; rookTarget = 'd1'; }
        } else {
            if(moveInfo.flags.includes('k')) { rookSource = 'h8'; rookTarget = 'f8'; }
            else { rookSource = 'a8'; rookTarget = 'd8'; }
        }

        const rook3D = pieces3D[rookSource];
        if(rook3D) {
            pieces3D[rookTarget] = rook3D;
            delete pieces3D[rookSource];
            rook3D.userData.square = rookTarget;
            rook3D.traverse(child => { if(child.isMesh) child.userData.square = rookTarget; });

            const rTargetPos = getSquarePos(rookTarget);
            new TWEEN.Tween(rook3D.position)
                .to({ x: rTargetPos.x, z: rTargetPos.z }, duration)
                .easing(TWEEN.Easing.Quadratic.InOut)
                .start();
        }
    }

    // Handle Promotion
    if (moveInfo.flags.includes('p')) {
        // Simplified: immediately swap model after move animation
        setTimeout(() => {
            boardGroup.remove(piece3D);
            const newPiece = createPiece(moveInfo.promotion || 'q', moveInfo.color);
            newPiece.position.copy(targetPos);
            newPiece.userData = { square: targetSq, color: moveInfo.color, type: 'piece' };
            newPiece.traverse(child => { if (child.isMesh) child.userData = newPiece.userData; });
            pieces3D[targetSq] = newPiece;
            boardGroup.add(newPiece);

            // Pop effect
            newPiece.scale.set(0,0,0);
            new TWEEN.Tween(newPiece.scale)
                .to({x:1, y:1, z:1}, 300)
                .easing(TWEEN.Easing.Back.Out)
                .start();
        }, duration);
    }
}

function checkGameState() {
    gameState = 'playing'; // Restore interaction
    updateUI();

    if (game.game_over()) {
        gameState = 'gameover';
        setTimeout(showGameOver, 500); // Slight delay for final impact
    } else {
