        .to({ x: 0, y: 12, z: 14 }, 1500)
        .easing(TWEEN.Easing.Cubic.InOut)
        .start();

    // Point camera at center
    const target = new THREE.Vector3(0, 0, 0);
    new TWEEN.Tween(controls.target)
        .to({ x: 0, y: 0, z: 0 }, 1500)
        .easing(TWEEN.Easing.Cubic.InOut)
        .start();
}

function updateUI() {
    if (game.turn() === 'w') {
        turnIndicator.textContent = "White's Turn";
        turnIndicator.className = "text-xl font-bold text-white tracking-wider";
    } else {
        turnIndicator.textContent = "Black's Turn";
        turnIndicator.className = "text-xl font-bold text-gray-400 tracking-wider";
