function showGameOver() {
    let title = "Game Over";
    let subtitle = "Draw";

    if (game.in_checkmate()) {
        title = "Checkmate!";
        subtitle = game.turn() === 'w' ? "Black wins." : "White wins.";
    } else if (game.in_stalemate()) {
        subtitle = "Stalemate";
    } else if (game.in_threefold_repetition()) {
        subtitle = "Draw by repetition";
    } else if (game.insufficient_material()) {
        subtitle = "Draw by insufficient material";
    }

    gameOverTitle.textContent = title;
    gameOverSubtitle.textContent = subtitle;
    setUIState(gameOverScreen, [topBar]);
    controls.enabled = false;

    // Spin camera slowly
    const currentAngle = Math.atan2(camera.position.x, camera.position.z);
    const radius = Math.sqrt(camera.position.x**2 + camera.position.z**2);

    new TWEEN.Tween({theta: currentAngle})
        .to({theta: currentAngle + Math.PI * 2}, 20000)
        .onUpdate((obj) => {
            camera.position.x = Math.sin(obj.theta) * radius;
            camera.position.z = Math.cos(obj.theta) * radius;
            camera.lookAt(0,0,0);
        })
        .repeat(Infinity)
        .start();
}

