            particles.push(new Particle({
                position: {x: this.position.x + (this.velocity.x > 0 ? 0 : this.width), y: this.position.y + this.height/2 + (Math.random()-0.5)*10},
                velocity: {x: (Math.random() - 0.5) * 2, y: (Math.random() - 0.5) * 2},
                color: '#93c5fd'
            }));
        }
        update() {
            if(!this.active) return;
            this.draw();
            this.position.x += this.velocity.x;
            if(this.position.x > CANVAS_WIDTH + 100 || this.position.x < -100) this.active = false;
