            if (this.isAttacking && this.attackType !== 'jutsu') {
                ctx.fillStyle = this.attackType === 'punch' ? 'rgba(239, 68, 68, 0.5)' : 'rgba(34, 197, 94, 0.5)';
                ctx.fillRect(
                    this.attackBox.position.x,
                    this.attackBox.position.y,
                    this.attackBox.width,
                    this.attackBox.height
                );
            }
        }

        update() {
            this.draw();
            if(this.cooldown > 0) this.cooldown--;

            // Determine facing direction
            if (this.velocity.x > 0) this.facingRight = true;
            else if (this.velocity.x < 0) this.facingRight = false;

            // Attack box positioning
            this.attackBox.position.x = this.facingRight ? this.position.x + this.width : this.position.x - this.attackBox.width;
            this.attackBox.position.y = this.position.y + 20;

            // Movement
            this.position.x += this.velocity.x;
            this.position.y += this.velocity.y;

            // Boundaries
            if (this.position.x < 0) this.position.x = 0;
            if (this.position.x + this.width > CANVAS_WIDTH) this.position.x = CANVAS_WIDTH - this.width;

            // Gravity
            if (this.position.y + this.height + this.velocity.y >= CANVAS_HEIGHT - 50) { // Ground level offset
                this.velocity.y = 0;
                this.position.y = CANVAS_HEIGHT - 50 - this.height;
            } else {
