        }

        // Background
        ctx.fillStyle = 'rgba(0, 0, 0, 0.15)'; // slight trail effect
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Ground line
        ctx.fillStyle = '#4a5568';
        ctx.fillRect(0, CANVAS_HEIGHT - 50, CANVAS_WIDTH, 50);

        player.update();
        enemy.update();

        // Handle Particles
        for(let i = particles.length - 1; i >= 0; i--) {
            particles[i].update();
            if(particles[i].alpha <= 0) particles.splice(i, 1);
        }

        // Handle Projectiles & Collisions
        for(let i = projectiles.length - 1; i >= 0; i--) {
            let p = projectiles[i];
            p.update();
            if(!p.active) {
                projectiles.splice(i, 1);
                continue;
            }

            // Check projectile collision with enemy
            if(p.owner === player && rectangularCollision({
                rectangle1: {position: p.position, width: p.width, height: p.height},
                rectangle2: enemy
            })) {
                enemy.takeHit(10);
                enemyHealthEl.style.width = enemy.health + '%';
                p.active = false;
            }
        }

        // Player Movement
        player.velocity.x = 0;
        if ((keys.a.pressed || keys.ArrowLeft.pressed) && player.lastKey === 'a') {
            player.velocity.x = -7;
        } else if ((keys.d.pressed || keys.ArrowRight.pressed) && player.lastKey === 'd') {
            player.velocity.x = 7;
        }

        // Enemy AI (Simple)
        enemy.velocity.x = 0;
        let dist = player.position.x - enemy.position.x;
        if(dist > 120) {
            enemy.velocity.x = 3;
            enemy.facingRight = true;
        } else if (dist < -120) {
            enemy.velocity.x = -3;
            enemy.facingRight = false;
        } else {
            // Close enough, randomly attack
            if(Math.random() < 0.05 && enemy.cooldown === 0) {
                let attacks = ['punch', 'kick'];
                enemy.attack(attacks[Math.floor(Math.random() * attacks.length)]);
            }
        }

        // Detect Melee Collision (Player attacks Enemy)
        if (
            rectangularCollision({
                rectangle1: player.attackBox,
                rectangle2: enemy
            }) &&
            player.isAttacking &&
            player.attackType !== 'jutsu' // Jutsu handled separately
        ) {
            player.isAttacking = false; // Prevent multiple hits per frame
            let dmg = player.attackType === 'punch' ? 5 : 12;
            enemy.takeHit(dmg);
            enemyHealthEl.style.width = enemy.health + '%';
        }

        // Detect Melee Collision (Enemy attacks Player)
        if (
            rectangularCollision({
                rectangle1: enemy.attackBox,
                rectangle2: player
            }) &&
            enemy.isAttacking
        ) {
            enemy.isAttacking = false;
            let dmg = enemy.attackType === 'punch' ? 5 : 10;
            player.takeHit(dmg);
            playerHealthEl.style.width = player.health + '%';
        }

        // End game based on health
        if (enemy.health <= 0 || player.health <= 0) {
            determineWinner({ player, enemy, timerId });
        }
    }

    // Input Listeners (Keyboard)
    window.addEventListener('keydown', (event) => {
        if(gameState !== 'PLAY') return;
        switch (event.key.toLowerCase()) {
            case 'd':
            case 'arrowright':
                keys.d.pressed = true;
                player.lastKey = 'd';
                break;
            case 'a':
            case 'arrowleft':
                keys.a.pressed = true;
                player.lastKey = 'a';
                break;
            case 'w':
            case 'arrowup':
                if (player.velocity.y === 0) player.velocity.y = -15;
                break;
            case 'j':
                player.attack('punch');
                break;
            case 'k':
                player.attack('kick');
                break;
            case 'l':
                player.attack('jutsu');
                break;
        }
    });

    window.addEventListener('keyup', (event) => {
        switch (event.key.toLowerCase()) {
            case 'd':
            case 'arrowright':
                keys.d.pressed = false;
                break;
            case 'a':
            case 'arrowleft':
                keys.a.pressed = false;
                break;
        }
    });

    // Touch Controls setup
    const addTouch = (id, keyAction, type='press') => {
        const el = document.getElementById(id);
        if(!el) return;
        const trigger = (e) => {
            e.preventDefault();
            if(gameState !== 'PLAY') return;
            if(type === 'press') {
                 if(keyAction === 'left') { keys.a.pressed = true; player.lastKey = 'a'; }
                 if(keyAction === 'right') { keys.d.pressed = true; player.lastKey = 'd'; }
            } else if (type === 'release') {
                 if(keyAction === 'left') keys.a.pressed = false;
                 if(keyAction === 'right') keys.d.pressed = false;
            } else if (type === 'tap') {
                if(keyAction === 'jump' && player.velocity.y === 0) player.velocity.y = -15;
                if(keyAction === 'punch') player.attack('punch');
                if(keyAction === 'kick') player.attack('kick');
                if(keyAction === 'jutsu') player.attack('jutsu');
            }
        };

        if(type === 'press') {
            el.addEventListener('touchstart', trigger, {passive: false});
            el.addEventListener('mousedown', trigger, {passive: false});
        } else if (type === 'release') {
            el.addEventListener('touchend', trigger, {passive: false});
            el.addEventListener('mouseup', trigger, {passive: false});
            el.addEventListener('mouseleave', trigger, {passive: false});
        } else if (type === 'tap') {
            el.addEventListener('touchstart', trigger, {passive: false});
            el.addEventListener('mousedown', trigger, {passive: false});
        }
    }

    addTouch('btn-left', 'left', 'press');
    addTouch('btn-left', 'left', 'release');
    addTouch('btn-right', 'right', 'press');
    addTouch('btn-right', 'right', 'release');
    addTouch('btn-jump', 'jump', 'tap');
    addTouch('btn-punch', 'punch', 'tap');
    addTouch('btn-kick', 'kick', 'tap');
    addTouch('btn-jutsu', 'jutsu', 'tap');


    // Game State Management
    function startGame() {
        if(audioCtx.state === 'suspended') audioCtx.resume();
        startScreen.classList.add('hidden');
        gameOverScreen.classList.add('hidden');
        hud.classList.remove('hidden');
        initGame();
        gameState = 'PLAY';
        decreaseTimer();
        animate();
    }

    startBtn.addEventListener('click', startGame);
    restartBtn.addEventListener('click', startGame);

    // Initial draw to show background before start
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

</script>
</body>
</html>
