    <script>
        // --- Web Audio API for simple sounds ---
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        function playSound(type) {
            if (audioCtx.state === 'suspended') audioCtx.resume();

            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();

            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);

            const now = audioCtx.currentTime;

            if (type === 'shoot') {
                osc.type = 'square';
                osc.frequency.setValueAtTime(440, now);
                osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
                gainNode.gain.setValueAtTime(0.1, now);
                gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
                osc.start(now);
                osc.stop(now + 0.1);
            } else if (type === 'explosion') {
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(100, now);
                osc.frequency.exponentialRampToValueAtTime(0.01, now + 0.5);
                gainNode.gain.setValueAtTime(0.2, now);
                gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
                osc.start(now);
                osc.stop(now + 0.5);
            } else if (type === 'hit') {
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(200, now);
                osc.frequency.exponentialRampToValueAtTime(50, now + 0.2);
                gainNode.gain.setValueAtTime(0.3, now);
                gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
                osc.start(now);
                osc.stop(now + 0.2);
            }
        }

        // --- Game Setup ---
        const canvas = document.getElementById('game-canvas');
        const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2)); // Perf optimization

        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.015);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 3, 7);
        camera.lookAt(0, 0, -10);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 10);
        scene.add(dirLight);

        // --- Materials & Geometries ---
        const trackWidth = 20;
        const trackLength = 200;

        // Grid Floor
        const gridHelper = new THREE.GridHelper(trackWidth * 2, trackLength / 2, 0xff007f, 0x00ffff);
        gridHelper.position.y = -0.5;
        gridHelper.position.z = -trackLength/2 + 10;
        scene.add(gridHelper);

        // Player Car
        const playerGeometry = new THREE.BoxGeometry(1.5, 0.8, 3);
        const playerMaterial = new THREE.MeshPhongMaterial({ color: 0x00ffff, shininess: 100 });
        const player = new THREE.Mesh(playerGeometry, playerMaterial);
        player.position.y = 0;
        scene.add(player);

        // Headlights (visual)
        const hl1 = new THREE.PointLight(0xffffff, 1, 15);
        hl1.position.set(0.5, 0, -1.5);
        player.add(hl1);
        const hl2 = new THREE.PointLight(0xffffff, 1, 15);
        hl2.position.set(-0.5, 0, -1.5);
        player.add(hl2);

        // --- Game Variables ---
        let gameState = 'start'; // start, playing, gameover
        let score = 0;
        let health = 100;
        let speed = 0.5; // Base forward speed simulated by moving environment
        let obstacles = [];
        let projectiles = [];

        const BOUNDARY = trackWidth / 2 - 1;

        // Input state
        const keys = { left: false, right: false, shoot: false };

        // --- Event Listeners ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        window.addEventListener('keydown', (e) => {
            if(gameState !== 'playing') return;
            if(e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = true;
            if(e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = true;
            if(e.code === 'Space') {
                if(!keys.shoot) fireProjectile();
                keys.shoot = true;
            }
        });

        window.addEventListener('keyup', (e) => {
            if(e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;
            if(e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;
            if(e.code === 'Space') keys.shoot = false;
        });

        // UI Buttons
        document.getElementById('start-btn').addEventListener('click', startGame);
        document.getElementById('restart-btn').addEventListener('click', startGame);

        // Mobile Controls
        const btnLeft = document.getElementById('btn-left');
        const btnRight = document.getElementById('btn-right');
        const btnShoot = document.getElementById('btn-shoot');

        btnLeft.addEventListener('touchstart', (e) => { e.preventDefault(); keys.left = true; });
        btnLeft.addEventListener('touchend', (e) => { e.preventDefault(); keys.left = false; });
        btnRight.addEventListener('touchstart', (e) => { e.preventDefault(); keys.right = true; });
        btnRight.addEventListener('touchend', (e) => { e.preventDefault(); keys.right = false; });
        btnShoot.addEventListener('touchstart', (e) => { e.preventDefault(); fireProjectile(); });

        // Show mobile controls if touch device
        if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
            document.getElementById('mobile-controls').classList.remove('hidden');
        }

        // --- Game Logic ---

        function startGame() {
            if (audioCtx.state === 'suspended') audioCtx.resume();

            // Reset variables
            score = 0;
            health = 100;
            speed = 0.5;
            player.position.x = 0;

            // Clear entities
            obstacles.forEach(o => scene.remove(o));
            projectiles.forEach(p => scene.remove(p));
            obstacles = [];
            projectiles = [];

            // UI
            document.getElementById('start-screen').classList.add('hidden');
            document.getElementById('game-over-screen').classList.add('hidden');
            document.getElementById('hud').classList.remove('hidden');
            if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
                document.getElementById('mobile-controls').classList.remove('hidden');
            }
            updateHUD();

            gameState = 'playing';
        }

        function gameOver() {
            gameState = 'gameover';
            document.getElementById('hud').classList.add('hidden');
            document.getElementById('mobile-controls').classList.add('hidden');
            document.getElementById('game-over-screen').classList.remove('hidden');
            document.getElementById('final-score').innerText = score;
        }

        function updateHUD() {
            document.getElementById('score-display').innerText = score;
            const healthEl = document.getElementById('health-display');
            healthEl.innerText = health;
            if(health < 30) healthEl.className = 'text-red-500';
            else if(health < 60) healthEl.className = 'text-yellow-400';
            else healthEl.className = 'text-green-400';
        }

        function fireProjectile() {
            playSound('shoot');
            const geo = new THREE.SphereGeometry(0.3, 8, 8);
            const mat = new THREE.MeshBasicMaterial({ color: 0xff00ff }); // Neon pink
            const proj = new THREE.Mesh(geo, mat);
            proj.position.copy(player.position);
            proj.position.z -= 2; // spawn in front
            scene.add(proj);
            projectiles.push(proj);
        }

        function spawnObstacle() {
            if (Math.random() > 0.05 + (speed * 0.02)) return; // Spawn rate based on speed

            const isEnemy = Math.random() > 0.5;
            const size = isEnemy ? 1.5 : 2;

            const geo = new THREE.BoxGeometry(size, size, size);
            const mat = new THREE.MeshPhongMaterial({ 
                color: isEnemy ? 0xff0000 : 0xaaaaaa, // Red enemies, grey blocks
                emissive: isEnemy ? 0x550000 : 0x000000 
            });

            const obs = new THREE.Mesh(geo, mat);
            obs.position.z = -100; // Far ahead
            obs.position.x = (Math.random() - 0.5) * (trackWidth - 2);
            obs.position.y = size / 2 - 0.5; // Rest on ground

            obs.userData = { isEnemy: isEnemy, hp: isEnemy ? 1 : 3 }; // Enemies die in 1 hit, blocks in 3

            scene.add(obs);
            obstacles.push(obs);
        }

        // Simple AABB Collision
        const box1 = new THREE.Box3();
        const box2 = new THREE.Box3();
        function checkCollision(objA, objB) {
            box1.setFromObject(objA);
            box2.setFromObject(objB);
            return box1.intersectsBox(box2);
        }

        let clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();

            if (gameState === 'playing') {
                // Movement
                const turnSpeed = 15 * delta;
                if (keys.left && player.position.x > -BOUNDARY) {
                    player.position.x -= turnSpeed;
                    player.rotation.z = Math.min(player.rotation.z + 0.1, 0.2); // tilt
                } else if (keys.right && player.position.x < BOUNDARY) {
                    player.position.x += turnSpeed;
                    player.rotation.z = Math.max(player.rotation.z - 0.1, -0.2);
                } else {
                    player.rotation.z *= 0.9; // Return to center
                }

                // Simulate forward movement by moving grid texture (cheap trick)
                // Since GridHelper doesn't have a simple texture offset, we animate its position and loop it
                gridHelper.position.z += speed;
                if (gridHelper.position.z > -trackLength/2 + 20) {
                    gridHelper.position.z = -trackLength/2 + 10;
                }

                // Increase difficulty
                speed += delta * 0.01;
                score += Math.floor(speed * 10 * delta);
                if(score % 100 === 0) updateHUD();

                spawnObstacle();

                // Update Projectiles
                for (let i = projectiles.length - 1; i >= 0; i--) {
                    let p = projectiles[i];
                    p.position.z -= (speed + 1); // Move faster than track

                    if (p.position.z < -120) {
                        scene.remove(p);
                        projectiles.splice(i, 1);
                        continue;
                    }

                    // Check collision with obstacles
                    for (let j = obstacles.length - 1; j >= 0; j--) {
                        let o = obstacles[j];
                        if (checkCollision(p, o)) {
                            // Hit!
                            scene.remove(p);
                            projectiles.splice(i, 1);

                            o.userData.hp--;
                            if (o.userData.hp <= 0) {
                                playSound('explosion');
                                scene.remove(o);
                                obstacles.splice(j, 1);
                                score += o.userData.isEnemy ? 100 : 50;
                                updateHUD();
                            } else {
                                // flash material slightly
                                o.material.emissive.setHex(0xffffff);
                                setTimeout(() => { if(o.material) o.material.emissive.setHex(0x000000); }, 50);
                            }
                            break; // Proj destroyed, stop checking other obstacles
                        }
                    }
                }

                // Update Obstacles & check player collision
                for (let i = obstacles.length - 1; i >= 0; i--) {
                    let o = obstacles[i];
                    o.position.z += speed;

                    if (o.position.z > camera.position.z + 5) {
                        scene.remove(o);
                        obstacles.splice(i, 1);
                        continue;
                    }

                    if (checkCollision(player, o)) {
                        playSound('hit');
                        health -= o.userData.isEnemy ? 20 : 30; // Damage
                        scene.remove(o);
                        obstacles.splice(i, 1);

                        // Screen shake effect
                        camera.position.x = (Math.random() - 0.5) * 0.5;
                        setTimeout(() => { camera.position.x = 0; }, 50);

                        updateHUD();

                        if (health <= 0) {
                            gameOver();
                        }
                    }
                }
            } else if (gameState === 'start') {
                // Idle animation for start screen
                camera.position.x = Math.sin(clock.getElapsedTime() * 0.5) * 5;
                camera.lookAt(0,0,-10);
                gridHelper.position.z += 0.1;
                if (gridHelper.position.z > -trackLength/2 + 20) gridHelper.position.z = -trackLength/2 + 10;
            }

            renderer.render(scene, camera);
        }

        // Start loop
        animate();
    </script>
