    </style>
</head>
<body>

    <canvas id="gameCanvas"></canvas>

    <div id="hud" class="hidden">
        Score: <span id="scoreDisplay">0</span><br>
        Coins: <span id="coinDisplay">0</span>
    </div>

    <div id="ui-layer">
        <!-- Start Screen -->
        <div id="startScreen" class="screen">
            <h1 class="text-5xl font-extrabold mb-4 text-yellow-400" style="text-shadow: 3px 3px 0 #000;">SUPER BLOCK BROS</h1>
            <p class="mb-6 text-xl">Use ARROW KEYS or WASD to move.<br>Press UP or W to jump.</p>
            <button class="btn" onclick="startGame()">Start Game</button>
        </div>

        <!-- Game Over Screen -->
        <div id="gameOverScreen" class="screen hidden">
            <h1 class="text-5xl font-bold mb-4 text-red-500">GAME OVER</h1>
            <p class="text-2xl mb-2">Score: <span id="finalScore">0</span></p>
            <button class="btn" onclick="resetGame()">Play Again</button>
