            </div>
        </div>

        <!-- Boss HP Bar -->
        <div id="boss-ui" class="w-full flex flex-col items-center hidden mt-10">
            <div class="text-red-500 text-xl font-bold uppercase mb-1 hud-text neon-red">AMY THE DESTROYER</div>
            <div class="w-2/3 h-4 bg-gray-900 rounded-sm border border-red-500 overflow-hidden">
                <div id="boss-hp-bar" class="h-full bg-red-600 w-full transition-all duration-100"></div>
            </div>
        </div>

        <div class="text-white/50 text-sm self-center pb-8 text-center" id="controlsHint">
            Swipe/Arrows to Move & Jump<br>Tap/Space to Attack (when Shifted)
        </div>
    </div>

    <!-- Screens -->
    <div id="startScreen" class="absolute inset-0 flex flex-col items-center justify-center overlay pointer-events-auto">
        <h1 class="text-6xl font-black mb-4 neon-blue tracking-wider text-center">SHADOW<br><span class="neon-red">SHIFT</span></h1>
        <p class="text-gray-300 mb-8 max-w-md text-center">Dodge obstacles. Build Energy. Shift Form. Defeat the Boss.</p>
        <div class="grid grid-cols-2 gap-4 text-sm text-gray-400 mb-8 text-center">
            <div><b class="text-white">Move:</b> Left/Right (Swipe)</div>
            <div><b class="text-white">Jump:</b> Up (Swipe)</div>
            <div><b class="text-white">Slide:</b> Down (Swipe)</div>
            <div><b class="text-white">Attack:</b> Space/Tap (Shifted)</div>
        </div>
        <button id="startBtn" class="px-8 py-3 bg-transparent border-2 border-cyan-500 text-cyan-500 font-bold text-xl rounded hover:bg-cyan-500 hover:text-black transition-colors pulse-anim cursor-pointer">START RUN</button>
    </div>

    <div id="gameOverScreen" class="absolute inset-0 flex flex-col items-center justify-center overlay pointer-events-auto hidden">
        <h1 class="text-6xl font-black mb-4 neon-red tracking-wider">SYSTEM FAILURE</h1>
        <div class="text-2xl text-white mb-2">Final Score: <span id="finalScore" class="neon-blue">0</span></div>
        <div id="killMessage" class="text-lg text-gray-400 mb-8"></div>
        <button id="restartBtn" class="px-8 py-3 bg-transparent border-2 border-red-500 text-red-500 font-bold text-xl rounded hover:bg-red-500 hover:text-black transition-colors cursor-pointer pulse-anim">REBOOT</button>
    </div>

<script>
/**
 * Shadow Shift - Core Engine
 * Pseudo-3D Engine using HTML5 Canvas
 */

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d', { alpha: false });
let width, height, centerX, centerY;

// UI Elements
const uiLayer = document.getElementById('ui-layer');
const startScreen = document.getElementById('startScreen');
const gameOverScreen = document.getElementById('gameOverScreen');
const scoreDisplay = document.getElementById('scoreDisplay');
const energyBar = document.getElementById('energy-bar');
const stateDisplay = document.getElementById('stateDisplay');
const bossUI = document.getElementById('boss-ui');
const bossHpBar = document.getElementById('boss-hp-bar');
const controlsHint = document.getElementById('controlsHint');

function resize() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width;
    canvas.height = height;
    centerX = width / 2;
    centerY = height / 2 + height * 0.1; // Horizon slightly below center
}
window.addEventListener('resize', resize);
resize();

// --- Audio System (Web Audio API) ---
let audioCtx;
const initAudio = () => {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
};

const playSound = (type) => {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    const now = audioCtx.currentTime;

    switch(type) {
        case 'jump':
            osc.type = 'sine';
            osc.frequency.setValueAtTime(300, now);
            osc.frequency.exponentialRampToValueAtTime(600, now + 0.1);
            gain.gain.setValueAtTime(0.3, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
            osc.start(now); osc.stop(now + 0.1);
            break;
        case 'hit':
            osc.type = 'square';
            osc.frequency.setValueAtTime(100, now);
            osc.frequency.exponentialRampToValueAtTime(20, now + 0.2);
            gain.gain.setValueAtTime(0.5, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
            osc.start(now); osc.stop(now + 0.2);
            break;
        case 'shift':
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.linearRampToValueAtTime(800, now + 0.5);
            gain.gain.setValueAtTime(0.5, now);
            gain.gain.linearRampToValueAtTime(0.01, now + 1.0);
            osc.start(now); osc.stop(now + 1.0);
            break;
        case 'shoot':
            osc.type = 'square';
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.exponentialRampToValueAtTime(400, now + 0.1);
            gain.gain.setValueAtTime(0.2, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
            osc.start(now); osc.stop(now + 0.1);
            break;
        case 'enemyHit':
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(200, now);
            gain.gain.setValueAtTime(0.4, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
            osc.start(now); osc.stop(now + 0.1);
            break;
        case 'bossExplode':
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(100, now);
            osc.frequency.exponentialRampToValueAtTime(10, now + 1);
            gain.gain.setValueAtTime(0.8, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 1);
            osc.start(now); osc.stop(now + 1);
            break;
    }
};

// --- Game Constants & State ---
const FOV = 300;
const LANE_WIDTH = 200;
const ROAD_LENGTH = 2000;
const BASE_SPEED = 15;
let GAME_SPEED = BASE_SPEED;

let gameState = 'start'; // start, playing, boss, gameover
let score = 0;
let distance = 0;
let frames = 0;
let lastTime = 0;

// --- Projection Math ---
function project(x, y, z) {
    // If behind camera, don't render properly
    if (z < 1) z = 1; 
    const scale = FOV / (FOV + z);
    return {
        x: centerX + (x * scale),
        y: centerY + (y * scale),
        s: scale
    };
}

// --- Entities ---
let entities = [];
let particles = [];
let playerProjectiles = [];
let enemyProjectiles = [];

class Particle {
    constructor(x, y, z, color, vx, vy, vz, life) {
        this.x = x; this.y = y; this.z = z;
        this.color = color;
        this.vx = vx; this.vy = vy; this.vz = vz;
        this.life = life; this.maxLife = life;
    }
    update() {
        this.x += this.vx; this.y += this.vy; this.z += this.vz;
        this.life--;
    }
    draw() {
        if (this.z < 1) return;
        const p = project(this.x, this.y, this.z);
        ctx.globalAlpha = this.life / this.maxLife;
        ctx.fillStyle = this.color;
        const size = Math.max(1, 10 * p.s);
        ctx.fillRect(p.x - size/2, p.y - size/2, size, size);
        ctx.globalAlpha = 1.0;
    }
}

function spawnExplosion(x, y, z, color, count) {
    for(let i=0; i<count; i++) {
        particles.push(new Particle(
            x, y, z, color,
            (Math.random()-0.5)*10, (Math.random()-0.5)*10 - 2, (Math.random()-0.5)*10,
            20 + Math.random()*20
        ));
    }
}

class Player {
    constructor() {
        this.lane = 0; // -1, 0, 1
        this.targetLane = 0;
        this.x = 0;
        this.y = 0; // 0 is ground
        this.z = 50; // slightly in front of camera
        this.vy = 0;
        this.isJumping = false;
        this.isSliding = false;
        this.slideTimer = 0;

        // Shift Mechanics
        this.energy = 0;
        this.maxEnergy = 100;
        this.isShifted = false;
        this.shiftDuration = 600; // frames
        this.shiftTimer = 0;

        this.width = 40;
        this.height = 80;
    }

    update() {
        // Smooth lane transition
        this.targetLane = Math.max(-1, Math.min(1, this.targetLane));
        const targetX = this.targetLane * LANE_WIDTH;
        this.x += (targetX - this.x) * 0.2;

        // Jump physics
        this.y += this.vy;
        if (this.y > 0) { // Moving up
            this.vy -= 1; // Gravity
        } else {
            this.y = 0;
            this.vy = 0;
            this.isJumping = false;
        }

        // Slide
        if (this.isSliding) {
            this.slideTimer--;
            this.height = 40;
            if (this.slideTimer <= 0) {
                this.isSliding = false;
                this.height = 80;
            }
        }

        // Energy & Shift Logic
        if (gameState === 'playing') {
            if (!this.isShifted) {
                this.energy += 0.05; // Passive gain
                if (this.energy >= this.maxEnergy) {
                    this.energy = this.maxEnergy;
                    this.shift();
                }
            } else {
                this.shiftTimer--;
                this.energy = (this.shiftTimer / this.shiftDuration) * this.maxEnergy;
                if (this.shiftTimer <= 0) {
                    this.unshift();
                }
            }
        }
    }

    shift() {
        this.isShifted = true;
        this.shiftTimer = this.shiftDuration;
        playSound('shift');
        stateDisplay.textContent = "SHIFTED";
        stateDisplay.className = "text-white text-xl font-bold hud-text mb-1 neon-red pulse-anim";
        energyBar.className = "h-full bg-fuchsia-500 w-full transition-all duration-100";
        GAME_SPEED = BASE_SPEED * 1.5;
        controlsHint.innerHTML = "Tap/Space to Attack!";
        spawnExplosion(this.x, this.y+40, this.z, '#f0f', 50);
    }

    unshift() {
        this.isShifted = false;
        this.energy = 0;
        stateDisplay.textContent = "NORMAL";
        stateDisplay.className = "text-white text-xl font-bold hud-text mb-1 neon-blue";
        energyBar.className = "h-full bg-cyan-500 transition-all duration-100";
        GAME_SPEED = BASE_SPEED;
        controlsHint.innerHTML = "Swipe/Arrows to Move & Jump";
        spawnExplosion(this.x, this.y+40, this.z, '#0ff', 30);
    }

    shoot() {
        if (!this.isShifted) return;
        playSound('shoot');
        playerProjectiles.push(new Projectile(this.x, this.y + 40, this.z + 10, 0, 0, 40, '#f0f', true));
    }

    draw() {
        const p1 = project(this.x - this.width/2, -this.y, this.z);
        const p2 = project(this.x + this.width/2, -this.y - this.height, this.z);

        const w = p2.x - p1.x;
        const h = p2.y - p1.y;

        ctx.fillStyle = this.isShifted ? '#222' : '#111';
        ctx.fillRect(p1.x, p1.y, w, h);

        // Glow/Outline
        ctx.strokeStyle = this.isShifted ? '#f0f' : '#0ff';
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = ctx.strokeStyle;
        ctx.strokeRect(p1.x, p1.y, w, h);
        ctx.shadowBlur = 0;

        // Trail
        if (frames % 3 === 0) {
            particles.push(new Particle(
                this.x + (Math.random()-0.5)*this.width, 
                this.y + Math.random()*this.height, 
                this.z, 
                this.isShifted ? '#f0f' : '#0ff', 
                0, 0, GAME_SPEED * 0.5, 
                10
            ));
        }
    }
}

class Entity {
    constructor(lane, type) {
        this.lane = lane;
        this.x = lane * LANE_WIDTH;
        this.z = ROAD_LENGTH;
        this.type = type; // 'obstacle', 'enemy'
        this.width = 80;
        this.height = type === 'enemy' ? 100 : 60;
        this.y = 0;
        if(type === 'obstacle' && Math.random() > 0.7) {
            this.height = 120; // High obstacle, slide required
        } else if (type === 'obstacle' && Math.random() > 0.5) {
             this.y = 100; // Airborne, slide or run under
             this.height = 40;
        }

        this.hp = type === 'enemy' ? 2 : 1;
        this.markedForDeletion = false;
        this.color = type === 'enemy' ? '#f00' : '#fa0';
    }

    update() {
        this.z -= GAME_SPEED;
        if (this.z < 0) this.markedForDeletion = true;
    }

    draw() {
        if (this.z < 1) return;
        const p1 = project(this.x - this.width/2, -this.y, this.z);
        const p2 = project(this.x + this.width/2, -this.y - this.height, this.z);
        const w = p2.x - p1.x;
        const h = p2.y - p1.y;

        ctx.fillStyle = '#111';
        ctx.fillRect(p1.x, p1.y, w, h);
        ctx.strokeStyle = this.color;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 15;
        ctx.shadowColor = this.color;
        ctx.strokeRect(p1.x, p1.y, w, h);
        ctx.shadowBlur = 0;

        // Enemy eye
        if (this.type === 'enemy') {
            ctx.fillStyle = '#f00';
            ctx.fillRect(p1.x + w/2 - w*0.1, p1.y + h*0.2, w*0.2, h*0.2);
        }
    }
}

class Projectile {
    constructor(x, y, z, vx, vy, vz, color, isPlayer) {
        this.x = x; this.y = y; this.z = z;
        this.vx = vx; this.vy = vy; this.vz = vz;
        this.color = color;
        this.isPlayer = isPlayer;
        this.markedForDeletion = false;
        this.size = 20;
    }
    update() {
        this.x += this.vx; this.y += this.vy; this.z += this.vz;
        if (this.z > ROAD_LENGTH || this.z < 0) this.markedForDeletion = true;
    }
    draw() {
        if (this.z < 1) return;
        const p = project(this.x, -this.y, this.z);
        ctx.fillStyle = this.color;
        ctx.shadowBlur = 20;
        ctx.shadowColor = this.color;
        const s = Math.max(2, this.size * p.s);
        ctx.beginPath();
        ctx.arc(p.x, p.y, s, 0, Math.PI*2);
        ctx.fill();
        ctx.shadowBlur = 0;
    }
}

class Boss {
    constructor() {
        this.x = 0;
        this.y = 150;
        this.z = 1000;
        this.width = 300;
        this.height = 300;
        this.hp = 100;
        this.maxHp = 100;
        this.state = 'intro';
        this.timer = 0;
        this.targetX = 0;

        bossUI.classList.remove('hidden');
        this.updateHpBar();
    }

    updateHpBar() {
        bossHpBar.style.width = `${(this.hp/this.maxHp)*100}%`;
    }

    update() {
        this.timer++;

        if (this.state === 'intro') {
            this.z -= 5;
            if (this.z <= 600) {
                this.z = 600;
                this.state = 'attack';
                this.timer = 0;
            }
        } else if (this.state === 'attack') {
            // Hover movement
            this.y = 150 + Math.sin(this.timer * 0.05) * 50;

            // Move between lanes
            if (this.timer % 120 === 0) {
                const lanes = [-1, 0, 1];
                this.targetX = lanes[Math.floor(Math.random() * lanes.length)] * LANE_WIDTH;
            }
            this.x += (this.targetX - this.x) * 0.05;

            // Attack patterns
            if (this.timer % 40 === 0 && Math.random() > 0.3) {
                playSound('shoot');
                enemyProjectiles.push(new Projectile(this.x, this.y, this.z - 50, 0, 0, -25, '#f00', false));

                // Spread shot
                if (this.hp < 50 && Math.random() > 0.5) {
                    enemyProjectiles.push(new Projectile(this.x, this.y, this.z - 50, -5, 0, -20, '#f00', false));
                    enemyProjectiles.push(new Projectile(this.x, this.y, this.z - 50, 5, 0, -20, '#f00', false));
                }
            }
        }
    }

    takeDamage(amount) {
        this.hp -= amount;
        this.updateHpBar();
        spawnExplosion(this.x, this.y, this.z, '#ff0', 20);
        playSound('enemyHit');

        if (this.hp <= 0) {
            playSound('bossExplode');
            spawnExplosion(this.x, this.y, this.z, '#f00', 200);
            spawnExplosion(this.x, this.y, this.z, '#ff0', 100);
            bossUI.classList.add('hidden');
            gameState = 'playing'; // Resume normal run
            score += 5000;
            player.energy = player.maxEnergy; // Insta shift
            player.shift();
            boss = null;
        }
    }

    draw() {
        if (!boss) return;
        const p1 = project(this.x - this.width/2, -this.y, this.z);
        const p2 = project(this.x + this.width/2, -this.y - this.height, this.z);
        const w = p2.x - p1.x;
        const h = p2.y - p1.y;

        // Core
        ctx.fillStyle = '#200';
        ctx.fillRect(p1.x, p1.y, w, h);
        ctx.strokeStyle = '#f00';
        ctx.lineWidth = 5;
        ctx.shadowBlur = 30;
        ctx.shadowColor = '#f00';
        ctx.strokeRect(p1.x, p1.y, w, h);

        // Eyes
        ctx.fillStyle = '#fff';
        const eyeW = w*0.2;
        const eyeH = h*0.1;
        ctx.fillRect(p1.x + w*0.2, p1.y + h*0.3, eyeW, eyeH);
        ctx.fillRect(p1.x + w*0.6, p1.y + h*0.3, eyeW, eyeH);

        ctx.shadowBlur = 0;
    }
}

// --- Globals ---
let player;
let boss = null;
let bossScoreThreshold = 3000;

// --- Input Handling ---
let touchStartX = 0;
let touchStartY = 0;

function handleInput(type) {
    if (gameState === 'start' || gameState === 'gameover') {
        startGame();
        return;
    }

    if (gameState !== 'playing' && gameState !== 'boss') return;

    if (type === 'left' && player.targetLane > -1) player.targetLane--;
    if (type === 'right' && player.targetLane < 1) player.targetLane++;
    if (type === 'up' && !player.isJumping) {
        player.vy = 20;
        player.isJumping = true;
        player.isSliding = false;
        playSound('jump');
    }
    if (type === 'down' && !player.isJumping) {
        player.isSliding = true;
        player.slideTimer = 30;
    }
    if (type === 'action') {
        player.shoot();
    }
}

window.addEventListener('keydown', (e) => {
    initAudio();
    if (e.key === 'ArrowLeft' || e.key === 'a') handleInput('left');
    if (e.key === 'ArrowRight' || e.key === 'd') handleInput('right');
    if (e.key === 'ArrowUp' || e.key === 'w') handleInput('up');
    if (e.key === 'ArrowDown' || e.key === 's') handleInput('down');
    if (e.key === ' ') handleInput('action');
});

// Touch controls for mobile
window.addEventListener('touchstart', e => {
    initAudio();
    touchStartX = e.changedTouches[0].screenX;
    touchStartY = e.changedTouches[0].screenY;
}, {passive: false});

window.addEventListener('touchend', e => {
    if (gameState === 'start' || gameState === 'gameover') {
        startGame();
        return;
    }

    const touchEndX = e.changedTouches[0].screenX;
    const touchEndY = e.changedTouches[0].screenY;
    const dx = touchEndX - touchStartX;
    const dy = touchEndY - touchStartY;

    // Tap to shoot
    if (Math.abs(dx) < 30 && Math.abs(dy) < 30) {
        handleInput('action');
        return;
    }

    if (Math.abs(dx) > Math.abs(dy)) {
        if (dx > 30) handleInput('right');
        else if (dx < -30) handleInput('left');
    } else {
        if (dy > 30) handleInput('down');
        else if (dy < -30) handleInput('up');
    }
}, {passive: false});

// Prevent default scrolling on canvas
canvas.addEventListener('touchmove', e => e.preventDefault(), {passive: false});

// --- Game Logic ---

function startGame() {
    initAudio();
    player = new Player();
    entities = [];
    particles = [];
    playerProjectiles = [];
    enemyProjectiles = [];
    boss = null;
    score = 0;
    distance = 0;
    frames = 0;
    GAME_SPEED = BASE_SPEED;
    bossScoreThreshold = 3000;

    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
    uiLayer.classList.remove('hidden');
    bossUI.classList.add('hidden');

    gameState = 'playing';
    updateHUD();
}

function gameOver(reason) {
    gameState = 'gameover';
    playSound('hit');
    spawnExplosion(player.x, player.y+40, player.z, '#fff', 100);

    setTimeout(() => {
        uiLayer.classList.add('hidden');
        gameOverScreen.classList.remove('hidden');
        document.getElementById('finalScore').textContent = Math.floor(score);
        document.getElementById('killMessage').textContent = reason;
    }, 1000);
}

function checkCollisions() {
    // Player vs Entities
    const pRect = {
        x: player.x - player.width/2 + 10, w: player.width - 20,
        y: player.y, h: player.height
    };

    for (let i = entities.length - 1; i >= 0; i--) {
        const ent = entities[i];
        // Check Z collision depth
        if (ent.z < player.z + 20 && ent.z > player.z - 40) {
            const eRect = {
                x: ent.x - ent.width/2, w: ent.width,
                y: ent.y, h: ent.height
            };

            // AABB Collision 2D (x,y)
            if (pRect.x < eRect.x + eRect.w &&
                pRect.x + pRect.w > eRect.x &&
                pRect.y < eRect.y + eRect.h &&
                pRect.y + pRect.h > eRect.y) {

                if (player.isShifted && ent.type === 'enemy') {
                    // Ramming enemies while shifted destroys them
                    ent.markedForDeletion = true;
                    score += 50;
                    spawnExplosion(ent.x, ent.y+50, ent.z, '#f00', 30);
                    playSound('enemyHit');
                } else {
                    gameOver("Collision detected.");
                    return;
                }
            }
        }
    }

    // Player vs Enemy Projectiles
    for (let i = enemyProjectiles.length - 1; i >= 0; i--) {
        const p = enemyProjectiles[i];
        if (p.z < player.z + 20 && p.z > player.z - 20) {
            const distSq = (p.x - player.x)**2 + (p.y - (player.y+player.height/2))**2;
            if (distSq < (player.width/2 + p.size)**2) {
                gameOver("Hit by energy blast.");
                return;
            }
        }
    }

    // Player Projectiles vs Entities & Boss
    for (let i = playerProjectiles.length - 1; i >= 0; i--) {
        const proj = playerProjectiles[i];

        // Boss
        if (boss && proj.z > boss.z - 50 && proj.z < boss.z + 50) {
            if (Math.abs(proj.x - boss.x) < boss.width/2 && 
                proj.y > boss.y && proj.y < boss.y + boss.height) {
                proj.markedForDeletion = true;
                boss.takeDamage(5);
                continue;
            }
        }

        // Entities
        for (let j = entities.length - 1; j >= 0; j--) {
            const ent = entities[j];
            if (proj.z > ent.z - 50 && proj.z < ent.z + 50) {
                if (Math.abs(proj.x - ent.x) < ent.width/2 && 
                    proj.y > ent.y && proj.y < ent.y + ent.height) {

                    proj.markedForDeletion = true;
                    ent.hp--;
                    playSound('enemyHit');
                    spawnExplosion(ent.x, ent.y+50, ent.z, '#fff', 10);

                    if (ent.hp <= 0) {
                        ent.markedForDeletion = true;
                        score += 100;
                        spawnExplosion(ent.x, ent.y+50, ent.z, ent.color, 30);
                    }
                    break; // Projectile destroyed
                }
            }
        }
    }
}

function updateHUD() {
    scoreDisplay.textContent = `SCORE: ${Math.floor(score)}`;
    energyBar.style.width = `${(player.energy / player.maxEnergy) * 100}%`;
}

function drawBackground() {
    // Grid Lines to simulate movement
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, width, height);

    ctx.strokeStyle = player && player.isShifted ? '#404' : '#044';
    ctx.lineWidth = 1;

    // Horizon line
    ctx.beginPath();
    ctx.moveTo(0, centerY);
    ctx.lineTo(width, centerY);
    ctx.stroke();

    // Lane lines
    for (let i = -2; i <= 2; i++) {
        const xOffset = i * LANE_WIDTH;
        const p1 = project(xOffset, 0, 10);
        const p2 = project(xOffset, 0, ROAD_LENGTH);
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();
    }

    // Moving horizontal lines
    const lineSpacing = 200;
    const offset = (distance % lineSpacing);
    for (let z = offset; z < ROAD_LENGTH; z += lineSpacing) {
        const pLeft = project(-LANE_WIDTH*2, 0, z);
        const pRight = project(LANE_WIDTH*2, 0, z);

        // Fade out in distance
        ctx.globalAlpha = Math.max(0, 1 - (z / ROAD_LENGTH));
        ctx.beginPath();
        ctx.moveTo(pLeft.x, pLeft.y);
        ctx.lineTo(pRight.x, pRight.y);
        ctx.stroke();
    }
    ctx.globalAlpha = 1.0;
}

function loop(timestamp) {
    requestAnimationFrame(loop);

    // Throttle frame rate slightly to ensure consistent physics if needed, 
    // but standard rAF is usually 60fps.
    const dt = timestamp - lastTime;
    if (dt < 16) return; // Cap at ~60fps
    lastTime = timestamp;

    ctx.clearRect(0, 0, width, height);

    if (gameState === 'start') return;

    drawBackground();

    if (gameState === 'playing' || gameState === 'boss') {
        frames++;
        distance += GAME_SPEED;
        score += GAME_SPEED * 0.01;

        // Spawning Logic
        if (gameState === 'playing' && frames % Math.floor(60 / (GAME_SPEED/BASE_SPEED)) === 0) {
            const lane = Math.floor(Math.random() * 3) - 1; // -1, 0, 1
            const type = (player.isShifted || Math.random() > 0.8) ? 'enemy' : 'obstacle';
            entities.push(new Entity(lane, type));
        }

        // Boss Trigger
        if (gameState === 'playing' && score > bossScoreThreshold) {
            gameState = 'boss';
            bossScoreThreshold += 5000;
            boss = new Boss();
            player.unshift(); // Force unshift for boss intro
        }

        player.update();
        if (boss) boss.update();

        // Update Arrays
        entities.forEach(e => e.update());
        entities = entities.filter(e => !e.markedForDeletion);

        particles.forEach(p => p.update());
        particles = particles.filter(p => p.life > 0);

        playerProjectiles.forEach(p => p.update());
        playerProjectiles = playerProjectiles.filter(p => !p.markedForDeletion);

        enemyProjectiles.forEach(p => p.update());
        enemyProjectiles = enemyProjectiles.filter(p => !p.markedForDeletion);

        checkCollisions();
        updateHUD();
    }

    // --- Rendering ---

    // Collect all renderable objects to sort by Z-depth (Painters Algorithm)
    let renderList = [];
    if (gameState !== 'gameover') {
        renderList.push({ z: player.z, draw: () => player.draw() });
    }
    if (boss) {
        renderList.push({ z: boss.z, draw: () => boss.draw() });
    }
    entities.forEach(e => renderList.push({ z: e.z, draw: () => e.draw() }));
    particles.forEach(p => renderList.push({ z: p.z, draw: () => p.draw() }));
    playerProjectiles.forEach(p => renderList.push({ z: p.z, draw: () => p.draw() }));
    enemyProjectiles.forEach(p => renderList.push({ z: p.z, draw: () => p.draw() }));

    // Sort descending (furthest first)
    renderList.sort((a, b) => b.z - a.z);

    renderList.forEach(obj => obj.draw());
}

// Button Listeners
document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('restartBtn').addEventListener('click', startGame);

// Start loop
requestAnimationFrame(loop);

</script>
