                let distToPlayer = player.pos.sub(this.pos).mag();
                if (distToPlayer > 60) {
                    let dir = player.pos.sub(this.pos).normalize();
                    // Flocking behavior - slightly offset from direct path
                    let offset = new Vector(Math.cos(frameCount*0.05), Math.sin(frameCount*0.05)).mult(20);
                    let targetPos = player.pos.sub(dir.mult(50)).add(offset);

                    let moveDir = targetPos.sub(this.pos).normalize();
                    this.pos = this.pos.add(moveDir.mult(this.speed));
                }

                // Find target
                let closest = null;
                let minDist = 400; // Agro range
                for (let e of enemies) {
                    let d = e.pos.sub(this.pos).mag();
                    if (d < minDist) {
                        minDist = d;
                        closest = e;
                    }
                }
                this.targetEnemy = closest;

                // Shoot
                if (this.targetEnemy && frameCount - this.lastShot > this.fireRate) {
                    this.shoot(this.targetEnemy.pos);
                    this.lastShot = frameCount;
                }

                // Zone damage
                let distToCenter = new Vector(width/2, height/2).sub(this.pos).mag();
                if (distToCenter > safeZone.radius && frameCount % 30 === 0) {
                    this.takeDamage(2); // takes less zone damage
                }

                allyHpBar.style.width = `${(this.hp / this.maxHp) * 100}%`;
            }
            shoot(targetPos) {
