                let distToPlayer = player.pos.sub(this.pos).mag();
                let distToAlly = ally && ally.hp > 0 ? ally.pos.sub(this.pos).mag() : Infinity;

                let targetPos = (distToPlayer < distToAlly) ? player.pos : ally.pos;

                let dir = targetPos.sub(this.pos).normalize();
                this.pos = this.pos.add(dir.mult(this.speed));

                // Collision with players
                if (distToPlayer < this.radius + player.radius) {
