            }
        }

        class Particle {
            constructor(x, y, color) {
                this.pos = new Vector(x, y);
                this.vel = new Vector((Math.random()-0.5)*5, (Math.random()-0.5)*5);
                this.life = 20 + Math.random()*20;
                this.color = color;
                this.radius = Math.random() * 3;
