            update() {
                this.pos = this.pos.add(this.vel);
                this.life--;
            }
            draw() {
                ctx.globalAlpha = this.life / 40;
                ctx.beginPath();
                ctx.arc(this.pos.x, this.pos.y, this.radius, 0, Math.PI * 2);
                ctx.fillStyle = this.color;
                ctx.fill();
                ctx.globalAlpha = 1.0;
            }
        }

        // --- Game State Variables ---
        let player, ally;
        let enemies = [];
        let bullets = [];
        let particles = [];
        let safeZone = { radius: 0, maxRadius: 0 };
        let terrain = []; // Simple grass patches

        function initGame() {
            score = 0;
            scoreEl.innerText = score;
            frameCount = 0;
            enemies = [];
            bullets = [];
            particles = [];

            player = new Player(width / 2 - 20, height / 2);
            ally = new Ally(width / 2 + 20, height / 2);

            safeZone.maxRadius = Math.max(width, height) * 0.8;
            safeZone.radius = safeZone.maxRadius;

            // Generate simple terrain pattern
            terrain = [];
            for(let i=0; i<30; i++) {
                terrain.push({
                    x: Math.random() * width,
                    y: Math.random() * height,
                    r: 20 + Math.random() * 50,
                    color: `rgba(45, 100, 35, ${0.1 + Math.random()*0.1})`
                });
            }

            gameState = 'PLAY';
            uiStart.classList.add('hidden');
            uiGameOver.classList.add('hidden');
            uiHUD.classList.remove('hidden');

            gameLoop();
        }

        function spawnEnemy() {
            // Spawn outside the view
            let angle = Math.random() * Math.PI * 2;
            let dist = Math.max(width, height) / 2 + 50;
            let cx = width / 2;
            let cy = height / 2;
            let x = cx + Math.cos(angle) * dist;
            let y = cy + Math.sin(angle) * dist;

            // Sometimes spawn at edges instead of pure circle
            if(Math.random() < 0.5) {
                if(Math.random() < 0.5) {
                    x = Math.random() < 0.5 ? -30 : width + 30;
                    y = Math.random() * height;
                } else {
                    x = Math.random() * width;
                    y = Math.random() < 0.5 ? -30 : height + 30;
                }
            }

            enemies.push(new Enemy(x, y));
        }

        function createExplosion(x, y, color, count=10) {
            for(let i=0; i<count; i++) {
                particles.push(new Particle(x, y, color));
            }
        }

        function gameOver() {
            gameState = 'OVER';
            uiHUD.classList.add('hidden');
            uiGameOver.classList.remove('hidden');
            finalScoreEl.innerText = score;
        }

        function drawBackground() {
            // Base grass
            ctx.fillStyle = '#2b4c1e'; // Dark green
            ctx.fillRect(0, 0, width, height);

            // Terrain patches
            terrain.forEach(t => {
                ctx.beginPath();
                ctx.arc(t.x, t.y, t.r, 0, Math.PI*2);
                ctx.fillStyle = t.color;
                ctx.fill();
            });

            // Safe Zone
            ctx.beginPath();
            ctx.arc(width/2, height/2, safeZone.radius, 0, Math.PI*2);
            ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
            ctx.fill();
            ctx.strokeStyle = 'rgba(59, 130, 246, 0.5)'; // Blue border
            ctx.lineWidth = 4;
            ctx.stroke();

            // Outside zone darkener
            ctx.beginPath();
            ctx.rect(0,0,width,height);
            ctx.arc(width/2, height/2, safeZone.radius, 0, Math.PI*2, true);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
            ctx.fill();
        }

        function gameLoop() {
            if (gameState !== 'PLAY') return;
            requestAnimationFrame(gameLoop);

            ctx.clearRect(0, 0, width, height);
            drawBackground();

            frameCount++;

            // Shrink Zone slowly
            if (safeZone.radius > 50 && frameCount % 5 === 0) {
                safeZone.radius -= 0.2;
            }

            // Spawn mechanics - harder over time
            let spawnRate = Math.max(20, 100 - Math.floor(frameCount / 100));
            if (frameCount % spawnRate === 0) {
                spawnEnemy();
                if (frameCount > 1000 && Math.random() < 0.3) spawnEnemy(); // Double spawn later
            }

            // Update & Draw Ally
            if (ally.hp > 0) {
                ally.update();
                ally.draw();
            }

            // Update & Draw Player
            player.update();
            player.draw();

            // Update & Draw Bullets
            for (let i = bullets.length - 1; i >= 0; i--) {
                let b = bullets[i];
                b.update();
                b.draw();

                // Out of bounds / life
                if (b.life <= 0 || b.pos.x < 0 || b.pos.x > width || b.pos.y < 0 || b.pos.y > height) {
                    bullets.splice(i, 1);
                    continue;
                }

                // Collision with enemies
                let hit = false;
                if (b.owner === 'player' || b.owner === 'ally') {
                    for (let j = enemies.length - 1; j >= 0; j--) {
                        let e = enemies[j];
                        let dist = b.pos.sub(e.pos).mag();
                        if (dist < e.radius + b.radius) {
                            e.takeDamage(10);
                            createExplosion(b.pos.x, b.pos.y, '#fca5a5', 3);
                            playSound('hit');
                            hit = true;
                            if (e.hp <= 0) {
                                createExplosion(e.pos.x, e.pos.y, '#ef4444', 15);
                                enemies.splice(j, 1);
                                if (b.owner === 'player') {
                                    score++;
                                    scoreEl.innerText = score;
                                }
                            }
                            break;
                        }
                    }
                }
                if (hit) bullets.splice(i, 1);
            }

            // Update & Draw Enemies
            for (let i = enemies.length - 1; i >= 0; i--) {
                let e = enemies[i];
                e.update();
                e.draw();
            }

            // Update & Draw Particles
            for (let i = particles.length - 1; i >= 0; i--) {
                let p = particles[i];
                p.update();
                p.draw();
                if (p.life <= 0) particles.splice(i, 1);
            }

            // Draw crosshair
            if(mouse.x && mouse.y) {
                ctx.beginPath();
                ctx.arc(mouse.x, mouse.y, 5, 0, Math.PI*2);
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
            }
        }

        // Buttons
        document.getElementById('start-btn').addEventListener('click', initGame);
        document.getElementById('restart-btn').addEventListener('click', initGame);

        // Initial draw
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(0,0,width,height);

    </script>
</body>
</html>
