        const words = [
            { id: '1', word: 'ROCHICHINARD', row: 2, col: 0, dir: 'h', clue: '1A. Forteresse en ruine accrochée à la falaise du Vercors.' },
            { id: '2', word: 'ROYANS', row: 7, col: 6, dir: 'h', clue: '2A. Région naturelle aux portes du Vercors.' },
            { id: '3', word: 'ZIZIM', row: 1, col: 4, dir: 'v', clue: '1D. Prince ottoman retenu prisonnier en France (Djem Sultan).' },
            { id: '4', word: 'CHATEAU', row: 2, col: 2, dir: 'v', clue: '2D. Édifice fortifié.' },
            { id: '5', word: 'ALLEMAN', row: 2, col: 9, dir: 'v', clue: '3D. Grande famille noble du Dauphiné.' }
        ];

        const GRID_COLS = 12;
        const GRID_ROWS = 9;

        let grid = [];
        let currentDirection = 'h'; // 'h' or 'v'
        let selectedCell = null; // {r, c}

        // Initialize empty grid
        for (let r = 0; r < GRID_ROWS; r++) {
            grid[r] = [];
            for (let c = 0; c < GRID_COLS; c++) {
                grid[r][c] = { isActive: false, letter: '', number: null, words: { h: null, v: null } };
            }
        }

        // Populate grid data
        words.forEach(w => {
            let r = w.row;
            let c = w.col;

            // Set number at start of word
            if (!grid[r][c].number) {
                // Determine display number (1, 2, 3...) based on ID or custom logic. 
                // For simplicity, just use the first digit of the clue
                grid[r][c].number = w.clue.match(/^\d+/)[0]; 
            }

            for (let i = 0; i < w.word.length; i++) {
                grid[r][c].isActive = true;
                grid[r][c].letter = w.word[i];
                grid[r][c].words[w.dir] = w.id;

                if (w.dir === 'h') c++;
                else r++;
            }
        });

        // UI Initialization
        const gridContainer = document.getElementById('grid-container');
        gridContainer.style.gridTemplateRows = `repeat(${GRID_ROWS}, 1fr)`;

        function renderGrid() {
            gridContainer.innerHTML = '';
            for (let r = 0; r < GRID_ROWS; r++) {
                for (let c = 0; c < GRID_COLS; c++) {
                    const cellData = grid[r][c];
                    const cellEl = document.createElement('div');
                    cellEl.className = `cell ${cellData.isActive ? 'active bg-white' : ''}`;
                    cellEl.dataset.r = r;
                    cellEl.dataset.c = c;

                    if (cellData.isActive) {
                        if (cellData.number) {
                            const numEl = document.createElement('span');
                            numEl.className = 'cell-number';
                            numEl.textContent = cellData.number;
                            cellEl.appendChild(numEl);
                        }

                        const input = document.createElement('input');
                        input.type = 'text';
                        input.maxLength = 1;
                        input.dataset.r = r;
                        input.dataset.c = c;

                        input.addEventListener('focus', handleFocus);
                        input.addEventListener('keydown', handleKeydown);
                        input.addEventListener('input', handleInput);
                        input.addEventListener('click', handleClick);

                        cellEl.appendChild(input);
                    }
                    gridContainer.appendChild(cellEl);
                }
            }
        }

        function renderClues() {
            const hList = document.getElementById('clues-horizontal');
            const vList = document.getElementById('clues-vertical');

            hList.innerHTML = '';
            vList.innerHTML = '';

            words.forEach(w => {
                const li = document.createElement('li');
                li.textContent = w.clue;
                li.dataset.wordId = w.id;
                li.addEventListener('click', () => selectWord(w.id, w.dir));

                if (w.dir === 'h') hList.appendChild(li);
                else vList.appendChild(li);
            });
        }

        // Interaction Logic
        function getCellInput(r, c) {
            return document.querySelector(`input[data-r="${r}"][data-c="${c}"]`);
        }

        function getCellDiv(r, c) {
            return document.querySelector(`.cell[data-r="${r}"][data-c="${c}"]`);
        }

        function clearHighlights() {
            document.querySelectorAll('.cell.highlighted').forEach(el => el.classList.remove('highlighted'));
            document.querySelectorAll('.clue-list li').forEach(el => el.classList.remove('active-clue'));
        }

        function highlightWord(wordId, dir) {
            clearHighlights();
            const w = words.find(x => x.id === wordId);
            if (!w) return;

            let r = w.row;
            let c = w.col;

            for (let i = 0; i < w.word.length; i++) {
                const cellDiv = getCellDiv(r, c);
                if(cellDiv) cellDiv.classList.add('highlighted');
                if (dir === 'h') c++; else r++;
            }

            const clueEl = document.querySelector(`li[data-word-id="${wordId}"]`);
            if (clueEl) {
                clueEl.classList.add('active-clue');
                clueEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }
        }

        function selectWord(wordId, dir) {
            const w = words.find(x => x.id === wordId);
            if (!w) return;
            currentDirection = dir;
            highlightWord(wordId, dir);
            const firstInput = getCellInput(w.row, w.col);
            if (firstInput) {
                // Prevent re-triggering focus logic immediately
                setTimeout(() => firstInput.focus(), 10);
            }
        }

        function handleClick(e) {
            const r = parseInt(e.target.dataset.r);
            const c = parseInt(e.target.dataset.c);
            const cellData = grid[r][c];

            // Toggle direction if cell belongs to both
            if (selectedCell && selectedCell.r === r && selectedCell.c === c) {
                if (cellData.words.h && cellData.words.v) {
                    currentDirection = currentDirection === 'h' ? 'v' : 'h';
                }
            } else {
                // Prefer current direction if cell supports it, otherwise switch
                if (!cellData.words[currentDirection]) {
                    currentDirection = currentDirection === 'h' ? 'v' : 'h';
                }
            }

            const wordId = cellData.words[currentDirection];
            if(wordId) highlightWord(wordId, currentDirection);
            selectedCell = {r, c};
        }

        function handleFocus(e) {
            const r = parseInt(e.target.dataset.r);
            const c = parseInt(e.target.dataset.c);

            // Only handle focus if it wasn't triggered by click (handled above)
            if(!selectedCell || selectedCell.r !== r || selectedCell.c !== c) {
                const cellData = grid[r][c];
                if (!cellData.words[currentDirection]) {
                    currentDirection = currentDirection === 'h' ? 'v' : 'h';
                }
                const wordId = cellData.words[currentDirection];
                if(wordId) highlightWord(wordId, currentDirection);
                selectedCell = {r, c};
            }
        }

        function handleInput(e) {
            const input = e.target;
            input.value = input.value.toUpperCase();

            if (input.value) {
                playTypeSound();
                // Move to next
                let r = parseInt(input.dataset.r);
                let c = parseInt(input.dataset.c);

                if (currentDirection === 'h') c++;
                else r++;

                const nextInput = getCellInput(r, c);
                const currentWordId = grid[parseInt(input.dataset.r)][parseInt(input.dataset.c)].words[currentDirection];

                if (nextInput && grid[r] && grid[r][c] && grid[r][c].words[currentDirection] === currentWordId) {
                    nextInput.focus();
                } else {
                    checkWinSilently();
                }
            }
        }

        function handleKeydown(e) {
            const input = e.target;
            let r = parseInt(input.dataset.r);
            let c = parseInt(input.dataset.c);

            if (e.key === 'Backspace' && !input.value) {
                if (currentDirection === 'h') c--;
                else r--;
                const prevInput = getCellInput(r, c);
                const currentWordId = grid[parseInt(input.dataset.r)][parseInt(input.dataset.c)].words[currentDirection];

                if (prevInput && grid[r] && grid[r][c] && grid[r][c].words[currentDirection] === currentWordId) {
                    prevInput.focus();
                    prevInput.value = ''; // clear it
                    e.preventDefault();
                }
            } else if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                e.preventDefault();
                let nextR = r, nextC = c;
                if(e.key === 'ArrowRight') nextC++;
                if(e.key === 'ArrowLeft') nextC--;
                if(e.key === 'ArrowDown') nextR++;
                if(e.key === 'ArrowUp') nextR--;

                const nextInput = getCellInput(nextR, nextC);
                if(nextInput) {
                    // Update direction based on arrow key naturally
                    if(e.key === 'ArrowRight' || e.key === 'ArrowLeft') currentDirection = 'h';
                    if(e.key === 'ArrowDown' || e.key === 'ArrowUp') currentDirection = 'v';
                    nextInput.focus();
                }
            }
        }

        function isGridCorrect() {
            for (let r = 0; r < GRID_ROWS; r++) {
                for (let c = 0; c < GRID_COLS; c++) {
                    if (grid[r][c].isActive) {
                        const input = getCellInput(r, c);
                        if (!input || input.value.toUpperCase() !== grid[r][c].letter) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        function checkWinSilently() {
            if (isGridCorrect()) {
                setTimeout(showWinScreen, 300);
            }
        }

        function checkGrid() {
            let correct = 0;
            let total = 0;
            let filled = 0;

            for (let r = 0; r < GRID_ROWS; r++) {
                for (let c = 0; c < GRID_COLS; c++) {
                    if (grid[r][c].isActive) {
                        total++;
                        const input = getCellInput(r, c);
                        const cellDiv = getCellDiv(r, c);
                        if (input && input.value) {
                            filled++;
                            if (input.value.toUpperCase() === grid[r][c].letter) {
                                correct++;
                                input.style.color = 'green';
                            } else {
                                input.style.color = 'red';
                            }
                            // Reset color after a bit
                            setTimeout(() => { if(input) input.style.color = '#111827'; }, 1500);
                        }
                    }
                }
            }

            if(correct === total) {
                showWinScreen();
            } else if (filled === 0) {
                alert("Commencez par remplir la grille !");
            } else {
                alert(`Vous avez ${correct} lettres correctes sur ${total}. Continuez !`);
            }
        }

        function createConfetti() {
            const colors = ['#f59e0b', '#3b82f6', '#ef4444', '#10b981'];
            for(let i=0; i<100; i++) {
                const conf = document.createElement('div');
                conf.className = 'confetti';
                conf.style.left = Math.random() * 100 + 'vw';
                conf.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                conf.style.animationDuration = (Math.random() * 3 + 2) + 's';
                conf.style.animationDelay = (Math.random() * 2) + 's';
                document.getElementById('win-screen').appendChild(conf);
            }
        }

        function showWinScreen() {
            document.getElementById('game-screen').classList.remove('active');
            document.getElementById('win-screen').classList.add('active');
            playWinSound();
            createConfetti();
        }

        function startGame() {
            document.getElementById('start-screen').classList.remove('active');
            document.getElementById('game-screen').classList.add('active');
            renderGrid();
            renderClues();
            // Select first word
            selectWord(words[0].id, words[0].dir);
        }

    </script>
</body>
