        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 120);
        camera.position.set(0, 5, 10);
        camera.lookAt(0, 0, -10);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        scene.add(dirLight);

        // --- Materials ---
        const playerMat = new THREE.MeshLambertMaterial({ color: 0xff3333 });
        const groundMat = new THREE.MeshLambertMaterial({ color: 0x33aa33 });
        const obstacleMat = new THREE.MeshLambertMaterial({ color: 0x3333ff });
        const coinMat = new THREE.MeshLambertMaterial({ color: 0xffd700, emissive: 0x444400 });

        // --- Environment ---
        // Create moving ground effect using a grid of lines
        const gridHelper = new THREE.GridHelper(100, 50, 0x000000, 0x000000);
        gridHelper.material.opacity = 0.2;
        gridHelper.material.transparent = true;
        gridHelper.position.y = -0.01;
        scene.add(gridHelper);

        const groundGeometry = new THREE.PlaneGeometry(100, 200);
        const ground = new THREE.Mesh(groundGeometry, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Player ---
        const playerGeometry = new THREE.BoxGeometry(1, 1, 1);
        const player = new THREE.Mesh(playerGeometry, playerMat);
        player.castShadow = true;
        scene.add(player);

        // Player physics/movement state
        let currentLane = 0; // -1 (left), 0 (center), 1 (right)
        let playerVelocityY = 0;
        let isJumping = false;
        const playerBaseY = 0.5;

        // Player collision box
        const playerBox = new THREE.Box3();

        // --- Objects (Obstacles & Coins) ---
        const activeObjects = [];
        const objectPool = [];
        let spawnTimer = 0;

        function createObstacle() {
            const geom = new THREE.BoxGeometry(1.5, Math.random() > 0.5 ? 2 : 1, 1.5);
            const mesh = new THREE.Mesh(geom, obstacleMat);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            mesh.userData = { type: 'obstacle', box: new THREE.Box3() };
            return mesh;
        }

        function createCoin() {
            const geom = new THREE.TorusGeometry(0.4, 0.1, 8, 16);
            const mesh = new THREE.Mesh(geom, coinMat);
            mesh.castShadow = true;
            mesh.rotation.x = Math.PI / 2;
            mesh.userData = { type: 'coin', box: new THREE.Box3(), rotationSpeed: 0.05 };
            return mesh;
        }

        function spawnObject() {
            if (gameState !== 'playing') return;

            const lane = Math.floor(Math.random() * 3) - 1; // -1, 0, or 1
            const isCoin = Math.random() < 0.3; // 30% chance of coin

            let obj;
            // Try to get from pool
            const availableType = isCoin ? 'coin' : 'obstacle';
            const poolIndex = objectPool.findIndex(o => o.userData.type === availableType);

            if (poolIndex > -1) {
                obj = objectPool.splice(poolIndex, 1)[0];
            } else {
                obj = isCoin ? createCoin() : createObstacle();
            }

            obj.position.set(lane * LANE_WIDTH, isCoin ? 1 : obj.geometry.parameters.height / 2, -100);
            obj.visible = true;
            scene.add(obj);
            activeObjects.push(obj);
        }

        // --- Audio Context (Simple synthesized sounds) ---
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        function playSound(type) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();
            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);

            if (type === 'jump') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(300, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(500, audioCtx.currentTime + 0.1);
                gainNode.gain.setValueAtTime(0.3, audioCtx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.1);
            } else if (type === 'coin') {
                osc.type = 'square';
                osc.frequency.setValueAtTime(800, audioCtx.currentTime);
                osc.frequency.setValueAtTime(1200, audioCtx.currentTime + 0.05);
                gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.1);
            } else if (type === 'crash') {
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(150, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(40, audioCtx.currentTime + 0.3);
                gainNode.gain.setValueAtTime(0.5, audioCtx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.3);
            }
        }

        // --- Input Handling ---
        function moveLeft() {
            if (gameState === 'playing' && currentLane > -1) currentLane--;
        }

        function moveRight() {
            if (gameState === 'playing' && currentLane < 1) currentLane++;
        }

        function jump() {
            if (gameState === 'playing' && !isJumping) {
                isJumping = true;
                playerVelocityY = JUMP_FORCE;
                playSound('jump');
            }
        }

        // Keyboard
        window.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowLeft' || e.key === 'a') moveLeft();
            if (e.key === 'ArrowRight' || e.key === 'd') moveRight();
            if (e.key === 'ArrowUp' || e.key === 'w' || e.key === ' ') jump();
        });

        // Touch / Swipe
        let touchStartX = 0;
        let touchStartY = 0;

        window.addEventListener('touchstart', (e) => {
            touchStartX = e.changedTouches[0].screenX;
            touchStartY = e.changedTouches[0].screenY;
        }, {passive: false});

        window.addEventListener('touchend', (e) => {
            if (gameState !== 'playing') return;
            let touchEndX = e.changedTouches[0].screenX;
            let touchEndY = e.changedTouches[0].screenY;
            handleSwipe(touchStartX, touchStartY, touchEndX, touchEndY);
        }, {passive: false});

        // Prevent default touch moves to stop scrolling
        window.addEventListener('touchmove', (e) => { e.preventDefault(); }, {passive: false});

        function handleSwipe(startX, startY, endX, endY) {
            const diffX = endX - startX;
            const diffY = endY - startY;

            if (Math.abs(diffX) > Math.abs(diffY)) {
                // Horizontal swipe
                if (Math.abs(diffX) > 30) {
                    if (diffX > 0) moveRight();
                    else moveLeft();
                }
            } else {
                // Vertical swipe
                if (diffY < -30) {
                    jump(); // Swipe up
                }
            }
        }

        // --- UI Updates ---
        const scoreEl = document.getElementById('score-display');
        const coinEl = document.getElementById('coin-display');
        const startScreen = document.getElementById('start-screen');
        const gameOverScreen = document.getElementById('game-over-screen');
        const hud = document.getElementById('hud');
        const finalScoreEl = document.getElementById('final-score');

        document.getElementById('start-btn').addEventListener('click', startGame);
        document.getElementById('restart-btn').addEventListener('click', startGame);

        function updateUI() {
            scoreEl.innerText = `Score: ${Math.floor(score)}`;
            coinEl.innerText = `Coins: ${coins}`;
        }

        // --- Game Logic ---
        function resetGame() {
            score = 0;
            coins = 0;
            gameSpeed = SPEED_INITIAL;
            distanceTraveled = 0;
            currentLane = 0;
            player.position.set(0, playerBaseY, 0);
            playerVelocityY = 0;
            isJumping = false;

            // Clear objects
            for (let i = activeObjects.length - 1; i >= 0; i--) {
                const obj = activeObjects[i];
                scene.remove(obj);
                objectPool.push(obj);
            }
            activeObjects.length = 0;
            updateUI();
        }

        function startGame() {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            resetGame();
            gameState = 'playing';
            startScreen.classList.add('hidden');
            gameOverScreen.classList.add('hidden');
            hud.classList.remove('hidden');
        }

        function gameOver() {
            gameState = 'gameover';
            playSound('crash');
            hud.classList.add('hidden');
            gameOverScreen.classList.remove('hidden');
            finalScoreEl.innerText = `Final Score: ${Math.floor(score)}\nCoins: ${coins}`;
        }

        // --- Main Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const dt = clock.getDelta();

            if (gameState === 'playing') {
                // 1. Update Player position
                // Smooth lane switching
                const targetX = currentLane * LANE_WIDTH;
                player.position.x += (targetX - player.position.x) * 0.15;

                // Jumping physics
                if (isJumping) {
                    playerVelocityY += GRAVITY;
                    player.position.y += playerVelocityY;

                    if (player.position.y <= playerBaseY) {
                        player.position.y = playerBaseY;
                        isJumping = false;
                        playerVelocityY = 0;
                    }
                }

                // Update player bounding box
                playerBox.setFromObject(player);

                // 2. Progression
                gameSpeed += SPEED_INCREMENT * dt;
                distanceTraveled += gameSpeed;
                score += gameSpeed * 0.1;
                updateUI();

                // Move grid texture effect
                gridHelper.position.z = (distanceTraveled % 10) - 5;

                // 3. Spawning Objects
                spawnTimer -= dt;
                // Spawn faster as game gets faster
                const spawnInterval = Math.max(0.3, 1.5 - (gameSpeed * 0.5));
                if (spawnTimer <= 0) {
                    spawnObject();
                    spawnTimer = spawnInterval;
                }

                // 4. Update Objects & Check Collisions
                for (let i = activeObjects.length - 1; i >= 0; i--) {
                    const obj = activeObjects[i];

                    // Move towards camera
                    obj.position.z += gameSpeed;

                    // Animate coin
                    if (obj.userData.type === 'coin') {
                        obj.rotation.y += obj.userData.rotationSpeed;
                    }

                    // Collision Detection
                    // Only check if object is relatively close to player Z
                    if (Math.abs(obj.position.z - player.position.z) < 2) {
                        obj.userData.box.setFromObject(obj);

                        if (playerBox.intersectsBox(obj.userData.box)) {
                            if (obj.userData.type === 'obstacle') {
                                gameOver();
                                break; // Stop checking further collisions this frame
                            } else if (obj.userData.type === 'coin') {
                                playSound('coin');
                                coins++;
                                score += 10;
                                updateUI();
                                // Remove coin
                                scene.remove(obj);
                                objectPool.push(obj);
                                activeObjects.splice(i, 1);
                                continue;
                            }
                        }
                    }

                    // Remove if passed camera
                    if (obj.position.z > camera.position.z + 5) {
                        scene.remove(obj);
                        objectPool.push(obj);
                        activeObjects.splice(i, 1);
                    }
                }
            }

            renderer.render(scene, camera);
        }

        // --- Handle Resize ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start loop
        animate();

    </script>
</body>
</html>
