                if (playerHealth > 0) {
                    document.getElementById('start-screen').classList.remove('hidden');
                    document.getElementById('start-btn').innerText = "RESUME";
                    document.getElementById('hud').classList.add('hidden');
                }
            }
        }

        const PI_2 = Math.PI / 2;
        function onMouseMove(event) {
            if (document.pointerLockElement !== document.body) return;

            const movementX = event.movementX || event.mozMovementX || event.webkitMovementX || 0;
            const movementY = event.movementY || event.mozMovementY || event.webkitMovementY || 0;

            yawObject.rotation.y -= movementX * 0.002;
            pitchObject.rotation.x -= movementY * 0.002;
            pitchObject.rotation.x = Math.max(-PI_2, Math.min(PI_2, pitchObject.rotation.x));
        }

        function onKeyDown(event) {
            switch (event.code) {
                case 'KeyW': moveForward = true; break;
                case 'KeyA': moveLeft = true; break;
                case 'KeyS': moveBackward = true; break;
                case 'KeyD': moveRight = true; break;
                case 'Space': if (canJump === true) velocity.y += 15; canJump = false; break;
                case 'ShiftLeft': isSprinting = true; break;
                case 'KeyR': reload(); break;
            }
        }

        function onKeyUp(event) {
            switch (event.code) {
                case 'KeyW': moveForward = false; break;
                case 'KeyA': moveLeft = false; break;
                case 'KeyS': moveBackward = false; break;
                case 'KeyD': moveRight = false; break;
                case 'ShiftLeft': isSprinting = false; break;
            }
        }

        // --- SHOOTING & HITSCAN ---
        const raycaster = new THREE.Raycaster();

        function onMouseDown(event) {
            if (document.pointerLockElement !== document.body || event.button !== 0) return;
            if (isReloading || ammo <= 0) {
                if(ammo <= 0) reload();
                return;
            }

            const now = performance.now();
            if (now - lastFireTime < fireRate) return;
            lastFireTime = now;

            ammo--;
            updateHUD();
            shootEffects();

            // Hitscan Raycast
            raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);

            // Check enemies first
            let hitEnemy = false;
            const enemyIntersects = raycaster.intersectObjects(enemies.map(e => e.mesh));

            if (enemyIntersects.length > 0) {
                const hitMesh = enemyIntersects[0].object;
                const enemy = enemies.find(e => e.mesh === hitMesh);
                if (enemy) {
                    damageEnemy(enemy, 35); // 3 hits to kill
                    showHitmarker();
                    hitEnemy = true;
                }
            }

            // If didn't hit enemy, check environment for impacts (visual only for this scope)
            // if(!hitEnemy) {
            //    const envIntersects = raycaster.intersectObjects(objects);
            // }
        }

        function shootEffects() {
            playSound('shoot');

            // Visual Recoil
            pitchObject.rotation.x += 0.02; 
            weaponMesh.position.z = 0.05; // Kickback

            // Muzzle Flash
            muzzleFlash.material.opacity = 1;
            muzzleFlash.rotation.z = Math.random() * Math.PI;

            setTimeout(() => {
                muzzleFlash.material.opacity = 0;
            }, 50);
        }

        function reload() {
            if (isReloading || ammo === 30) return;
            isReloading = true;
            document.getElementById('ammo-val').innerText = "RLD";

            // Simple reload animation
            weaponPivot.rotation.x = -Math.PI / 4;

            setTimeout(() => {
                ammo = 30;
                isReloading = false;
                weaponPivot.rotation.x = 0;
                updateHUD();
            }, 1500);
        }

        function showHitmarker() {
            const hm = document.getElementById('hitmarker');
            hm.style.opacity = 1;
            playSound('hitmarker');
            setTimeout(() => { hm.style.opacity = 0; }, 100);
        }

        // --- ENEMY AI ---
        class Enemy {
            constructor(x, z) {
                this.hp = 100;
                this.speed = 10 + Math.random() * 5;

                const geo = new THREE.BoxGeometry(1.2, 2, 1.2);
                const mat = new THREE.MeshLambertMaterial({ color: 0xcc0000 });
                this.mesh = new THREE.Mesh(geo, mat);
                this.mesh.position.set(x, 1, z);
                this.mesh.castShadow = true;

                scene.add(this.mesh);
                this.box = new THREE.Box3();
                this.lastAttack = 0;
            }

            update(delta, playerPos) {
                if (this.hp <= 0) return;

                // Move towards player
                const dir = new THREE.Vector3().subVectors(playerPos, this.mesh.position);
                dir.y = 0; 
                const dist = dir.length();
                dir.normalize();

                // Look at player
                this.mesh.lookAt(playerPos.x, this.mesh.position.y, playerPos.z);

                if (dist > 1.5) {
                    // Basic movement (no complex pathfinding to avoid walls, just simple chase)
                    // In a real game, use NavMesh. Here they might get stuck, but it fits the simple scope.
                    this.mesh.position.add(dir.multiplyScalar(this.speed * delta));
                } else {
                    // Attack
                    const now = performance.now();
                    if (now - this.lastAttack > 1000) {
                        playerTakeDamage(15);
                        this.lastAttack = now;
                    }
                }

                // Keep above ground
                this.mesh.position.y = 1;
                this.box.setFromObject(this.mesh);
            }
        }

        function spawnEnemy() {
            if (enemies.length > 15) return; // Max enemies

            // Spawn away from player
            let x, z;
            do {
                x = (Math.random() - 0.5) * (mapSize - 20);
                z = (Math.random() - 0.5) * (mapSize - 20);
            } while (new THREE.Vector2(x - yawObject.position.x, z - yawObject.position.z).length() < 30);

            enemies.push(new Enemy(x, z));
        }

        function damageEnemy(enemy, amount) {
            enemy.hp -= amount;
            // Flash white
            enemy.mesh.material.color.setHex(0xffffff);
            setTimeout(() => {
                if(enemy.mesh) enemy.mesh.material.color.setHex(0xcc0000);
            }, 50);

            if (enemy.hp <= 0) {
                scene.remove(enemy.mesh);
                enemies = enemies.filter(e => e !== enemy);
                score += 100;
                updateHUD();
                playSound('kill');
            }
        }

        // --- PLAYER LOGIC ---
        function playerTakeDamage(amount) {
            playerHealth -= amount;
            updateHUD();

            const overlay = document.getElementById('damage-overlay');
            overlay.style.opacity = 1;
            playSound('hurt');

            setTimeout(() => {
                overlay.style.opacity = 0;
            }, 300);

            if (playerHealth <= 0) {
                gameOver();
            }
        }

        function updateHUD() {
            document.getElementById('hp-val').innerText = Math.max(0, playerHealth);
            const hb = document.getElementById('health-bar');
            hb.style.width = Math.max(0, playerHealth) + '%';
            if(playerHealth < 30) hb.style.background = '#ef4444';
            else hb.style.background = '#22c55e';

            document.getElementById('ammo-val').innerText = ammo;
            document.getElementById('score-val').innerText = score;
        }

        function checkCollision(newPos) {
            // Simple AABB vs AABB collision
            const playerBox = new THREE.Box3();
            // Player dimensions roughly 1x2x1
            playerBox.setFromCenterAndSize(newPos, new THREE.Vector3(1, 2, 1));

            for (let i = 0; i < boundingBoxes.length; i++) {
                if (playerBox.intersectsBox(boundingBoxes[i])) {
                    return true;
                }
            }
            // Check boundaries
            if(Math.abs(newPos.x) > mapSize/2 - 1 || Math.abs(newPos.z) > mapSize/2 - 1) return true;

            return false;
        }

        function gameOver() {
            document.exitPointerLock();
            document.getElementById('hud').classList.add('hidden');
            document.getElementById('game-over-screen').classList.remove('hidden');
            document.getElementById('final-score').innerText = score;
        }

        function resetGame() {
            playerHealth = 100;
            score = 0;
            ammo = 30;
            isReloading = false;

            yawObject.position.set(0, 2, 0);
            velocity.set(0,0,0);

            // Clear enemies
            enemies.forEach(e => scene.remove(e.mesh));
            enemies = [];

            updateHUD();
        }

        // --- AUDIO (Synthesized) ---
        function playSound(type) {
            if(!audioCtx) return;
            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();

            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);

            const now = audioCtx.currentTime;

            if (type === 'shoot') {
                osc.type = 'square';
                osc.frequency.setValueAtTime(150, now);
                osc.frequency.exponentialRampToValueAtTime(40, now + 0.1);
                gainNode.gain.setValueAtTime(0.3, now);
                gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
                osc.start(now);
                osc.stop(now + 0.1);
            } else if (type === 'hitmarker') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(800, now);
                gainNode.gain.setValueAtTime(0.5, now);
                gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
                osc.start(now);
                osc.stop(now + 0.05);
            } else if (type === 'hurt') {
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(100, now);
                gainNode.gain.setValueAtTime(0.8, now);
                gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
                osc.start(now);
                osc.stop(now + 0.3);
            } else if (type === 'kill') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(400, now);
                osc.frequency.setValueAtTime(600, now + 0.1);
                gainNode.gain.setValueAtTime(0.4, now);
                gainNode.gain.linearRampToValueAtTime(0, now + 0.2);
                osc.start(now);
                osc.stop(now + 0.2);
            }
        }

        // --- MAIN LOOP ---
        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        let spawnTimer = 0;

        function animate() {
            requestAnimationFrame(animate);

            const time = performance.now();
            const delta = (time - prevTime) / 1000;

            if (document.pointerLockElement === document.body && playerHealth > 0) {

                // Weapon animations return to normal
                weaponMesh.position.z += (0 - weaponMesh.position.z) * 10 * delta;

                // Movement Physics
                velocity.x -= velocity.x * 10.0 * delta;
                velocity.z -= velocity.z * 10.0 * delta;
                velocity.y -= 9.8 * 5.0 * delta; // Gravity

                direction.z = Number(moveForward) - Number(moveBackward);
                direction.x = Number(moveRight) - Number(moveLeft);
                direction.normalize(); // consistent speed in all directions

                let currentSpeed = PLAYER_SPEED;
                if (isSprinting && moveForward) currentSpeed *= SPRINT_MULT;

                if (moveForward || moveBackward) velocity.z -= direction.z * currentSpeed * delta;
                if (moveLeft || moveRight) velocity.x -= direction.x * currentSpeed * delta;

                // Collision Detection for Movement
                const potentialPos = yawObject.position.clone();

                // Test X axis
                potentialPos.x += (velocity.x * delta);
                if(checkCollision(potentialPos)) {
                    velocity.x = 0;
                    potentialPos.x = yawObject.position.x; // Revert
                }

                // Test Z axis
                potentialPos.z += (velocity.z * delta);
                if(checkCollision(potentialPos)) {
                    velocity.z = 0;
                    potentialPos.z = yawObject.position.z; // Revert
                }

                // Apply movement
                yawObject.translateX(velocity.x * delta);
                yawObject.translateZ(velocity.z * delta);
                yawObject.position.y += (velocity.y * delta); // Jump

                if (yawObject.position.y < 2) {
                    velocity.y = 0;
                    yawObject.position.y = 2;
                    canJump = true;
                }

                // Update Camera pos manually to follow yawObject (since camera is child of pitch, which is child of yaw)
                scene.position.x = -yawObject.position.x;
                scene.position.y = -yawObject.position.y;
                scene.position.z = -yawObject.position.z;

                // Actually, easier way: add yawObject to scene, remove translating scene.
                // Let's fix hierarchy.
            }

            // AI Update
            if (playerHealth > 0 && document.pointerLockElement === document.body) {
                enemies.forEach(enemy => enemy.update(delta, yawObject.position));

                spawnTimer += delta;
                if (spawnTimer > 2) { // Spawn every 2 seconds
                    spawnEnemy();
                    spawnTimer = 0;
                }
            }

            prevTime = time;
            renderer.render(scene, camera);
        }

        // Correct hierarchy for FPS controls
        init();
        scene.add(yawObject); // Add player controller to scene
        animate();

    </script>
</body>
</html>
