    <script>
        const display = document.getElementById('display');
        const historyDisplay = document.getElementById('history');
        let currentExpression = '';
        let isEvaluated = false;

        function updateDisplay() {
            // Replace internal symbols with visual ones for display
            let visualStr = currentExpression
                .replace(/pi/g, 'π')
                .replace(/\*/g, '×')
                .replace(/\//g, '÷');

            display.innerText = visualStr === '' ? '0' : visualStr;
            // Scroll to end
            display.scrollLeft = display.scrollWidth;
        }

        function appendVal(val) {
            if (isEvaluated) {
                currentExpression = '';
                isEvaluated = false;
            }
            currentExpression += val;
            updateDisplay();
        }

        function appendOp(op) {
            isEvaluated = false;
            currentExpression += op;
            updateDisplay();
        }

        function appendFunc(func) {
            if (isEvaluated) {
                currentExpression = '';
                isEvaluated = false;
            }
            currentExpression += func;
            updateDisplay();
        }

        function clearAll() {
            currentExpression = '';
            historyDisplay.innerText = '';
            isEvaluated = false;
            updateDisplay();
        }

        function deleteLast() {
            if (isEvaluated) return;
            // Handle deleting functions like 'sin(' as one block if possible, but character by character is simpler and robust
            if (currentExpression.endsWith(' AND ') || currentExpression.endsWith(' XOR ')) {
                currentExpression = currentExpression.slice(0, -5);
            } else if (currentExpression.endsWith(' OR ')) {
                currentExpression = currentExpression.slice(0, -4);
            } else if (currentExpression.endsWith('<<') || currentExpression.endsWith('>>')) {
                currentExpression = currentExpression.slice(0, -2);
            } else {
                currentExpression = currentExpression.slice(0, -1);
            }
            updateDisplay();
        }

        function calculate() {
            if (currentExpression === '') return;

            try {
                // Keep original for history
                let visualStr = currentExpression
                    .replace(/pi/g, 'π')
                    .replace(/\*/g, '×')
                    .replace(/\//g, '÷');
                historyDisplay.innerText = visualStr + ' =';

                // Prepare string for evaluation
                let evalStr = currentExpression
                    .replace(/sin\(/g, 'Math.sin(')
                    .replace(/cos\(/g, 'Math.cos(')
                    .replace(/tan\(/g, 'Math.tan(')
                    .replace(/log\(/g, 'Math.log10(')
                    .replace(/ln\(/g, 'Math.log(')
                    .replace(/sqrt\(/g, 'Math.sqrt(')
                    .replace(/pi/g, 'Math.PI')
                    .replace(/e/g, 'Math.E')
                    .replace(/\^/g, '**') // Power
                    .replace(/ AND /g, '&') // Bitwise AND
                    .replace(/ OR /g, '|')  // Bitwise OR
                    .replace(/ XOR /g, '^'); // Bitwise XOR

                // Evaluate using Function for slightly better security than raw eval, though still executes code.
                // Wrapped in Math.round to handle floating point precision issues (e.g., 0.1 + 0.2)
                let result = new Function('return ' + evalStr)();

                if (typeof result === 'number') {
                    // Fix precision for display, up to 10 decimal places
                    result = parseFloat(result.toFixed(10));
                }

                if (isNaN(result) || !isFinite(result)) {
                    throw new Error("Invalid calculation");
                }

                currentExpression = result.toString();
                isEvaluated = true;
                updateDisplay();

            } catch (error) {
                display.innerText = "Error";
                currentExpression = "";
                isEvaluated = true;
            }
        }

        // Keyboard Support
        document.addEventListener('keydown', (event) => {
            const key = event.key;
            if (/[0-9]/.test(key) || key === '.') {
                appendVal(key);
            } else if (['+', '-', '*', '/', '(', ')'].includes(key)) {
                appendOp(key);
            } else if (key === 'Enter' || key === '=') {
                event.preventDefault();
                calculate();
            } else if (key === 'Backspace') {
                deleteLast();
            } else if (key === 'Escape') {
                clearAll();
            } else if (key === '^') {
                appendOp('^');
            }
        });
    </script>
</body>
</html>
