    <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700&family=Crimson+Text:ital,wght@0,400;0,600;1,400&display=swap');

        :root {
            --bg-color: #0a0a0c;
            --panel-bg: #1a1a24;
            --accent-red: #8b0000;
            --accent-purple: #4b0082;
            --text-main: #d3d3d3;
            --text-muted: #808080;
        }

        body {
            font-family: 'Crimson Text', serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            overflow: hidden;
            user-select: none;
        }

        h1, h2, h3, .title-font {
            font-family: 'Cinzel', serif;
        }

        /* Screen Management */
        .screen { display: none; width: 100vw; height: 100vh; position: absolute; top: 0; left: 0; flex-direction: column; }
        .screen.active { display: flex; }

        /* Card Styling */
        .card {
            width: 140px; height: 200px;
            background: #2a2a35;
            border: 2px solid #444;
            border-radius: 8px;
            padding: 8px;
            display: flex;
            flex-direction: column;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
            position: relative;
            box-shadow: 0 4px 6px rgba(0,0,0,0.5);
            margin: 0 -10px; /* Overlap */
        }
        .card:hover {
            transform: translateY(-20px);
            z-index: 10;
            box-shadow: 0 10px 15px rgba(0,0,0,0.8);
            border-color: #888;
        }
        .card.disabled {
            opacity: 0.5;
            cursor: not-allowed;
            transform: none !important;
            border-color: #222 !important;
        }
        .card-cost {
            position: absolute; top: -10px; left: -10px;
            background: #111; border: 2px solid #555; border-radius: 50%;
            width: 30px; height: 30px;
            display: flex; justify-content: center; align-items: center;
            font-weight: bold; color: #00ffff;
            font-family: 'Cinzel', serif;
        }
        .card-type { font-size: 0.7rem; text-transform: uppercase; color: var(--text-muted); text-align: center; margin-bottom: 5px; border-bottom: 1px solid #444; padding-bottom: 2px;}
        .card-name { font-weight: bold; text-align: center; margin-bottom: 5px; font-size: 1.1rem; line-height: 1.1;}
        .card-desc { font-size: 0.9rem; text-align: center; flex-grow: 1; display: flex; align-items: center; justify-content: center;}

        .card.attack { border-top-color: var(--accent-red); background: linear-gradient(180deg, #3a1a1a 0%, #2a2a35 30%);}
        .card.skill { border-top-color: #2e8b57; background: linear-gradient(180deg, #1a3a2a 0%, #2a2a35 30%);}

        /* Health & Energy Bars */
        .bar-container { background: #222; border: 1px solid #555; border-radius: 4px; overflow: hidden; height: 20px; position: relative;}
        .bar-fill { height: 100%; transition: width 0.3s ease-in-out; }
        .hp-fill { background: var(--accent-red); }
        .block-fill { background: #4682b4; position: absolute; top:0; right:0; opacity: 0.8;}
        .bar-text { position: absolute; width: 100%; text-align: center; top: 0; font-size: 0.8rem; line-height: 20px; font-weight: bold; text-shadow: 1px 1px 0 #000;}

        /* Entity Areas */
        .entity { display: flex; flex-direction: column; align-items: center; width: 250px; }
        .sprite { width: 150px; height: 150px; background-size: contain; background-position: center; background-repeat: no-repeat; filter: drop-shadow(0 0 10px rgba(0,0,0,0.8)); margin-bottom: 10px; transition: transform 0.1s;}
        .sprite.hurt { transform: translateX(5px) rotate(2deg); filter: brightness(200%) hue-rotate(-50deg); }

        #player-sprite { background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><path fill="%23aaa" d="M40,90 L60,90 L55,40 L65,30 L50,10 L35,30 L45,40 Z"/><circle cx="50" cy="20" r="8" fill="%23ccc"/></svg>'); }

        .intent-icon { width: 30px; height: 30px; border-radius: 50%; background: #111; border: 1px solid #555; display: flex; justify-content: center; align-items: center; position: absolute; top: -15px; right: -15px; font-size: 1.2rem; z-index: 5;}

        /* Map */
        .map-node { width: 40px; height: 40px; border-radius: 50%; border: 2px solid #555; display: flex; justify-content: center; align-items: center; margin: 20px auto; cursor: pointer; background: #111; position: relative;}
        .map-node.active { border-color: var(--accent-red); box-shadow: 0 0 10px var(--accent-red); }
        .map-node.completed { border-color: #444; background: #222; cursor: default; }
        .map-line { width: 2px; height: 40px; background: #555; margin: 0 auto; }

        /* Effects */
        .shake { animation: shake 0.5s; }
        @keyframes shake { 0% { transform: translate(1px, 1px) rotate(0deg); } 10% { transform: translate(-1px, -2px) rotate(-1deg); } 20% { transform: translate(-3px, 0px) rotate(1deg); } 30% { transform: translate(3px, 2px) rotate(0deg); } 40% { transform: translate(1px, -1px) rotate(1deg); } 50% { transform: translate(-1px, 2px) rotate(-1deg); } 60% { transform: translate(-3px, 1px) rotate(0deg); } 70% { transform: translate(3px, 1px) rotate(-1deg); } 80% { transform: translate(-1px, -1px) rotate(1deg); } 90% { transform: translate(1px, 2px) rotate(0deg); } 100% { transform: translate(1px, -2px) rotate(-1deg); } }

        /* CRT overlay */
        .crt::before { content: " "; display: block; position: absolute; top: 0; left: 0; bottom: 0; right: 0; background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06)); z-index: 100; background-size: 100% 2px, 3px 100%; pointer-events: none; }

        .floating-text { position: absolute; color: white; font-weight: bold; font-size: 1.5rem; pointer-events: none; animation: floatUp 1s ease-out forwards; text-shadow: 2px 2px 0 #000; z-index: 50;}
        @keyframes floatUp { 0% { opacity: 1; transform: translateY(0); } 100% { opacity: 0; transform: translateY(-50px); } }

        /* Custom Scrollbar */
        ::-webkit-scrollbar { width: 8px; }
        ::-webkit-scrollbar-track { background: #111; }
        ::-webkit-scrollbar-thumb { background: #444; border-radius: 4px; }
    </style>
</head>
