    <!-- GAME OVER / VICTORY SCREEN -->
    <div id="end-screen" class="screen justify-center items-center bg-black">
        <h1 class="text-6xl mb-4" id="end-title">YOU DIED</h1>
        <p class="text-xl text-gray-400 mb-8" id="end-stats">Reached Floor: 1</p>
        <button onclick="initGame()" class="px-8 py-3 bg-red-900 hover:bg-red-700 text-white font-bold rounded title-font text-xl transition-colors">Play Again</button>
    </div>

    <!-- AUDIO (Synthesized for self-containment) -->
    <script>
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        function playSound(type) {
            if(audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.connect(gain);
            gain.connect(audioCtx.destination);

            const now = audioCtx.currentTime;

            if (type === 'hit') {
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(150, now);
                osc.frequency.exponentialRampToValueAtTime(40, now + 0.1);
                gain.gain.setValueAtTime(0.3, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
                osc.start(now); osc.stop(now + 0.1);
            } else if (type === 'block') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(400, now);
                osc.frequency.exponentialRampToValueAtTime(600, now + 0.2);
                gain.gain.setValueAtTime(0.2, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.2);
                osc.start(now); osc.stop(now + 0.2);
            } else if (type === 'card') {
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(600, now);
                osc.frequency.exponentialRampToValueAtTime(300, now + 0.05);
                gain.gain.setValueAtTime(0.1, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.05);
                osc.start(now); osc.stop(now + 0.05);
            }
        }
    </script>

    <!-- GAME LOGIC -->
    <script>
        // --- DATA ---
        const CARDS = {
            strike: { id: 'strike', name: 'Strike', cost: 1, type: 'attack', desc: 'Deal 6 damage.', play: (p, e) => dealDamage(e, 6) },
            defend: { id: 'defend', name: 'Defend', cost: 1, type: 'skill', desc: 'Gain 5 block.', play: (p, e) => gainBlock(p, 5) },
            heavy_strike: { id: 'heavy_strike', name: 'Heavy Strike', cost: 2, type: 'attack', desc: 'Deal 14 damage.', play: (p, e) => dealDamage(e, 14) },
            blood_letting: { id: 'blood_letting', name: 'Blood Rite', cost: 0, type: 'skill', desc: 'Lose 2 HP. Gain 2 Energy.', play: (p, e) => { takeDirectDamage(p, 2); p.energy += 2; } },
            vampirism: { id: 'vampirism', name: 'Drain', cost: 1, type: 'attack', desc: 'Deal 4 damage. Heal 4 HP.', play: (p, e) => { dealDamage(e, 4); heal(p, 4); } },
            shield_bash: { id: 'shield_bash', name: 'Shield Bash', cost: 1, type: 'attack', desc: 'Deal damage equal to your Block.', play: (p, e) => dealDamage(e, p.block) }
        };

        const ENEMIES = [
            { id: 'ghoul', name: 'Feral Ghoul', maxHp: 25, svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><path fill="#556b2f" d="M20,80 Q40,40 50,20 Q60,40 80,80 L60,90 L40,90 Z"/><circle cx="45" cy="35" r="3" fill="#f00"/><circle cx="55" cy="35" r="3" fill="#f00"/></svg>', getIntent: (e) => ({ type: 'attack', val: 6, icon: '⚔️' }) },
            { id: 'cultist', name: 'Dark Cultist', maxHp: 35, svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><path fill="#4b0082" d="M30,90 L50,10 L70,90 Z"/><circle cx="50" cy="40" r="8" fill="#000"/><path stroke="#fff" stroke-width="2" d="M45,40 L55,40 M50,35 L50,45"/></svg>', getIntent: (e) => { e.turn = (e.turn||0)+1; return e.turn % 2 === 0 ? { type: 'defend', val: 8, icon: '🛡️' } : { type: 'attack', val: 9, icon: '⚔️' }; } },
            { id: 'gargoyle', name: 'Stone Gargoyle', maxHp: 45, svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect x="30" y="30" width="40" height="60" fill="#555"/><path fill="#555" d="M10,50 Q30,20 50,30 Q70,20 90,50 L70,60 L30,60 Z"/></svg>', getIntent: (e) => ({ type: 'attack', val: Math.floor(Math.random() * 5) + 5, icon: '⚔️' }) },
            { id: 'boss', name: 'The Abyss Lord', maxHp: 100, isBoss: true, svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><path fill="#8b0000" d="M10,90 L50,0 L90,90 Z"/><circle cx="50" cy="30" r="10" fill="#000"/><path stroke="#f00" stroke-width="3" d="M45,30 L55,30 M50,25 L50,35"/></svg>', getIntent: (e) => { e.turn = (e.turn||0)+1; if(e.turn%3===0) return {type: 'defend', val: 15, icon: '🛡️'}; return { type: 'attack', val: 12, icon: '⚔️' }; } }
        ];

        // --- STATE ---
        let state = {
            screen: 'start',
            floor: 0,
            maxFloors: 5,
            player: { hp: 50, maxHp: 50, energy: 3, maxEnergy: 3, block: 0, deck: [], hand: [], drawPile: [], discardPile: [] },
            enemy: null,
            map: [],
            isPlayerTurn: true
        };

        // --- UTILS ---
        const $ = id => document.getElementById(id);
        function shuffle(array) {
            for (let i = array.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [array[i], array[j]] = [array[j], array[i]];
            }
            return array;
        }
        function createFloatingText(targetId, text, color) {
            const target = $(targetId);
            const rect = target.getBoundingClientRect();
            const el = document.createElement('div');
            el.className = 'floating-text';
            el.style.left = (rect.left + rect.width/2 - 10) + 'px';
            el.style.top = (rect.top + rect.height/2) + 'px';
            el.style.color = color;
            el.innerText = text;
            document.body.appendChild(el);
            setTimeout(() => el.remove(), 1000);
        }

        // --- CORE LOGIC ---
        function initGame() {
            state.player = { hp: 50, maxHp: 50, energy: 3, maxEnergy: 3, block: 0, 
                             deck: ['strike', 'strike', 'strike', 'strike', 'defend', 'defend', 'defend', 'defend'], 
                             hand: [], drawPile: [], discardPile: [] };
            state.floor = 0;
            generateMap();
            showScreen('map-screen');
            updateMapUI();
        }

        function generateMap() {
            state.map = [];
            for(let i=0; i<state.maxFloors - 1; i++) state.map.push({ type: 'combat', enemyIndex: Math.floor(Math.random() * (ENEMIES.length-1)) });
            state.map.push({ type: 'boss', enemyIndex: ENEMIES.length - 1 });
        }

        function updateMapUI() {
            $('map-hp').innerText = `${state.player.hp}/${state.player.maxHp}`;
            $('map-deck').innerText = state.player.deck.length;
            const container = $('map-container');
            container.innerHTML = '';

            for(let i = state.map.length - 1; i >= 0; i--) {
                const node = document.createElement('div');
                node.className = `map-node ${i < state.floor ? 'completed' : (i === state.floor ? 'active' : '')}`;
                node.innerHTML = state.map[i].type === 'boss' ? '😈' : '⚔️';
                if(i === state.floor) node.onclick = startCombat;
                container.appendChild(node);

                if(i > 0) {
                    const line = document.createElement('div');
                    line.className = 'map-line';
                    container.appendChild(line);
                }
            }
        }

        function startCombat() {
            const node = state.map[state.floor];
            const baseEnemy = ENEMIES[node.enemyIndex];
            state.enemy = { ...baseEnemy, hp: baseEnemy.maxHp, block: 0, turn: 0 };

            $('enemy-name').innerText = state.enemy.name;
            $('enemy-name').className = `title-font mb-2 ${state.enemy.isBoss ? 'text-red-600 text-2xl' : 'text-red-400'}`;
            $('enemy-sprite').style.backgroundImage = `url('data:image/svg+xml;utf8,${encodeURIComponent(state.enemy.svg)}')`;
            $('floor-display').innerText = state.floor + 1;

            state.player.drawPile = shuffle([...state.player.deck]);
            state.player.discardPile = [];
            state.player.hand = [];
            state.player.block = 0;

            showScreen('combat-screen');
            startTurn();
        }

        function startTurn() {
            state.isPlayerTurn = true;
            state.player.energy = state.player.maxEnergy;
            state.player.block = 0;
            $('end-turn-btn').disabled = false;
            $('end-turn-btn').classList.remove('opacity-50');

            // Draw 5 cards
            for(let i=0; i<5; i++) drawCard();

            // Set Enemy Intent
            state.enemy.intent = state.enemy.getIntent(state.enemy);

            updateCombatUI();
        }

        function drawCard() {
            if (state.player.drawPile.length === 0) {
                if (state.player.discardPile.length === 0) return;
                state.player.drawPile = shuffle([...state.player.discardPile]);
                state.player.discardPile = [];
            }
            state.player.hand.push(state.player.drawPile.pop());
        }

        function playCard(index) {
            if(!state.isPlayerTurn) return;
            const cardId = state.player.hand[index];
            const cardDef = CARDS[cardId];

            if (state.player.energy >= cardDef.cost) {
                state.player.energy -= cardDef.cost;
                state.player.hand.splice(index, 1);
                playSound('card');

                // Execute effect
                cardDef.play(state.player, state.enemy);
                state.player.discardPile.push(cardId);

                updateCombatUI();
                checkCombatEnd();
            }
        }

        function dealDamage(target, amount) {
            let damage = amount;
            if (target.block > 0) {
                if (target.block >= damage) {
                    target.block -= damage;
                    damage = 0;
                    playSound('block');
                } else {
                    damage -= target.block;
                    target.block = 0;
                }
            }
            if (damage > 0) {
                target.hp -= damage;
                playSound('hit');
                const spriteId = target === state.enemy ? 'enemy-sprite' : 'player-sprite';
                $(spriteId).classList.add('hurt');
                setTimeout(() => $(spriteId).classList.remove('hurt'), 200);
            }
            createFloatingText(target === state.enemy ? 'enemy-entity' : 'player-entity', `-${amount}`, '#ff4444');
        }

        function takeDirectDamage(target, amount) {
            target.hp -= amount;
            createFloatingText(target === state.enemy ? 'enemy-entity' : 'player-entity', `-${amount}`, '#ff4444');
        }

        function gainBlock(target, amount) {
            target.block += amount;
            playSound('block');
            createFloatingText(target === state.enemy ? 'enemy-entity' : 'player-entity', `+${amount}`, '#44aaff');
        }

        function heal(target, amount) {
            target.hp = Math.min(target.maxHp, target.hp + amount);
            createFloatingText(target === state.enemy ? 'enemy-entity' : 'player-entity', `+${amount}`, '#44ff44');
        }

        function endTurn() {
            if(!state.isPlayerTurn) return;
            state.isPlayerTurn = false;
            $('end-turn-btn').disabled = true;
            $('end-turn-btn').classList.add('opacity-50');

            // Discard hand
            state.player.discardPile.push(...state.player.hand);
            state.player.hand = [];
            updateCombatUI();

            // Enemy Turn
            setTimeout(() => {
                state.enemy.block = 0;
                const intent = state.enemy.intent;

                if (intent.type === 'attack') {
                    $('enemy-sprite').classList.add('shake');
                    setTimeout(() => $('enemy-sprite').classList.remove('shake'), 500);
                    dealDamage(state.player, intent.val);
                } else if (intent.type === 'defend') {
                    gainBlock(state.enemy, intent.val);
                }

                updateCombatUI();
                if(!checkCombatEnd()) {
                    setTimeout(startTurn, 800);
                }
            }, 500);
        }

        function checkCombatEnd() {
            if (state.enemy.hp <= 0) {
                state.floor++;
                if(state.floor >= state.maxFloors) {
                    endGame(true);
                } else {
                    setTimeout(showRewardScreen, 500);
                }
                return true;
            }
            if (state.player.hp <= 0) {
                setTimeout(() => endGame(false), 500);
                return true;
            }
            return false;
        }

        // --- UI UPDATES ---
        function updateCombatUI() {
            // Player stats
            $('player-hp-text').innerText = `${state.player.hp}/${state.player.maxHp}`;
            $('player-hp-bar').style.width = `${Math.max(0, (state.player.hp / state.player.maxHp) * 100)}%`;
            $('player-block-text').innerText = `Block: ${state.player.block}`;
            $('player-block-text').style.opacity = state.player.block > 0 ? 1 : 0;
            $('energy-display').innerText = `${state.player.energy}/${state.player.maxEnergy}`;

            // Enemy stats
            $('enemy-hp-text').innerText = `${state.enemy.hp}/${state.enemy.maxHp}`;
            $('enemy-hp-bar').style.width = `${Math.max(0, (state.enemy.hp / state.enemy.maxHp) * 100)}%`;
            $('enemy-block-text').innerText = `Block: ${state.enemy.block}`;
            $('enemy-block-text').style.opacity = state.enemy.block > 0 ? 1 : 0;

            // Intent
            $('enemy-intent-icon').innerText = state.enemy.intent.icon;
            $('enemy-intent-value').innerText = state.enemy.intent.val;

            // Deck counts
            $('draw-pile-count').innerText = state.player.drawPile.length;
            $('discard-pile-count').innerText = state.player.discardPile.length;

            // Render Hand
            const handContainer = $('hand-container');
            handContainer.innerHTML = '';
            state.player.hand.forEach((cardId, index) => {
                const c = CARDS[cardId];
                const canPlay = state.player.energy >= c.cost && state.isPlayerTurn;
                const cardEl = document.createElement('div');
                cardEl.className = `card ${c.type} ${canPlay ? '' : 'disabled'}`;
                // Arc positioning
                const offset = index - (state.player.hand.length - 1) / 2;
                cardEl.style.transform = canPlay ? `rotate(${offset * 5}deg) translateY(${Math.abs(offset) * 5}px)` : '';

                cardEl.innerHTML = `
                    <div class="card-cost">${c.cost}</div>
                    <div class="card-type">${c.type}</div>
                    <div class="card-name">${c.name}</div>
                    <div class="card-desc">${c.desc}</div>
                `;
                if(canPlay) cardEl.onclick = () => playCard(index);
                handContainer.appendChild(cardEl);
            });
        }

        // --- REWARD SCREEN ---
        function showRewardScreen() {
            showScreen('reward-screen');
            const container = $('reward-cards-container');
            container.innerHTML = '';

            // Pick 3 random cards (excluding basic strike/defend usually, but keeping simple here)
            const availableCards = Object.keys(CARDS).filter(k => k !== 'strike' && k !== 'defend');
            const choices = shuffle([...availableCards]).slice(0, 3);

            choices.forEach(cardId => {
                const c = CARDS[cardId];
                const cardEl = document.createElement('div');
                cardEl.className = `card ${c.type}`;
                cardEl.style.margin = '0 10px';
                cardEl.innerHTML = `
                    <div class="card-cost">${c.cost}</div>
                    <div class="card-type">${c.type}</div>
                    <div class="card-name">${c.name}</div>
                    <div class="card-desc">${c.desc}</div>
                `;
                cardEl.onclick = () => {
                    state.player.deck.push(cardId);
                    returnToMap();
                };
                container.appendChild(cardEl);
            });
        }

        function skipReward() { returnToMap(); }

        function returnToMap() {
            updateMapUI();
            showScreen('map-screen');
        }

        // --- GAME OVER ---
        function endGame(victory) {
            showScreen('end-screen');
            $('end-title').innerText = victory ? "ABYSS CONQUERED" : "YOU DIED";
            $('end-title').className = `text-6xl mb-4 ${victory ? 'text-yellow-500' : 'text-red-700'}`;
            $('end-stats').innerText = `Reached Floor: ${state.floor + 1}`;
        }

        // --- NAVIGATION ---
        function showScreen(id) {
            document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
            $(id).classList.add('active');
        }

        function startGame() {
            // Audio context requires user interaction to start
            if(audioCtx.state === 'suspended') audioCtx.resume();
            initGame();
        }

    </script>
</body>
</html>
