    <script type="module">
        import * as THREE from 'three';

        // --- Game State ---
        let gameState = 'start'; // start, playing, gameover
        let score = 0;
        let speedMultiplier = 1;
        let baseSpeed = 0.4;

        // --- DOM Elements ---
        const startScreen = document.getElementById('start-screen');
        const gameOverScreen = document.getElementById('game-over-screen');
        const scoreHud = document.getElementById('score-hud');
        const scoreVal = document.getElementById('score-val');
        const finalScoreVal = document.getElementById('final-score');
        const startBtn = document.getElementById('start-btn');
        const restartBtn = document.getElementById('restart-btn');
        const touchControls = document.getElementById('touch-controls');

        // --- Three.js Setup ---
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.02);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        scene.add(dirLight);

        // --- Environment ---
        const gridHelper = new THREE.GridHelper(100, 50, 0x00ffff, 0x002222);
        gridHelper.position.y = -0.5;
        scene.add(gridHelper);

        // --- Player ---
        const playerGeo = new THREE.BoxGeometry(1, 1, 1);
        const playerMat = new THREE.MeshPhongMaterial({ 
            color: 0x00ffff, 
            emissive: 0x008888,
            shininess: 100
        });
        const player = new THREE.Mesh(playerGeo, playerMat);
        player.position.set(0, 0, 5);
        scene.add(player);

        // --- Obstacles ---
        const obstacles = [];
        const obstacleGeo = new THREE.BoxGeometry(1, 1, 1);
        const obstacleMat = new THREE.MeshPhongMaterial({ 
            color: 0xff0044,
            emissive: 0x880022
        });

        const spawnZ = -50;
        const despawnZ = 15;
        const laneWidth = 1.5;
        const numLanes = 5;

        // --- Input Handling ---
        const keys = { left: false, right: false };

        window.addEventListener('keydown', (e) => {
            if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = true;
            if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = true;
        });

        window.addEventListener('keyup', (e) => {
            if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;
            if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;
        });

        // Touch controls
        const touchLeft = document.getElementById('touch-left');
        const touchRight = document.getElementById('touch-right');

        touchLeft.addEventListener('touchstart', (e) => { e.preventDefault(); keys.left = true; });
        touchLeft.addEventListener('touchend', (e) => { e.preventDefault(); keys.left = false; });
        touchRight.addEventListener('touchstart', (e) => { e.preventDefault(); keys.right = true; });
        touchRight.addEventListener('touchend', (e) => { e.preventDefault(); keys.right = false; });

        // --- Audio Context (Simple synthesized sounds) ---
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        function playSound(type) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.connect(gain);
            gain.connect(audioCtx.destination);

            if (type === 'score') {
                osc.type = 'sine';
                osc.frequency.setValueAtTime(400, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(800, audioCtx.currentTime + 0.1);
                gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.1);
            } else if (type === 'crash') {
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(100, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(10, audioCtx.currentTime + 0.5);
                gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.5);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.5);
            }
        }

        // --- Game Logic Functions ---
        function spawnObstacle() {
            const obs = new THREE.Mesh(obstacleGeo, obstacleMat);
            // Pick a random lane
            const laneIndex = Math.floor(Math.random() * numLanes) - Math.floor(numLanes/2);
            obs.position.set(laneIndex * laneWidth, 0, spawnZ);

            // Random scaling for variety
            obs.scale.x = 1 + Math.random();
            obs.scale.y = 1 + Math.random();

            scene.add(obs);
            obstacles.push(obs);
        }

        function startGame() {
            gameState = 'playing';
            score = 0;
            speedMultiplier = 1;
            player.position.x = 0;
            keys.left = false;
            keys.right = false;

            // Clear old obstacles
            obstacles.forEach(obs => scene.remove(obs));
            obstacles.length = 0;

            // UI
            startScreen.classList.add('hidden');
            gameOverScreen.classList.add('hidden');
            scoreHud.classList.remove('hidden');
            touchControls.classList.remove('hidden');
            scoreVal.innerText = score;

            if (audioCtx.state === 'suspended') audioCtx.resume();
        }

        function gameOver() {
            gameState = 'gameover';
            playSound('crash');

            scoreHud.classList.add('hidden');
            touchControls.classList.add('hidden');
            gameOverScreen.classList.remove('hidden');
            finalScoreVal.innerText = score;
        }

        // --- Event Listeners UI ---
        startBtn.addEventListener('click', startGame);
        restartBtn.addEventListener('click', startGame);

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // --- Main Game Loop ---
        let lastTime = 0;
        let spawnTimer = 0;

        function animate(time) {
            requestAnimationFrame(animate);

            const delta = (time - lastTime) / 1000;
            lastTime = time;

            if (gameState === 'playing') {
                // Player Movement
                const moveSpeed = 10 * delta;
                if (keys.left) player.position.x -= moveSpeed;
                if (keys.right) player.position.x += moveSpeed;

                // Clamp player position
                const maxPos = Math.floor(numLanes/2) * laneWidth;
                player.position.x = Math.max(-maxPos, Math.min(maxPos, player.position.x));

                // Tilt effect
                player.rotation.z = THREE.MathUtils.lerp(player.rotation.z, (keys.right ? -0.2 : (keys.left ? 0.2 : 0)), 0.1);

                // Grid animation
                gridHelper.position.z += (baseSpeed * speedMultiplier) * 60 * delta;
                if(gridHelper.position.z > 10) gridHelper.position.z = 0;

                // Spawning
                spawnTimer += delta;
                const spawnInterval = Math.max(0.2, 1.0 - (speedMultiplier * 0.1)); // Gets faster
                if (spawnTimer > spawnInterval) {
                    spawnObstacle();
                    // Maybe spawn a second one for difficulty
                    if(Math.random() > 0.7) spawnObstacle(); 
                    spawnTimer = 0;
                }

                // Obstacle Movement & Collision
                for (let i = obstacles.length - 1; i >= 0; i--) {
                    const obs = obstacles[i];
                    obs.position.z += (baseSpeed * speedMultiplier) * 60 * delta;

                    // Simple Box Collision
                    const distX = Math.abs(player.position.x - obs.position.x);
                    const distZ = Math.abs(player.position.z - obs.position.z);

                    // Box bounds roughly based on scale
                    const hitDistX = (1 + obs.scale.x)/2;
                    const hitDistZ = (1 + obs.scale.z)/2;

                    if (distX < hitDistX && distZ < hitDistZ) {
                        gameOver();
                        break;
                    }

                    // Despawn & Score
                    if (obs.position.z > despawnZ) {
                        scene.remove(obs);
                        obstacles.splice(i, 1);
                        score += 10;
                        scoreVal.innerText = score;
                        if(score % 100 === 0) playSound('score');

                        // Increase difficulty
                        speedMultiplier += 0.02;
                    }
                }
            } else if (gameState === 'start') {
                // Idle animation
                player.rotation.x += 0.01;
                player.rotation.y += 0.01;
            }

            renderer.render(scene, camera);
        }

        // Start loop
        requestAnimationFrame(animate);

    </script>
