        const COOLDOWN_MS = 400;
        let lastActionTime = { left: 0, right: 0, rotate: 0, drop: 0 };

        // Play sound synthesis (Web Audio API)
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        function playTone(freq, type, duration) {
            if(audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + duration);
        }

        async function setupCamera() {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    video: { width: 320, height: 240, facingMode: "user" } 
                });
                video.srcObject = stream;
                return new Promise((resolve) => {
                    video.onloadedmetadata = () => {
                        resolve();
                    };
                });
            } catch (err) {
                console.error("Camera access denied or unavailable.", err);
                alert("Camera access is required to play with gestures.");
            }
        }

        function triggerAction(action) {
            const now = performance.now();
            if (now - lastActionTime[action] < COOLDOWN_MS) return;

            lastActionTime[action] = now;

            // Visual feedback
            const el = document.getElementById(`zone-${action}`);
            if(el) {
                el.classList.add('zone-active');
                setTimeout(() => el.classList.remove('zone-active'), 200);
            }

            if (!gameActive) return;

            switch(action) {
                case 'left':
                    playerMove(-1);
                    playTone(300, 'square', 0.1);
                    break;
                case 'right':
                    playerMove(1);
                    playTone(300, 'square', 0.1);
                    break;
                case 'rotate':
                    playerRotate(1);
                    playTone(500, 'sine', 0.1);
                    break;
                case 'drop':
                    playerDrop();
                    score += 1; // bonus for hard drop
                    updateScore();
                    playTone(150, 'sawtooth', 0.15);
                    break;
            }
            if(gameActive) draw(); // Immediate feedback
        }

        function detectMotion() {
            if (video.videoWidth === 0) {
                motionLoopId = requestAnimationFrame(detectMotion);
                return;
            }

            // Draw current video frame to small canvas (flipped horizontally to match CSS mirror)
            mCtx.save();
            mCtx.scale(-1, 1);
            mCtx.drawImage(video, -motionCanvas.width, 0, motionCanvas.width, motionCanvas.height);
            mCtx.restore();

            const currentFrame = mCtx.getImageData(0, 0, motionCanvas.width, motionCanvas.height);
            const currentData = currentFrame.data;

            if (previousFrameData) {
                // Define zones on the small canvas (matching CSS percentages roughly)
                const w = motionCanvas.width;
                const h = motionCanvas.height;

                // [x, y, w, h]
                const zones = {
                    left: { rect: [0, Math.floor(h*0.2), Math.floor(w*0.3), Math.floor(h*0.6)], threshold: 25 },
                    right: { rect: [Math.floor(w*0.7), Math.floor(h*0.2), Math.floor(w*0.3), Math.floor(h*0.6)], threshold: 25 },
                    rotate: { rect: [Math.floor(w*0.3), 0, Math.floor(w*0.4), Math.floor(h*0.3)], threshold: 20 },
                    drop: { rect: [Math.floor(w*0.3), Math.floor(h*0.7), Math.floor(w*0.4), Math.floor(h*0.3)], threshold: 20 }
                };

                for (const [action, zone] of Object.entries(zones)) {
                    let motionAmount = 0;
                    const [zx, zy, zw, zh] = zone.rect;
                    let pixelCount = 0;

                    for (let y = zy; y < zy + zh; y+=2) { // Skip pixels for performance
                        for (let x = zx; x < zx + zw; x+=2) {
                            const i = (y * w + x) * 4;
                            // Calculate grayscale diff
                            const rDiff = Math.abs(currentData[i] - previousFrameData[i]);
                            const gDiff = Math.abs(currentData[i+1] - previousFrameData[i+1]);
                            const bDiff = Math.abs(currentData[i+2] - previousFrameData[i+2]);

                            // Average diff
                            if ((rDiff + gDiff + bDiff)/3 > 30) { 
                                motionAmount++;
                            }
                            pixelCount++;
                        }
                    }

                    const motionPercentage = (motionAmount / pixelCount) * 100;
                    if (motionPercentage > zone.threshold) {
                        triggerAction(action);
                    }
                }
            }

            // Store current frame for next comparison
            previousFrameData = new Uint8ClampedArray(currentData);
            motionLoopId = requestAnimationFrame(detectMotion);
        }

        // --- EVENT LISTENERS ---
        document.getElementById('start-btn').addEventListener('click', async () => {
            if(audioCtx.state === 'suspended') await audioCtx.resume();
            document.getElementById('start-btn').innerText = "CONNECTING CAMERA...";
            await setupCamera();
            document.getElementById('start-screen').classList.add('hidden');
            initGame();
            detectMotion();
        });

        document.getElementById('restart-btn').addEventListener('click', () => {
            document.getElementById('game-over-screen').classList.add('hidden');
            initGame();
        });

        // Keyboard fallback for testing/accessibility
        document.addEventListener('keydown', event => {
            if (!gameActive) return;
            switch(event.keyCode) {
                case 37: triggerAction('left'); break;
                case 39: triggerAction('right'); break;
                case 38: triggerAction('rotate'); break;
                case 40: triggerAction('drop'); break;
            }
        });

        // Initial draw
        draw();
    </script>
</body>
</html>
