        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
    </style>

    <!-- Import Maps -->
    <script type="importmap">
        {
            "imports": {
                "react": "https://esm.sh/react@18.2.0",
                "react-dom/client": "https://esm.sh/react-dom@18.2.0/client",
                "three": "https://esm.sh/three@0.160.0",
                "@react-three/fiber": "https://esm.sh/@react-three/fiber@8.15.12?external=react,react-dom,three",
                "@react-three/drei": "https://esm.sh/@react-three/drei@9.96.1?external=react,react-dom,three,@react-three/fiber",
                "@react-three/cannon": "https://esm.sh/@react-three/cannon@6.6.0?external=react,react-dom,three,@react-three/fiber"
            }
        }
    </script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
</head>
<body>
    <div id="root"></div>

    <script type="text/babel" data-type="module">
        import React, { useState, useEffect, useRef, useMemo } from 'react';
        import { createRoot } from 'react-dom/client';
        import * as THREE from 'three';
        import { Canvas, useFrame, useThree } from '@react-three/fiber';
        import { Sky, Environment, Text, Sparkles } from '@react-three/drei';
        import { Physics, useSphere, useBox } from '@react-three/cannon';

        // --- Keyboard Controls Hook ---
        function useKeyboard() {
            const [keys, setKeys] = useState({ forward: false, backward: false, left: false, right: false, jump: false });
            useEffect(() => {
                const handleKeyDown = (e) => {
                    switch(e.code) {
                        case 'KeyW': case 'ArrowUp': setKeys(k => ({ ...k, forward: true })); break;
                        case 'KeyS': case 'ArrowDown': setKeys(k => ({ ...k, backward: true })); break;
                        case 'KeyA': case 'ArrowLeft': setKeys(k => ({ ...k, left: true })); break;
                        case 'KeyD': case 'ArrowRight': setKeys(k => ({ ...k, right: true })); break;
                        case 'Space': setKeys(k => ({ ...k, jump: true })); break;
                    }
                };
                const handleKeyUp = (e) => {
                    switch(e.code) {
                        case 'KeyW': case 'ArrowUp': setKeys(k => ({ ...k, forward: false })); break;
                        case 'KeyS': case 'ArrowDown': setKeys(k => ({ ...k, backward: false })); break;
                        case 'KeyA': case 'ArrowLeft': setKeys(k => ({ ...k, left: false })); break;
                        case 'KeyD': case 'ArrowRight': setKeys(k => ({ ...k, right: false })); break;
                        case 'Space': setKeys(k => ({ ...k, jump: false })); break;
                    }
                };
                window.addEventListener('keydown', handleKeyDown);
                window.addEventListener('keyup', handleKeyUp);
                return () => {
                    window.removeEventListener('keydown', handleKeyDown);
                    window.removeEventListener('keyup', handleKeyUp);
                };
            }, []);
            return keys;
        }

        // --- Game Entities ---

        const Platform = ({ position, args, color, type = 'normal' }) => {
            const [ref] = useBox(() => ({ type: 'Static', position, args }));
            return (
                <mesh ref={ref} receiveShadow castShadow>
                    <boxGeometry args={args} />
                    <meshStandardMaterial color={color} roughness={0.7} metalness={0.1} />
                </mesh>
            );
        };

        const Goal = ({ position, onWin }) => {
            const args = [4, 0.5, 4];
            const [ref] = useBox(() => ({ 
                type: 'Static', 
                position, 
                args,
                isSensor: true,
                onCollide: (e) => {
                    if (e.body.name === 'player') {
                        onWin();
                    }
                }
            }));

            useFrame((state) => {
                if (ref.current) {
                    ref.current.rotation.y += 0.01;
                }
            });

            return (
                <group position={position}>
                    <mesh ref={ref} receiveShadow>
                        <cylinderGeometry args={[2, 2, 0.5, 32]} />
                        <meshStandardMaterial color="#00ff00" emissive="#00aa00" emissiveIntensity={0.5} />
                    </mesh>
                    <Sparkles count={50} scale={4} size={4} speed={0.4} color="#aaffaa" position={[0, 1, 0]}/>
                    <Text position={[0, 2, 0]} fontSize={1} color="white" outlineWidth={0.1} outlineColor="black">GOAL</Text>
                </group>
            );
        };

        const Player = ({ position, setGameState }) => {
            const { camera } = useThree();
            const [ref, api] = useSphere(() => ({ 
                mass: 1, 
                position, 
                args: [0.5],
                fixedRotation: true // Keep it rolling smoothly without spinning wildly
            }));

            const velocity = useRef([0, 0, 0]);
            const positionRef = useRef(position);
            const { forward, backward, left, right, jump } = useKeyboard();

            useEffect(() => {
                api.velocity.subscribe((v) => (velocity.current = v));
                api.position.subscribe((p) => (positionRef.current = p));
            }, [api.velocity, api.position]);

            useFrame(() => {
                if (!ref.current) return;

                const speed = 5;
                const direction = new THREE.Vector3();

                // Calculate movement direction relative to camera looking forward
                const frontVector = new THREE.Vector3(0, 0, (backward ? 1 : 0) - (forward ? 1 : 0));
                const sideVector = new THREE.Vector3((left ? 1 : 0) - (right ? 1 : 0), 0, 0);

                direction.subVectors(frontVector, sideVector).normalize().multiplyScalar(speed);

                // Apply horizontal velocity
                api.velocity.set(direction.x, velocity.current[1], direction.z);

                // Jump logic (simple ground check based on velocity Y)
                if (jump && Math.abs(velocity.current[1]) < 0.05) {
                    api.velocity.set(velocity.current[0], 7, velocity.current[2]);
                }

                // Camera follow
                const currentPos = new THREE.Vector3(...positionRef.current);
                const cameraOffset = new THREE.Vector3(0, 4, 8);
                const targetCameraPos = currentPos.clone().add(cameraOffset);

                camera.position.lerp(targetCameraPos, 0.1);
                camera.lookAt(currentPos);

                // Death check
                if (positionRef.current[1] < -10) {
                    setGameState('lost');
                }

                // Keep name for collision detection
                ref.current.name = 'player';
            });

            return (
                <mesh ref={ref} castShadow>
                    <sphereGeometry args={[0.5, 32, 32]} />
                    <meshStandardMaterial color="#ff4081" roughness={0.2} metalness={0.8} />
                </mesh>
            );
        };

        const Level = ({ setGameState }) => {
            // Level layout
            const platforms = [
                { pos: [0, -1, 0], args: [6, 1, 6], color: "#3b82f6" }, // Start
                { pos: [0, -1, -8], args: [4, 1, 4], color: "#6366f1" },
                { pos: [4, 0, -14], args: [3, 1, 3], color: "#8b5cf6" },
                { pos: [-4, 1, -20], args: [3, 1, 3], color: "#a855f7" },
                { pos: [0, 2, -28], args: [8, 1, 4], color: "#d946ef" }, // Bridge
                { pos: [0, 3, -38], args: [2, 1, 2], color: "#ec4899" }, // Small step
                { pos: [0, 4, -45], args: [4, 1, 4], color: "#f43f5e" },
            ];

            return (
                <>
                    {platforms.map((p, i) => (
                        <Platform key={i} position={p.pos} args={p.args} color={p.color} />
                    ))}
                    <Goal position={[0, 5, -55]} onWin={() => setGameState('won')} />
                </>
            );
        };

        // --- Main App Component ---
        const App = () => {
            const [gameState, setGameState] = useState('menu'); // menu, playing, won, lost

            const startGame = () => setGameState('playing');
            const returnToMenu = () => setGameState('menu');

            return (
                <div className="w-full h-full relative font-sans">
                    {/* UI Overlay */}
                    {gameState !== 'playing' && (
                        <div className="ui-layer bg-black/60 backdrop-blur-sm">
                            <div className="interactive bg-white p-8 rounded-xl shadow-2xl text-center max-w-md w-full mx-4">
                                {gameState === 'menu' && (
                                    <>
                                        <h1 className="text-4xl font-extrabold mb-4 text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-purple-600">
                                            NEON RUN
                                        </h1>
                                        <p className="mb-6 text-gray-600">Use WASD or Arrows to move.<br/>Space to jump.<br/>Reach the green goal!</p>
                                        <button onClick={startGame} className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-3 px-8 rounded-full transition transform hover:scale-105">
                                            PLAY GAME
                                        </button>
                                    </>
                                )}
                                {gameState === 'won' && (
                                    <>
                                        <h1 className="text-4xl font-extrabold mb-4 text-green-500">LEVEL COMPLETE!</h1>
                                        <p className="mb-6 text-gray-600">Great job navigating the platforms.</p>
                                        <button onClick={startGame} className="bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-8 rounded-full transition transform hover:scale-105 mb-2 w-full">
                                            PLAY AGAIN
                                        </button>
                                        <button onClick={returnToMenu} className="text-gray-500 hover:text-gray-700 underline text-sm mt-2">
                                            Main Menu
                                        </button>
                                    </>
                                )}
                                {gameState === 'lost' && (
                                    <>
                                        <h1 className="text-4xl font-extrabold mb-4 text-red-500">YOU FELL!</h1>
                                        <p className="mb-6 text-gray-600">Watch your step.</p>
                                        <button onClick={startGame} className="bg-red-500 hover:bg-red-600 text-white font-bold py-3 px-8 rounded-full transition transform hover:scale-105 mb-2 w-full">
                                            TRY AGAIN
                                        </button>
                                        <button onClick={returnToMenu} className="text-gray-500 hover:text-gray-700 underline text-sm mt-2">
                                            Main Menu
                                        </button>
                                    </>
                                )}
                            </div>
                        </div>
                    )}

                    {/* HUD */}
                    {gameState === 'playing' && (
                        <div className="absolute top-4 left-4 text-white font-bold text-xl drop-shadow-md z-0 pointer-events-none">
                            Controls: WASD + Space
                        </div>
                    )}

                    {/* 3D Canvas */}
                    <Canvas shadows camera={{ fov: 60 }}>
                        <Sky sunPosition={[100, 20, 100]} turbidity={0.1} rayleigh={0.5} />
                        <ambientLight intensity={0.4} />
                        <directionalLight 
                            castShadow 
                            position={[10, 20, 10]} 
                            intensity={1.5} 
                            shadow-mapSize={[1024, 1024]}
                            shadow-camera-left={-20}
                            shadow-camera-right={20}
                            shadow-camera-top={20}
                            shadow-camera-bottom={-20}
                        />

                        {gameState === 'playing' && (
                            <Physics gravity={[0, -20, 0]}>
                                <Player position={[0, 5, 0]} setGameState={setGameState} />
                                <Level setGameState={setGameState} />
                            </Physics>
                        )}

                        {/* decorative background floating elements */}
                        {gameState !== 'playing' && (
                           <group>
                               {[...Array(20)].map((_, i) => (
                                   <mesh key={i} position={[(Math.random() - 0.5) * 40, (Math.random() - 0.5) * 40, -10 - Math.random() * 20]}>
                                       <boxGeometry args={[Math.random() * 2, Math.random() * 2, Math.random() * 2]} />
                                       <meshStandardMaterial color={`hsl(${Math.random() * 360}, 50%, 50%)`} opacity={0.5} transparent />
                                   </mesh>
                               ))}
                           </group>
                        )}
                    </Canvas>
                </div>
            );
        };

        const root = createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
