        <div class="score-text">SCORE: <span id="scoreDisplay">0</span></div>
    </div>

    <div id="uiLayer">
        <!-- Start Screen -->
        <div id="startScreen" class="screen active">
            <h1 class="neon-text-title">NEON<br>RUNNER</h1>
            <p class="neon-text-subtitle">Desktop: Arrows / Space to Jump<br>Mobile: On-screen buttons</p>
            <button class="btn" onclick="startGame()">Start Game</button>
        </div>

        <!-- Game Over Screen -->
        <div id="gameOverScreen" class="screen">
            <h1 class="neon-text-title" style="color: #ff0044; text-shadow: 0 0 10px #ff0044, 0 0 20px #ff0044, 0 0 40px #ff0044;">SYSTEM FAILURE</h1>
            <p class="neon-text-subtitle" style="color: #fff;">Final Score: <span id="finalScore">0</span></p>
            <button class="btn" onclick="startGame()">Reboot</button>
        </div>
    </div>

    <!-- Mobile Controls -->
    <div id="mobileControls">
        <div class="control-zone">
            <div class="touch-btn" id="btnLeft">←</div>
            <div class="touch-btn" id="btnRight">→</div>
        </div>
        <div class="control-zone" style="justify-content: flex-end;">
            <div class="touch-btn" id="btnJump">↑</div>
        </div>
    </div>

<script>
    /** --- Audio System (Web Audio API) --- */
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    let actx;

    function initAudio() {
        if (!actx) actx = new AudioContext();
        if (actx.state === 'suspended') actx.resume();
    }

    function playSound(type) {
        if (!actx) return;
        const osc = actx.createOscillator();
        const gain = actx.createGain();
        osc.connect(gain);
        gain.connect(actx.destination);

        const now = actx.currentTime;
        if (type === 'jump') {
            osc.type = 'square';
            osc.frequency.setValueAtTime(150, now);
            osc.frequency.exponentialRampToValueAtTime(300, now + 0.1);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
            osc.start(now);
            osc.stop(now + 0.1);
        } else if (type === 'coin') {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.setValueAtTime(1200, now + 0.05);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
            osc.start(now);
            osc.stop(now + 0.1);
        } else if (type === 'die') {
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.exponentialRampToValueAtTime(50, now + 0.5);
            gain.gain.setValueAtTime(0.2, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
            osc.start(now);
            osc.stop(now + 0.5);
        }
    }

    /** --- Game Setup --- */
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d', { alpha: false }); // Optimize

    let width, height;
    function resize() {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    }
    window.addEventListener('resize', resize);
    resize();

    // Game State
    let state = 'start'; // start, playing, gameover
    let score = 0;
    let cameraX = 0;
    let frame = 0;

    // Entities
    let player;
    let platforms = [];
    let coins = [];
    let particles = [];
    let backgroundStars = [];

    // Input
    const keys = { left: false, right: false, up: false };

    window.addEventListener('keydown', e => {
        if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = true;
        if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = true;
        if (e.code === 'ArrowUp' || e.code === 'KeyW' || e.code === 'Space') keys.up = true;
    });

    window.addEventListener('keyup', e => {
        if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;
        if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;
        if (e.code === 'ArrowUp' || e.code === 'KeyW' || e.code === 'Space') keys.up = false;
    });

    // Touch controls
    const setupTouch = (id, key) => {
        const btn = document.getElementById(id);
        btn.addEventListener('touchstart', (e) => { e.preventDefault(); keys[key] = true; });
        btn.addEventListener('touchend', (e) => { e.preventDefault(); keys[key] = false; });
    };
    setupTouch('btnLeft', 'left');
    setupTouch('btnRight', 'right');
    setupTouch('btnJump', 'up');


    /** --- Classes --- */

    class Player {
        constructor() {
            this.width = 30;
            this.height = 30;
            this.x = 100;
            this.y = height / 2;
            this.vx = 0;
            this.vy = 0;
            this.speed = 7;
            this.jumpPower = -14;
            this.gravity = 0.6;
            this.grounded = false;
            this.color = '#00ffff';
            this.trail = [];
        }

        update() {
            // Horizontal movement
            if (keys.left) this.vx -= 1;
            if (keys.right) this.vx += 1;
            this.vx *= 0.8; // Friction

            // Vertical movement
            this.vy += this.gravity;
            if (keys.up && this.grounded) {
                this.vy = this.jumpPower;
                this.grounded = false;
                playSound('jump');
                createParticles(this.x + this.width/2, this.y + this.height, 10, this.color);
            }

            // Apply limits
            if (this.vx > this.speed) this.vx = this.speed;
            if (this.vx < -this.speed) this.vx = -this.speed;
            if (this.vy > 20) this.vy = 20;

            // Store previous position for collision response
            const prevX = this.x;
            const prevY = this.y;

            // Move X
            this.x += this.vx;
            this.checkCollisions(prevX, prevY, 'x');

            // Move Y
            this.y += this.vy;
            this.grounded = false;
            this.checkCollisions(prevX, prevY, 'y');

            // Trail
            if (frame % 2 === 0) {
                this.trail.push({x: this.x, y: this.y, alpha: 1});
                if (this.trail.length > 10) this.trail.shift();
            }
            for (let t of this.trail) t.alpha -= 0.1;

            // Death condition
            if (this.y > height + 100) {
                gameOver();
            }
        }

        checkCollisions(px, py, axis) {
            for (let p of platforms) {
                if (this.x < p.x + p.w &&
                    this.x + this.width > p.x &&
                    this.y < p.y + p.h &&
                    this.y + this.height > p.y) {

                    if (axis === 'x') {
                        if (this.vx > 0) this.x = p.x - this.width;
                        else if (this.vx < 0) this.x = p.x + p.w;
                        this.vx = 0;
                    } else if (axis === 'y') {
                        if (this.vy > 0) {
                            this.y = p.y - this.height;
                            this.grounded = true;
                        } else if (this.vy < 0) {
                            this.y = p.y + p.h;
                        }
                        this.vy = 0;
                    }
                }
            }
        }

        draw(ctx) {
            // Draw trail
            ctx.save();
            ctx.shadowBlur = 10;
            ctx.shadowColor = this.color;
            for (let i = 0; i < this.trail.length; i++) {
                const t = this.trail[i];
                if (t.alpha <= 0) continue;
                ctx.fillStyle = `rgba(0, 255, 255, ${t.alpha * 0.3})`;
                ctx.fillRect(t.x, t.y, this.width, this.height);
            }

            // Draw player
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 20;
            ctx.shadowColor = this.color;
            ctx.fillRect(this.x, this.y, this.width, this.height);

            // Inner core
            ctx.fillStyle = this.color;
            ctx.shadowBlur = 0;
            ctx.fillRect(this.x + 5, this.y + 5, this.width - 10, this.height - 10);
            ctx.restore();
        }
    }

    class Platform {
        constructor(x, y, w, h) {
            this.x = x;
            this.y = y;
            this.w = w;
            this.h = h;
            this.color = '#ff00ff';
        }

        draw(ctx) {
            ctx.save();
            ctx.fillStyle = '#050510'; // Dark core
            ctx.strokeStyle = this.color;
            ctx.lineWidth = 3;
            ctx.shadowBlur = 15;
            ctx.shadowColor = this.color;

            ctx.beginPath();
            ctx.rect(this.x, this.y, this.w, this.h);
            ctx.fill();
            ctx.stroke();

            // Grid lines on platform
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'rgba(255, 0, 255, 0.2)';
            ctx.lineWidth = 1;
            for(let i=10; i<this.w; i+=20) {
                ctx.beginPath(); ctx.moveTo(this.x+i, this.y); ctx.lineTo(this.x+i, this.y+this.h); ctx.stroke();
            }
            ctx.restore();
        }
    }

    class Coin {
        constructor(x, y) {
            this.x = x;
            this.y = y;
            this.r = 10;
            this.collected = false;
            this.baseY = y;
            this.offset = Math.random() * Math.PI * 2;
        }

        update() {
            this.y = this.baseY + Math.sin((frame * 0.05) + this.offset) * 10;

            // Collision with player
            if (!this.collected) {
                const dx = (this.x) - (player.x + player.width/2);
                const dy = (this.y) - (player.y + player.height/2);
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < this.r + player.width/2) {
                    this.collected = true;
                    score += 100;
                    document.getElementById('scoreDisplay').innerText = score;
                    playSound('coin');
                    createParticles(this.x, this.y, 20, '#ffff00');
                }
            }
        }

        draw(ctx) {
            if (this.collected) return;
            ctx.save();
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 20;
            ctx.shadowColor = '#ffff00';

            ctx.beginPath();
            ctx.arc(this.x, this.y, this.r * (0.8 + Math.sin(frame*0.1)*0.2), 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#ffff00';
            ctx.shadowBlur = 0;
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.r * 0.5, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }
    }

    class Particle {
        constructor(x, y, color) {
            this.x = x;
            this.y = y;
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 5;
            this.vx = Math.cos(angle) * speed;
            this.vy = Math.sin(angle) * speed;
            this.life = 1;
            this.decay = Math.random() * 0.05 + 0.02;
            this.color = color;
            this.size = Math.random() * 4 + 2;
        }
        update() {
            this.x += this.vx;
            this.y += this.vy;
            this.life -= this.decay;
        }
        draw(ctx) {
            if(this.life <= 0) return;
            ctx.save();
            ctx.globalAlpha = this.life;
            ctx.fillStyle = this.color;
            ctx.shadowBlur = 10;
            ctx.shadowColor = this.color;
            ctx.fillRect(this.x, this.y, this.size, this.size);
            ctx.restore();
        }
    }

    function createParticles(x, y, count, color) {
        for(let i=0; i<count; i++) particles.push(new Particle(x, y, color));
    }

    function initBackground() {
        backgroundStars = [];
        for(let i=0; i<100; i++) {
            backgroundStars.push({
                x: Math.random() * width * 3, // Spread out widely
                y: Math.random() * height,
                size: Math.random() * 2,
                speed: Math.random() * 0.5 + 0.1
            });
        }
    }

    /** --- Game Logic --- */

    let levelGenX = 0;

    function generateLevel() {
        // Ensure we always have platforms ahead of the camera
        while (levelGenX < cameraX + width * 2) {
            const w = Math.random() * 200 + 100;

            // Determine Y based on previous platform to make it jumpable
            let y;
            if (platforms.length === 0) {
                y = height - 150;
            } else {
                const prev = platforms[platforms.length - 1];
                // Y offset between -100 and +100 from prev
                y = prev.y + (Math.random() * 200 - 100);
                // Clamp
                if (y < 100) y = 100;
                if (y > height - 100) y = height - 100;
            }

            // X gap
            const gap = Math.random() * 150 + 50;
            levelGenX += gap;

            platforms.push(new Platform(levelGenX, y, w, 30));

            // Add coins occasionally
            if (Math.random() > 0.5) {
                const numCoins = Math.floor(Math.random() * 3) + 1;
                for(let i=0; i<numCoins; i++) {
                    coins.push(new Coin(levelGenX + (w/2) + (i*30 - 30), y - 60));
                }
            }

            levelGenX += w;
        }

        // Cleanup old entities to save memory
        platforms = platforms.filter(p => p.x + p.w > cameraX - 500);
        coins = coins.filter(c => c.x > cameraX - 500 && !c.collected);
        particles = particles.filter(p => p.life > 0);
    }

    function drawBackground() {
        // Deep space background with subtle gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#02010a');
        bgGrad.addColorStop(1, '#100520');
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);

        // Parallax Stars
        ctx.fillStyle = '#ffffff';
        for(let star of backgroundStars) {
            // Wrap stars
            let sx = (star.x - cameraX * star.speed) % width;
            if (sx < 0) sx += width;

            ctx.globalAlpha = Math.sin((frame * 0.05) + star.x) * 0.5 + 0.5;
            ctx.fillRect(sx, star.y, star.size, star.size);
        }
        ctx.globalAlpha = 1;

        // Synthwave Grid Base (Parallax)
        ctx.save();
        ctx.strokeStyle = 'rgba(255, 0, 255, 0.15)';
        ctx.lineWidth = 2;
        ctx.shadowBlur = 5;
        ctx.shadowColor = '#ff00ff';

        const gridY = height - 50;
        ctx.beginPath();
        ctx.moveTo(0, gridY);
        ctx.lineTo(width, gridY);
        ctx.stroke();

        const gridOffsetX = -(cameraX * 0.5) % 50;
        for(let i = -50; i < width + 50; i += 50) {
            ctx.beginPath();

            // Perspective transform manually
            const topX = i + gridOffsetX;
            const bottomX = (i + gridOffsetX - width/2) * 3 + width/2;

            ctx.moveTo(topX, gridY);
            ctx.lineTo(bottomX, height);
            ctx.stroke();
        }
        ctx.restore();
    }

    function startGame() {
        initAudio();
        document.getElementById('startScreen').classList.remove('active');
        document.getElementById('gameOverScreen').classList.remove('active');
        document.getElementById('hud').style.display = 'block';

        player = new Player();
        platforms = [];
        coins = [];
        particles = [];
        score = 0;
        cameraX = 0;
        levelGenX = 50; // Start first platform near player
        frame = 0;

        // Initial safe platform
        platforms.push(new Platform(50, height/2 + 100, 400, 30));
        levelGenX = 450;

        initBackground();

        document.getElementById('scoreDisplay').innerText = score;
        state = 'playing';

        // Reset keys so user doesn't carry over menu presses
        keys.left = keys.right = keys.up = false;
    }

    function gameOver() {
        state = 'gameover';
        playSound('die');
        createParticles(player.x, player.y, 50, '#ff0044');
        document.getElementById('hud').style.display = 'none';
        document.getElementById('gameOverScreen').classList.add('active');
        document.getElementById('finalScore').innerText = score;
    }

    /** --- Main Loop --- */
    function loop() {
        requestAnimationFrame(loop);

        frame++;

        if (state === 'start' || state === 'gameover') {
            // Draw nice background even in menus
            drawBackground();

            // Draw particles if game over
            if (state === 'gameover') {
                ctx.save();
                ctx.translate(-cameraX, 0);
                particles.forEach(p => { p.update(); p.draw(ctx); });
                ctx.restore();
            }
            return;
        }

        // Logic
        player.update();

        // Camera logic - focus on player, but don't go backwards
        const targetCamX = player.x - width / 3;
        if (targetCamX > cameraX) {
            cameraX += (targetCamX - cameraX) * 0.1; // Smooth follow
        }

        // Score based on distance
        if (player.x > score) {
            score = Math.floor(player.x);
            if(frame % 10 === 0) document.getElementById('scoreDisplay').innerText = score;
        }

        generateLevel();
        coins.forEach(c => c.update());
        particles.forEach(p => p.update());

        // Rendering
        drawBackground();

        ctx.save();
        ctx.translate(-cameraX, 0);

        platforms.forEach(p => p.draw(ctx));
        coins.forEach(c => c.draw(ctx));
        player.draw(ctx);
        particles.forEach(p => p.draw(ctx));

        ctx.restore();
    }

    // Start loop
    drawBackground(); // Initial draw
    requestAnimationFrame(loop);

</script>
