                    const n_out = createOrGetNode(cx + laneOffset, cz - config.streetWidth/2);
                    const s_in = createOrGetNode(cx + laneOffset, cz + config.streetWidth/2);
                    const s_out = createOrGetNode(cx - laneOffset, cz + config.streetWidth/2);
                    const e_in = createOrGetNode(cx + config.streetWidth/2, cz - laneOffset);
                    const e_out = createOrGetNode(cx + config.streetWidth/2, cz + laneOffset);
                    const w_in = createOrGetNode(cx - config.streetWidth/2, cz + laneOffset);
                    const w_out = createOrGetNode(cx - config.streetWidth/2, cz - laneOffset);

                    // Add central intersection node for visual debug (optional, not strictly needed for logic if linked directly)

                    // Link internal turns (handling boundaries)
                    const isTop = j === 0;
                    const isBottom = j === numIntersections - 1;
                    const isLeft = i === 0;
                    const isRight = i === numIntersections - 1;

                    // Logic: From Entry, you can go Straight, Right, Left to Exits
                    if (!isTop) { // Has North entry
                        if(!isBottom) n_in.addNext(s_out); // Straight
                        if(!isLeft) n_in.addNext(w_out); // Right
                        if(!isRight) n_in.addNext(e_out); // Left
                    }
                    if (!isBottom) { // Has South entry
                        if(!isTop) s_in.addNext(n_out);
                        if(!isRight) s_in.addNext(e_out);
                        if(!isLeft) s_in.addNext(w_out);
                    }
                    if (!isLeft) { // Has West entry
                        if(!isRight) w_in.addNext(e_out);
                        if(!isBottom) w_in.addNext(s_out);
                        if(!isTop) w_in.addNext(n_out);
                    }
                    if (!isRight) { // Has East entry
                        if(!isLeft) e_in.addNext(w_out);
                        if(!isTop) e_in.addNext(n_out);
                        if(!isBottom) e_in.addNext(s_out);
                    }

                    // Link to adjacent intersections
                    if (!isBottom) {
                        const next_cx = cx;
                        const next_cz = (j + 1 - config.gridSize / 2) * spacing;
                        const next_n_in = createOrGetNode(next_cx - laneOffset, next_cz - config.streetWidth/2);
                        s_out.addNext(next_n_in);
                    }
                    if (!isTop) {
                        const prev_cx = cx;
                        const prev_cz = (j - 1 - config.gridSize / 2) * spacing;
                        const prev_s_in = createOrGetNode(prev_cx + laneOffset, prev_cz + config.streetWidth/2);
                        n_out.addNext(prev_s_in);
                    }
                    if (!isRight) {
                        const next_cx = (i + 1 - config.gridSize / 2) * spacing;
                        const next_cz = cz;
                        const next_w_in = createOrGetNode(next_cx - config.streetWidth/2, next_cz + laneOffset);
                        e_out.addNext(next_w_in);
                    }
                    if (!isLeft) {
                        const prev_cx = (i - 1 - config.gridSize / 2) * spacing;
                        const prev_cz = cz;
                        const prev_e_in = createOrGetNode(prev_cx + config.streetWidth/2, prev_cz - laneOffset);
                        w_out.addNext(prev_e_in);
                    }
                }
            }

            // Clean up nodes with no exits (dead ends at edges)
            for(let i = waypoints.length - 1; i >= 0; i--) {
                if(waypoints[i].next.length === 0) {
                   // Create a U-turn for dead ends to keep traffic flowing
                   let wp = waypoints[i];
                   // Find nearest node that is not self
                   let nearest = null;
                   let minDist = Infinity;
                   waypoints.forEach(w => {
                       if(w !== wp) {
                           let d = Math.hypot(w.x-wp.x, w.z-wp.z);
                           if(d < minDist && w.next.length > 0) {
                               minDist = d; nearest = w;
                           }
                       }
                   });
                   if(nearest) wp.addNext(nearest);
                }
            }
        }

        generateTrafficGraph();

        // Car Class
        const carGeo = new THREE.BoxGeometry(2, 1.5, 4);
        carGeo.translate(0, 0.75, 0); // Origin at bottom

        class Car {
            constructor() {
                this.mesh = new THREE.Mesh(carGeo, new THREE.MeshStandardMaterial({ 
                    color: new THREE.Color().setHSL(Math.random(), 0.8, 0.5) 
                }));
                this.mesh.castShadow = true;
                scene.add(this.mesh);

                this.reset();
            }

            reset() {
                this.currentNode = waypoints[Math.floor(Math.random() * waypoints.length)];
                this.targetNode = this.currentNode.next[Math.floor(Math.random() * this.currentNode.next.length)] || this.currentNode;
                this.mesh.position.set(this.currentNode.x, 0, this.currentNode.z);
                this.speed = config.carSpeedMin + Math.random() * (config.carSpeedMax - config.carSpeedMin);
            }

            update(dt) {
                if(!this.targetNode) return;

                const dx = this.targetNode.x - this.mesh.position.x;
                const dz = this.targetNode.z - this.mesh.position.z;
                const dist = Math.hypot(dx, dz);

                if (dist < 0.5) {
                    this.currentNode = this.targetNode;
                    if(this.currentNode.next.length > 0) {
                        this.targetNode = this.currentNode.next[Math.floor(Math.random() * this.currentNode.next.length)];
                    } else {
                        this.reset(); // Should rarely happen with U-turns added
                    }
                } else {
                    const moveX = (dx / dist) * this.speed * dt;
                    const moveZ = (dz / dist) * this.speed * dt;
                    this.mesh.position.x += moveX;
                    this.mesh.position.z += moveZ;
                    this.mesh.rotation.y = Math.atan2(dx, dz);
                }
            }
        }

        // Initialize Cars
        for(let i=0; i<config.numCars; i++) {
            cars.push(new Car());
        }

        // Player setup
        const playerRadius = 0.5;
        const playerGeo = new THREE.CylinderGeometry(playerRadius, playerRadius, 2, 16);
        playerGeo.translate(0, 1, 0);
        const playerMat = new THREE.MeshStandardMaterial({ color: 0xff0000 });
        const player = new THREE.Mesh(playerGeo, playerMat);
        player.castShadow = true;
        scene.add(player);

        // Camera rig setup for 360 3rd person
        const cameraRig = new THREE.Group();
        scene.add(cameraRig);
        cameraRig.add(camera);
        camera.position.set(0, 8, 12);
        camera.lookAt(0, 1, 0);

        // Inputs
        const keys = { w: false, a: false, s: false, d: false };
        let isDragging = false;
        let prevMouse = { x: 0, y: 0 };
        let camAzimuth = 0;
        let camElevation = Math.PI / 4;

        let joystickVector = { x: 0, y: 0 };
        let isTouchControls = false;

        window.addEventListener('keydown', (e) => {
            if(keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = true;
        });
        window.addEventListener('keyup', (e) => {
            if(keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = false;
        });

        // Mouse look
        container.addEventListener('mousedown', (e) => {
            if(gameState !== 'PLAYING') return;
            isDragging = true;
            prevMouse.x = e.clientX;
            prevMouse.y = e.clientY;
        });
        window.addEventListener('mouseup', () => isDragging = false);
        window.addEventListener('mousemove', (e) => {
            if(isDragging && gameState === 'PLAYING') {
                const deltaX = e.clientX - prevMouse.x;
                const deltaY = e.clientY - prevMouse.y;
                camAzimuth -= deltaX * 0.01;
                camElevation -= deltaY * 0.01;
                camElevation = Math.max(0.1, Math.min(Math.PI / 2.5, camElevation)); // Clamp elevation
                prevMouse.x = e.clientX;
                prevMouse.y = e.clientY;
            }
        });

        // Mobile Touch Look & Joystick
        const joystickZone = document.getElementById('joystick-zone');
        const joystickKnob = document.getElementById('joystick-knob');

        // Detect touch to show joystick
        window.addEventListener('touchstart', () => {
            if(!isTouchControls) {
                isTouchControls = true;
                if(gameState === 'PLAYING') {
                    joystickZone.style.display = 'block';
                    document.getElementById('controls-hint').style.display = 'none';
                }
            }
        }, {once: true});

        // Touch Look (right side of screen)
        container.addEventListener('touchstart', (e) => {
            if(gameState !== 'PLAYING') return;
            for(let i=0; i<e.changedTouches.length; i++) {
                let touch = e.changedTouches[i];
                if(touch.clientX > window.innerWidth / 2) { // Right side for look
                    prevMouse.x = touch.clientX;
                    prevMouse.y = touch.clientY;
                }
            }
        }, {passive: false});

        container.addEventListener('touchmove', (e) => {
            if(gameState !== 'PLAYING') return;
            for(let i=0; i<e.changedTouches.length; i++) {
                let touch = e.changedTouches[i];
                if(touch.clientX > window.innerWidth / 2) {
                    e.preventDefault();
                    const deltaX = touch.clientX - prevMouse.x;
                    const deltaY = touch.clientY - prevMouse.y;
                    camAzimuth -= deltaX * 0.01;
                    camElevation -= deltaY * 0.01;
                    camElevation = Math.max(0.1, Math.min(Math.PI / 2.5, camElevation));
                    prevMouse.x = touch.clientX;
                    prevMouse.y = touch.clientY;
                }
            }
        }, {passive: false});

        // Joystick Logic
        let joyTouchId = null;
        joystickZone.addEventListener('touchstart', (e) => {
            e.preventDefault();
            joyTouchId = e.changedTouches[0].identifier;
            updateJoystick(e.changedTouches[0]);
        }, {passive: false});

        joystickZone.addEventListener('touchmove', (e) => {
            e.preventDefault();
            for(let i=0; i<e.changedTouches.length; i++) {
                if(e.changedTouches[i].identifier === joyTouchId) {
                    updateJoystick(e.changedTouches[i]);
                }
            }
        }, {passive: false});

        const endJoystick = (e) => {
             for(let i=0; i<e.changedTouches.length; i++) {
                if(e.changedTouches[i].identifier === joyTouchId) {
                    joyTouchId = null;
                    joystickKnob.style.transform = `translate(0px, 0px)`;
                    joystickVector = {x: 0, y: 0};
                }
            }
        };
        joystickZone.addEventListener('touchend', endJoystick);
        joystickZone.addEventListener('touchcancel', endJoystick);

        function updateJoystick(touch) {
            const rect = joystickZone.getBoundingClientRect();
            const centerX = rect.left + rect.width / 2;
            const centerY = rect.top + rect.height / 2;

            let dx = touch.clientX - centerX;
            let dy = touch.clientY - centerY;

            const dist = Math.hypot(dx, dy);
            const maxDist = rect.width / 2 - 25; // 25 is knob radius

            if(dist > maxDist) {
                dx = (dx / dist) * maxDist;
                dy = (dy / dist) * maxDist;
            }

            joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`;

            // Normalize -1 to 1
            joystickVector.x = dx / maxDist;
            joystickVector.y = dy / maxDist;
        }


        // UI Flow
        const startBtn = document.getElementById('start-btn');
        const restartBtn = document.getElementById('restart-btn');
        const startScreen = document.getElementById('start-screen');
        const gameOverScreen = document.getElementById('game-over-screen');
        const hud = document.getElementById('hud');
        const scoreEl = document.getElementById('score');
        const finalScoreEl = document.getElementById('final-score');
        const hintEl = document.getElementById('controls-hint');

        function startGame() {
            player.position.set(0, 0, 0);
            camAzimuth = 0;
            camElevation = Math.PI / 4;
            cars.forEach(c => c.reset());

            gameState = 'PLAYING';
            startTime = performance.now();

            startScreen.style.display = 'none';
            gameOverScreen.style.display = 'none';
            hud.style.display = 'block';
            if(isTouchControls) {
                joystickZone.style.display = 'block';
            } else {
                hintEl.style.display = 'block';
                setTimeout(() => hintEl.style.display = 'none', 5000);
            }
        }

        function gameOver() {
            gameState = 'GAMEOVER';
            hud.style.display = 'none';
            joystickZone.style.display = 'none';
            gameOverScreen.style.display = 'flex';
            finalScoreEl.innerText = score;
        }

        startBtn.addEventListener('click', startGame);
        restartBtn.addEventListener('click', startGame);

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Game Loop
        function animate(currentTime) {
            requestAnimationFrame(animate);

            const dt = Math.min((currentTime - lastTime) / 1000, 0.1); // Cap delta time
            lastTime = currentTime;

            if (gameState === 'PLAYING') {
                // Update Score
                score = Math.floor((currentTime - startTime) / 1000);
                scoreEl.innerText = score;

                // Player Movement based on Camera Azimuth
                let moveX = 0;
                let moveZ = 0;

                // Keyboard input
                if (keys.w) moveZ -= 1;
                if (keys.s) moveZ += 1;
                if (keys.a) moveX -= 1;
                if (keys.d) moveX += 1;

                // Joystick input (overrides keyboard if active)
                if(joystickVector.x !== 0 || joystickVector.y !== 0) {
                    moveX = joystickVector.x;
                    moveZ = joystickVector.y;
                }

                if (moveX !== 0 || moveZ !== 0) {
                    // Normalize vector
                    const len = Math.hypot(moveX, moveZ);
                    moveX /= len;
                    moveZ /= len;

                    // Rotate movement vector by camera azimuth
                    const cosA = Math.cos(camAzimuth);
                    const sinA = Math.sin(camAzimuth);

                    const finalMoveX = (moveX * cosA - moveZ * sinA) * config.playerSpeed * dt;
                    const finalMoveZ = (moveX * sinA + moveZ * cosA) * config.playerSpeed * dt;

                    player.position.x += finalMoveX;
                    player.position.z += finalMoveZ;

                    // Bounds check (roughly keep inside city)
                    const limit = totalSize / 2;
                    player.position.x = Math.max(-limit, Math.min(limit, player.position.x));
                    player.position.z = Math.max(-limit, Math.min(limit, player.position.z));
                }

                // Update Camera Rig Position
                cameraRig.position.copy(player.position);

                // Update Camera Position on Rig based on orbit angles
                const radius = 15;
                camera.position.x = Math.sin(camAzimuth) * Math.cos(camElevation) * radius;
                camera.position.y = Math.sin(camElevation) * radius;
                camera.position.z = Math.cos(camAzimuth) * Math.cos(camElevation) * radius;
                camera.lookAt(player.position.x, player.position.y + 1, player.position.z);

                // Update Cars & Check Collision
                for (let i = 0; i < cars.length; i++) {
                    cars[i].update(dt);

                    // Simple Box-Circle Collision
                    const cx = cars[i].mesh.position.x;
                    const cz = cars[i].mesh.position.z;

                    // Approximate car bounds (length 4, width 2)
                    // Simplify by checking distance to center, adjusted for shape
                    const dx = player.position.x - cx;
                    const dz = player.position.z - cz;
                    const distSq = dx*dx + dz*dz;

                    // Rough collision check: radius + half car diagonal
                    if (distSq < (playerRadius + 1.5) * (playerRadius + 1.5)) {
                        // More precise check needed if inside rough radius due to rotation
                        // For simplicity in this demo, a slightly smaller circular bounding box for cars is used
                        if(distSq < 2.5) { // tuned value
                             gameOver();
                             break;
                        }
                    }
                }
            }

            renderer.render(scene, camera);
        }

        requestAnimationFrame(animate);

    </script>
