            const branch = createCylinder(startPoint, endPoint, radius, radius * 0.7);
            treeGroup.add(branch);

            if (depth === maxDepth && maxDepth > 1) {
                // Add leaves
                const leafGeo = new THREE.IcosahedronGeometry(radius * 5, 1);
                const leaf = new THREE.Mesh(leafGeo, leafMat);
                leaf.position.copy(endPoint);
                leaf.castShadow = true;

                // Add slight random offset to leaves
                leaf.position.x += (random() - 0.5);
                leaf.position.y += (random() - 0.5);
                leaf.position.z += (random() - 0.5);

                leaf.scale.set(0.01, 0.01, 0.01); // Start small for animation
                treeGroup.add(leaf);

                // Animate leaf scaling
                let scale = 0.01;
                const targetScale = 1;
                const animateLeaf = () => {
                    if(scale < targetScale) {
                        scale += 0.05;
                        leaf.scale.set(scale, scale, scale);
                        requestAnimationFrame(animateLeaf);
                    }
                }
                animateLeaf();
            } else {
                // Generate child branches
                const numBranches = (depth === 0) ? 1 : Math.floor(random() * 2) + 2; // 2-3 branches
                for (let i = 0; i < numBranches; i++) {
                    const angleX = (random() - 0.5) * 1.5;
                    const angleZ = (random() - 0.5) * 1.5;

                    const newDir = direction.clone().applyEuler(new THREE.Euler(angleX, 0, angleZ)).normalize();
                    const newLen = length * (0.7 + random() * 0.2);
                    const newRad = radius * 0.7;

                    buildBranch(endPoint, newDir, newLen, newRad, depth + 1, maxDepth);
                }
            }
        }

        function generateTree(level) {
            // Clear old tree
            while(treeGroup.children.length > 0){ 
                const child = treeGroup.children[0];
                treeGroup.remove(child); 
            }

            seed = 12345; // Reset seed for consistent shape

            const maxDepth = Math.min(Math.floor(level / 2) + 1, 6);
            const baseLength = 2 + (level * 0.3);
            const baseRadius = 0.5 + (level * 0.1);

            buildBranch(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 1, 0), baseLength, baseRadius, 0, maxDepth);

            // Adjust camera based on tree size
            const targetY = baseLength * 2;
            const targetZ = 15 + (level * 1.5);

            // Simple camera tween
            let progress = 0;
            const startPos = camera.position.clone();
            const targetPos = new THREE.Vector3(0, targetY/2 + 2, targetZ);

            const moveCamera = () => {
                progress += 0.05;
                if(progress <= 1) {
                    camera.position.lerpVectors(startPos, targetPos, progress);
                    camera.lookAt(0, targetY/2, 0);
                    requestAnimationFrame(moveCamera);
                }
            };
            moveCamera();
        }

        function spawnBreakParticles(yPos) {
            for(let i=0; i<10; i++) {
                const mesh = new THREE.Mesh(particleGeo, woodMat);
                mesh.position.set((Math.random()-0.5)*3, yPos + Math.random()*2, (Math.random()-0.5)*3);
                mesh.velocity = new THREE.Vector3((Math.random()-0.5)*5, Math.random()*5, (Math.random()-0.5)*5);
                mesh.rotationSpeed = new THREE.Vector3(Math.random(), Math.random(), Math.random());
                scene.add(mesh);
                particles.push(mesh);
            }
        }

        // --- Game State & Logic ---
        let gameState = {
            habit: "",
            level: 0,
            maxLevel: 15,
            health: 3
        };

        const ui = {
            startScreen: document.getElementById('start-screen'),
            habitInput: document.getElementById('habit-input'),
            startBtn: document.getElementById('start-btn'),
            header: document.getElementById('header'),
            controls: document.getElementById('controls'),
            habitDisplay: document.getElementById('habit-display'),
            levelDisplay: document.getElementById('level-display'),
            healthDisplay: document.getElementById('health-display'),
            successBtn: document.getElementById('success-btn'),
            failBtn: document.getElementById('fail-btn'),
            gameOverScreen: document.getElementById('game-over-screen'),
            endTitle: document.getElementById('end-title'),
            endMessage: document.getElementById('end-message'),
            restartBtn: document.getElementById('restart-btn')
        };

        const heartSVG = `<svg class="w-6 h-6 text-red-500 fill-current" viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>`;
        const brokenHeartSVG = `<svg class="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3l18 18"></path></svg>`;

        function updateUI() {
            ui.habitDisplay.innerText = gameState.habit;
            ui.levelDisplay.innerText = `Growth Level: ${gameState.level}`;

            ui.healthDisplay.innerHTML = '';
            for(let i=0; i<3; i++) {
                if(i < gameState.health) {
                    ui.healthDisplay.innerHTML += heartSVG;
                } else {
                    ui.healthDisplay.innerHTML += brokenHeartSVG;
                }
            }
        }

        function startGame() {
            const val = ui.habitInput.value.trim();
            if(!val) return;

            gameState.habit = val;
            gameState.level = 1;
            gameState.health = 3;

            ui.startScreen.classList.add('opacity-0', 'pointer-events-none');
            setTimeout(() => ui.startScreen.classList.add('hidden'), 500);

            ui.header.classList.remove('hidden');
            ui.controls.classList.remove('hidden');

            // Animate controls in
            setTimeout(() => {
                ui.controls.classList.remove('translate-y-20', 'opacity-0');
            }, 100);

            updateUI();
            generateTree(gameState.level);
            playSound('grow');
        }

        function growTree() {
            if(gameState.level < gameState.maxLevel) {
                gameState.level++;
                updateUI();
                generateTree(gameState.level);
                playSound('grow');
            } else {
                showGameOver(true);
            }
        }

        function breakBranch() {
            playSound('break');

            // Visual shake
            document.body.classList.add('shaking');
            setTimeout(() => document.body.classList.remove('shaking'), 500);

            gameState.health--;

            if(gameState.level > 1) {
                gameState.level--;
            }

            updateUI();

            // Spawn particles roughly where top of tree is
            spawnBreakParticles(gameState.level * 2);

            // Re-generate smaller tree
            generateTree(gameState.level);

            if(gameState.health <= 0) {
                setTimeout(() => showGameOver(false), 1000);
            }
        }

        function showGameOver(victory) {
            ui.controls.classList.add('hidden');
            ui.header.classList.add('hidden');
            ui.gameOverScreen.classList.remove('hidden');

            if(victory) {
                ui.endTitle.innerText = "Magnificent Tree!";
                ui.endTitle.className = "text-3xl font-bold text-green-600 mb-4";
                ui.endMessage.innerText = `You successfully mastered "${gameState.habit}"!`;

                // Add spinning animation to tree
                const spin = () => {
                    treeGroup.rotation.y += 0.01;
                    if(!ui.gameOverScreen.classList.contains('hidden')) {
                        requestAnimationFrame(spin);
                    }
                }
                spin();
            } else {
                ui.endTitle.innerText = "Tree Withered";
                ui.endTitle.className = "text-3xl font-bold text-red-600 mb-4";
                ui.endMessage.innerText = `You broke your streak for "${gameState.habit}".`;

                // Make tree fall over
                let angle = 0;
                const fall = () => {
                    if(angle < Math.PI / 2) {
                        angle += 0.05;
                        treeGroup.rotation.x = angle;
                        requestAnimationFrame(fall);
                    }
                }
                fall();
            }
        }

        function resetGame() {
            ui.gameOverScreen.classList.add('hidden');
            ui.startScreen.classList.remove('hidden', 'opacity-0', 'pointer-events-none');
            ui.habitInput.value = '';
            treeGroup.rotation.set(0,0,0);
            while(treeGroup.children.length > 0){ treeGroup.remove(treeGroup.children[0]); }
        }

        // Event Listeners
        ui.startBtn.addEventListener('click', startGame);
        ui.habitInput.addEventListener('keypress', (e) => { if(e.key === 'Enter') startGame(); });
        ui.successBtn.addEventListener('click', growTree);
        ui.failBtn.addEventListener('click', breakBranch);
        ui.restartBtn.addEventListener('click', resetGame);

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const delta = clock.getDelta();

            // Animate leaves slightly (wind effect)
            treeGroup.children.forEach(child => {
                if(child.geometry.type === 'IcosahedronGeometry') {
                    child.rotation.x += 0.5 * delta;
                    child.rotation.y += 0.3 * delta;
                }
            });

            // Physics for breaking particles
            for(let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.velocity.y -= 9.8 * delta; // Gravity
                p.position.add(p.velocity.clone().multiplyScalar(delta));
                p.rotation.x += p.rotationSpeed.x;
                p.rotation.y += p.rotationSpeed.y;

                if(p.position.y < 0) {
                    scene.remove(p);
                    particles.splice(i, 1);
                }
            }

            // Slowly rotate scene
            scene.rotation.y += 0.05 * delta;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation loop
        animate();

    </script>
</body>
</html>
