        document.addEventListener('keyup', (e) => {
            const key = e.key.toLowerCase();
            if (keys.hasOwnProperty(key)) keys[key] = false;
            if (e.code === 'Space') keys.space = false;
            if (e.key === 'Shift') keys.shift = false;
        });
        document.addEventListener('mousedown', (e) => {
            if(e.button === 0) {
                isMouseDown = true;
                if(currentState === GameState.PLAYING && document.pointerLockElement !== document.body) {
                    document.body.requestPointerLock();
                }
            }
        });
        document.addEventListener('mouseup', (e) => { if(e.button === 0) isMouseDown = false; });

        document.addEventListener('mousemove', (e) => {
            if (document.pointerLockElement === document.body && (currentState === GameState.PLAYING || currentState === GameState.FALLING)) {
                yawObject.rotation.y -= e.movementX * 0.002;
                pitchObject.rotation.x -= e.movementY * 0.002;
                pitchObject.rotation.x = Math.max(-Math.PI/2, Math.min(Math.PI/2, pitchObject.rotation.x));
            }
        });

        // --- Initialization ---
        function init() {
            loadSave();
            updateMenuStats();

            // Fake Loading
            let progress = 0;
            const interval = setInterval(() => {
                progress += Math.random() * 15;
                if(progress >= 100) {
                    progress = 100;
                    clearInterval(interval);
                    setTimeout(showMenu, 500);
                }
                document.getElementById('loading-bar').style.width = progress + '%';
            }, 200);

            // ThreeJS Setup
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x87CEEB); // Sky blue
            scene.fog = new THREE.FogExp2(0x87CEEB, 0.002);

            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 2000);

            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.shadowMap.enabled = true;
            document.getElementById('game-container').appendChild(renderer.domElement);

            // Lights
            const ambient = new THREE.AmbientLight(0xffffff, 0.4);
            scene.add(ambient);
            const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
            dirLight.position.set(100, 200, 50);
            dirLight.castShadow = true;
            dirLight.shadow.camera.left = -500; dirLight.shadow.camera.right = 500;
            dirLight.shadow.camera.top = 500; dirLight.shadow.camera.bottom = -500;
            dirLight.shadow.mapSize.width = 2048; dirLight.shadow.mapSize.height = 2048;
            scene.add(dirLight);

            // FPS Camera setup
            pitchObject = new THREE.Object3D();
            pitchObject.add(camera);
            yawObject = new THREE.Object3D();
            yawObject.add(pitchObject);
            scene.add(yawObject);

            clock = new THREE.Clock();

            window.addEventListener('resize', onWindowResize, false);

            animate();
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        // --- UI Flow ---
        function hideAllUI() {
            document.querySelectorAll('.ui-layer').forEach(el => el.classList.remove('active-ui'));
            document.getElementById('crosshair').style.display = 'none';
        }
        function showMenu() {
            hideAllUI(); document.getElementById('ui-menu').classList.add('active-ui');
            currentState = GameState.MENU;
            if(document.pointerLockElement) document.exitPointerLock();
        }
        function showModeSelect() {
            hideAllUI(); document.getElementById('ui-mode').classList.add('active-ui');
            currentState = GameState.MODE;
        }
        function showStats() {
            alert(`Статистика:\nУровень: ${stats.level}\nПобеды: ${stats.wins}\nМатчи: ${stats.matches}\nУбийства: ${stats.totalKills}`);
        }

        // --- Game Logic ---
        function startGame(mode) {
            hideAllUI();
            document.getElementById('ui-hud').classList.add('active-ui');
            document.getElementById('action-prompt').classList.remove('hidden');

            // Reset match stats
            match.alive = 100; match.kills = 0; match.damage = 0; 
            match.startTime = Date.now(); match.zoneRadius = 1500;
            match.zoneTimer = 60; // First zone in 60s

            // Reset player
            player.hp = 100; player.armor = 0; player.ammo = 30; player.maxAmmo = 120;
            updateHUD();

            generateMap();

            // Start Plane
            currentState = GameState.PLANE;
            yawObject.position.set(-mapSize/2, 400, 0);
            yawObject.rotation.set(0, -Math.PI/2, 0);
            pitchObject.rotation.x = -Math.PI/4; // look down

            planeObj = new THREE.Mesh(new THREE.BoxGeometry(20, 5, 40), new THREE.MeshLambertMaterial({color: 0x333333}));
            planeObj.position.copy(yawObject.position);
            scene.add(planeObj);

            stats.matches++;
            saveStats();
        }

        function generateMap() {
            // Clear old
            objects.forEach(o => scene.remove(o));
            bots.forEach(b => scene.remove(b.mesh));
            loots.forEach(l => scene.remove(l.mesh));
            if(ground) scene.remove(ground);
            if(zoneMesh) scene.remove(zoneMesh);
            objects = []; bots = []; loots = [];

            // Ground
            const geo = new THREE.PlaneGeometry(mapSize*2, mapSize*2);
            const mat = new THREE.MeshLambertMaterial({ color: 0x5a7d3c });
            ground = new THREE.Mesh(geo, mat);
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            scene.add(ground);

            // Generate Cities & Forests
            const numCities = 5;
            for(let i=0; i<numCities; i++) {
                let cx = (Math.random() - 0.5) * mapSize * 0.8;
                let cz = (Math.random() - 0.5) * mapSize * 0.8;
                genCity(cx, cz);
            }

            for(let i=0; i<300; i++) {
                let tx = (Math.random() - 0.5) * mapSize;
                let tz = (Math.random() - 0.5) * mapSize;
                genTree(tx, tz);
            }

            // Spawn Zone
            const zGeo = new THREE.CylinderGeometry(1, 1, 1000, 32, 1, true);
            const zMat = new THREE.MeshBasicMaterial({ color: 0x0044ff, transparent: true, opacity: 0.3, side: THREE.DoubleSide });
            zoneMesh = new THREE.Mesh(zGeo, zMat);
            zoneMesh.position.set(0, 500, 0);
            zoneMesh.scale.set(match.zoneRadius, 1, match.zoneRadius);
            scene.add(zoneMesh);

            // Spawn Bots (real)
            for(let i=0; i<15; i++) spawnBot();
        }

        function genCity(x, z) {
            const bGeo = new THREE.BoxGeometry(10, 15, 10);
            const bMat = new THREE.MeshLambertMaterial({ color: 0x888888 });
            for(let i=0; i<5+Math.random()*5; i++) {
                let bx = x + (Math.random()-0.5)*100;
                let bz = z + (Math.random()-0.5)*100;
                let mesh = new THREE.Mesh(bGeo, bMat);
                mesh.position.set(bx, 7.5, bz);
                mesh.castShadow = true; mesh.receiveShadow = true;
                scene.add(mesh);
                objects.push(mesh);

                // Spawn loot near building
                spawnLoot(bx+6, bz);
            }
        }

        function genTree(x, z) {
            const tGeo = new THREE.CylinderGeometry(0.5, 0.5, 5);
            const tMat = new THREE.MeshLambertMaterial({ color: 0x5c4033 });
            const trunk = new THREE.Mesh(tGeo, tMat);
            trunk.position.set(x, 2.5, z);
            trunk.castShadow = true;

            const lGeo = new THREE.ConeGeometry(3, 8, 8);
            const lMat = new THREE.MeshLambertMaterial({ color: 0x228b22 });
            const leaves = new THREE.Mesh(lGeo, lMat);
            leaves.position.set(x, 8, z);
            leaves.castShadow = true;

            scene.add(trunk); scene.add(leaves);
            objects.push(trunk);
        }

        function spawnLoot(x, z) {
            const types = ['ammo', 'medkit', 'armor'];
            const type = types[Math.floor(Math.random()*types.length)];
            const lGeo = new THREE.BoxGeometry(1, 1, 1);
            let color = type === 'ammo' ? 0xffff00 : type === 'medkit' ? 0xff0000 : 0x0000ff;
            const lMat = new THREE.MeshBasicMaterial({ color: color });
            const mesh = new THREE.Mesh(lGeo, lMat);
            mesh.position.set(x, 0.5, z);
            scene.add(mesh);
            loots.push({ mesh, type });
        }

        function spawnBot() {
            const bGeo = new THREE.CylinderGeometry(1, 1, 3.6);
            const bMat = new THREE.MeshLambertMaterial({ color: 0xff0000 });
            const mesh = new THREE.Mesh(bGeo, bMat);
            mesh.position.set((Math.random()-0.5)*mapSize, 1.8, (Math.random()-0.5)*mapSize);
            mesh.castShadow = true;
            scene.add(mesh);
            bots.push({
                mesh: mesh, hp: 100, state: 'wander',
                target: new THREE.Vector3(),
                timer: 0, lastShot: 0
            });
            objects.push(mesh); // Can hit them
        }

        function jumpFromPlane() {
            currentState = GameState.FALLING;
            document.getElementById('action-prompt').classList.add('hidden');
            scene.remove(planeObj);
            pitchObject.rotation.x = -Math.PI/2;
            player.velocity.set(0, -50, 0);
            document.body.requestPointerLock();
        }

        // --- Main Update Loop ---
        function update(dt) {
            if(currentState === GameState.PLANE) {
                // Plane moves
                yawObject.position.x += 150 * dt; // 150m/s
                planeObj.position.copy(yawObject.position);
                if(yawObject.position.x > mapSize/2) jumpFromPlane(); // auto jump
            } 
            else if (currentState === GameState.FALLING) {
                // Skydive controls
                let speed = 30;
                if(keys.w) yawObject.translateZ(-speed * dt);
                if(keys.s) yawObject.translateZ(speed * dt);
                if(keys.a) yawObject.translateX(-speed * dt);
                if(keys.d) yawObject.translateX(speed * dt);

                player.velocity.y -= 9.8 * dt; // gravity
                yawObject.position.y += player.velocity.y * dt;

                // Parachute deploy
                if(yawObject.position.y < 200) player.velocity.y = Math.max(player.velocity.y, -10);

                // Land
                if(yawObject.position.y <= player.height) {
                    yawObject.position.y = player.height;
                    currentState = GameState.PLAYING;
                    pitchObject.rotation.x = 0;
                    document.getElementById('crosshair').style.display = 'block';
                }
            } 
            else if (currentState === GameState.PLAYING) {
                updatePlayer(dt);
                updateBots(dt);
                updateZone(dt);
                updateLoots();
                simulateOtherPlayers(dt);
            }

            updateBullets(dt);
            if(currentState >= GameState.PLANE) updateMinimap();
        }

        function updatePlayer(dt) {
            // Movement
            let speed = keys.shift ? player.speed * 1.5 : player.speed;

            player.velocity.x -= player.velocity.x * 10.0 * dt;
            player.velocity.z -= player.velocity.z * 10.0 * dt;
            player.velocity.y -= 9.8 * 3.0 * dt; // gravity

            const dir = new THREE.Vector3();
            if(keys.w) dir.z -= 1;
            if(keys.s) dir.z += 1;
            if(keys.a) dir.x -= 1;
            if(keys.d) dir.x += 1;
            dir.normalize();

            if (dir.length() > 0) {
                yawObject.translateX(dir.x * speed * dt);
                yawObject.translateZ(dir.z * speed * dt);
            }

            // Jump
            if(keys.space && player.isGrounded) {
                player.velocity.y = 10;
                player.isGrounded = false;
            }

            yawObject.position.y += player.velocity.y * dt;

            // Basic floor collision
            if(yawObject.position.y <= player.height) {
                player.velocity.y = 0;
                yawObject.position.y = player.height;
                player.isGrounded = true;
            }

            // Shoot
            if(isMouseDown && player.canShoot && player.ammo > 0) {
                shoot();
            }

            // Zone damage
            let distToCenter = Math.sqrt(yawObject.position.x**2 + yawObject.position.z**2);
            if(distToCenter > match.zoneRadius) {
                takeDamage(5 * dt);
                document.getElementById('zone-overlay').style.opacity = 0.5;
            } else {
                document.getElementById('zone-overlay').style.opacity = 0;
            }
        }

        function shoot() {
            player.canShoot = false;
            player.ammo--;
            playSound('shoot');
            updateHUD();

            // Recoil
            pitchObject.rotation.x += 0.02;

            // Raycast
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2(0,0), camera);

            // Visual bullet trail
            createBulletTrail(raycaster.ray.origin, raycaster.ray.direction);

            const intersects = raycaster.intersectObjects(objects);
            if(intersects.length > 0) {
                let hit = intersects[0];
                let bot = bots.find(b => b.mesh === hit.object);
                if(bot) {
                    bot.hp -= 25;
                    match.damage += 25;
                    showHitMarker();
                    playSound('hit');
                    if(bot.hp <= 0) {
                        scene.remove(bot.mesh);
                        objects = objects.filter(o => o !== bot.mesh);
                        bots = bots.filter(b => b !== bot);
                        match.kills++;
                        match.alive--;
                        spawnLoot(bot.mesh.position.x, bot.mesh.position.z);
                    }
                }
            }

            setTimeout(() => { player.canShoot = true; }, 100); // Fire rate
        }

        function createBulletTrail(origin, dir) {
            const mat = new THREE.LineBasicMaterial({ color: 0xffdd00 });
            const pts = [origin, origin.clone().add(dir.clone().multiplyScalar(100))];
            const geo = new THREE.BufferGeometry().setFromPoints(pts);
            const line = new THREE.Line(geo, mat);
            scene.add(line);
            setTimeout(() => scene.remove(line), 50);
        }

        function showHitMarker() {
            const hm = document.getElementById('hit-marker');
            hm.style.display = 'block';
            setTimeout(() => hm.style.display='none', 100);
        }

        function reload() {
            if(player.maxAmmo > 0 && player.ammo < player.clipSize) {
                let needed = player.clipSize - player.ammo;
                let take = Math.min(needed, player.maxAmmo);
                player.ammo += take;
                player.maxAmmo -= take;
                updateHUD();
            }
        }

        function updateBots(dt) {
            bots.forEach(bot => {
                let distToPlayer = bot.mesh.position.distanceTo(yawObject.position);

                if(distToPlayer < 50) {
                    // Look at player & Shoot
                    bot.mesh.lookAt(yawObject.position.x, bot.mesh.position.y, yawObject.position.z);
                    bot.state = 'attack';
                    if(Date.now() - bot.lastShot > 1000 && Math.random() > 0.5) {
                        bot.lastShot = Date.now();
                        createBulletTrail(bot.mesh.position.clone().setY(2.5), yawObject.position.clone().sub(bot.mesh.position).normalize());
                        playSound('shoot');
                        if(Math.random() > 0.6) takeDamage(15);
                    }
                } else {
                    bot.state = 'wander';
                    bot.timer -= dt;
                    if(bot.timer <= 0) {
                        bot.timer = 2 + Math.random()*3;
                        let angle = Math.random() * Math.PI * 2;
                        bot.target.set(bot.mesh.position.x + Math.cos(angle)*20, bot.mesh.position.y, bot.mesh.position.z + Math.sin(angle)*20);
                        bot.mesh.lookAt(bot.target);
                    }
                    bot.mesh.translateZ(3 * dt); // move forward
                }

                // Keep inside zone roughly
                if(bot.mesh.position.length() > match.zoneRadius) {
                    bot.mesh.lookAt(0, bot.mesh.position.y, 0);
                    bot.mesh.translateZ(5 * dt);
                }
            });
        }

        function updateZone(dt) {
            match.zoneTimer -= dt;
            let m = Math.floor(Math.max(0, match.zoneTimer) / 60).toString().padStart(2, '0');
            let s = Math.floor(Math.max(0, match.zoneTimer) % 60).toString().padStart(2, '0');
            document.getElementById('hud-zone-timer').innerText = `${m}:${s}`;

            if(match.zoneTimer <= 0) {
                // Shrinking
                match.zoneRadius -= 10 * dt;
                zoneMesh.scale.set(match.zoneRadius, 1, match.zoneRadius);
                if(match.zoneRadius <= match.maxRadius * 0.7) {
                    // Next phase
                    match.maxRadius = match.zoneRadius;
                    match.zoneTimer = 60;
                    match.zonePhase++;
                }
            }
        }

        let interactTarget = null;
        function updateLoots() {
            let prompt = document.getElementById('interaction-prompt');
            interactTarget = null;
            let closest = Infinity;

            loots.forEach(loot => {
                let dist = loot.mesh.position.distanceTo(yawObject.position);
                loot.mesh.rotation.y += 0.02; // Spin
                if(dist < 3 && dist < closest) {
                    closest = dist;
                    interactTarget = loot;
                }
            });

            if(interactTarget) {
                prompt.style.display = 'block';
                let name = interactTarget.type === 'ammo' ? 'Патроны' : interactTarget.type === 'medkit' ? 'Аптечка' : 'Броня';
                prompt.innerText = `[F] Подобрать ${name}`;
            } else {
                prompt.style.display = 'none';
            }
        }

        function interact() {
            if(interactTarget) {
                playSound('pickup');
                if(interactTarget.type === 'ammo') player.maxAmmo += 30;
                if(interactTarget.type === 'medkit') player.hp = Math.min(player.maxHp, player.hp + 50);
                if(interactTarget.type === 'armor') player.armor = Math.min(player.maxArmor, player.armor + 50);

                scene.remove(interactTarget.mesh);
                loots = loots.filter(l => l !== interactTarget);
                interactTarget = null;
                updateHUD();
            }
        }

        function simulateOtherPlayers(dt) {
            if(Math.random() < 0.005 * dt && match.alive > bots.length + 1) {
                match.alive--;
                updateHUD();
            }

            if(match.alive <= 1) { // Victory
                endGame(true);
            }
        }

        function takeDamage(amt) {
            if(player.armor > 0) {
                player.armor -= amt;
                if(player.armor < 0) {
                    player.hp += player.armor;
                    player.armor = 0;
                }
            } else {
                player.hp -= amt;
            }

            // Blood screen
            const blood = document.getElementById('blood-overlay');
            blood.style.opacity = 1;
            setTimeout(() => blood.style.opacity = 0, 200);

            updateHUD();
            if(player.hp <= 0) endGame(false);
        }

        function updateHUD() {
            document.getElementById('hud-hp-text').innerText = Math.floor(player.hp);
            document.getElementById('hud-hp-bar').style.width = player.hp + '%';
            document.getElementById('hud-armor-text').innerText = Math.floor(player.armor);
            document.getElementById('hud-armor-bar').style.width = player.armor + '%';
            document.getElementById('hud-ammo').innerText = player.ammo;
            document.getElementById('hud-ammo').nextElementSibling.innerText = '/' + player.maxAmmo;
            document.getElementById('hud-alive').innerText = match.alive;
            document.getElementById('hud-kills').innerText = match.kills;
        }

        function updateBullets(dt) {
            // Placeholder if physical bullets used, currently using raycast
        }

        // --- Minimap ---
        const minimapCanvas = document.getElementById('minimap');
        const mCtx = minimapCanvas.getContext('2d');
        minimapCanvas.width = 200; minimapCanvas.height = 200;

        function updateMinimap() {
            mCtx.clearRect(0, 0, 200, 200);

            // Center around player
            let px = yawObject.position.x;
            let pz = yawObject.position.z;
            let scale = 0.2; // Zoom level

            mCtx.save();
            mCtx.translate(100, 100);
            mCtx.scale(scale, scale);
            mCtx.translate(-px, -pz);

            // Map boundaries
            mCtx.fillStyle = '#5a7d3c';
            mCtx.fillRect(-mapSize, -mapSize, mapSize*2, mapSize*2);

            // Buildings
            mCtx.fillStyle = '#888';
            objects.forEach(o => {
                if(o.geometry.type === 'BoxGeometry') {
                    mCtx.fillRect(o.position.x-5, o.position.z-5, 10, 10);
                }
            });

            // Zone
            mCtx.strokeStyle = 'blue';
            mCtx.lineWidth = 10 / scale;
            mCtx.beginPath();
            mCtx.arc(0, 0, match.zoneRadius, 0, Math.PI*2);
            mCtx.stroke();

            // Player
            mCtx.restore();
            mCtx.fillStyle = 'white';
            mCtx.beginPath();
            mCtx.arc(100, 100, 4, 0, Math.PI*2);
            mCtx.fill();

            // Field of view cone
            mCtx.strokeStyle = 'rgba(255,255,255,0.5)';
            mCtx.beginPath();
            mCtx.moveTo(100, 100);
            let rot = -yawObject.rotation.y - Math.PI/2;
            mCtx.lineTo(100 + Math.cos(rot-0.5)*30, 100 + Math.sin(rot-0.5)*30);
            mCtx.lineTo(100 + Math.cos(rot+0.5)*30, 100 + Math.sin(rot+0.5)*30);
            mCtx.closePath();
            mCtx.stroke();
        }

        // --- Game Over ---
        function endGame(isVictory) {
            currentState = GameState.GAMEOVER;
            if(document.pointerLockElement) document.exitPointerLock();
            hideAllUI();

            let timePlayed = Math.floor((Date.now() - match.startTime) / 1000);
            let m = Math.floor(timePlayed / 60).toString().padStart(2, '0');
            let s = (timePlayed % 60).toString().padStart(2, '0');

            let rank = isVictory ? 1 : match.alive;
            let ratingGain = (isVictory ? 500 : 0) + (match.kills * 10) + Math.floor(timePlayed/60);

            stats.totalKills += match.kills;
            stats.rating += ratingGain;
            if(isVictory) stats.wins++;
            if(stats.rating > stats.level * 1000) stats.level++;
            saveStats();

            const goUi = document.getElementById('ui-gameover');
            goUi.classList.add('active-ui');
            document.getElementById('go-title').innerText = isVictory ? 'ПОБЕДА!' : 'ВЫБЫЛ';
            document.getElementById('go-title').className = `text-8xl font-bold mb-2 ${isVictory?'text-yellow-400':'text-red-500'}`;
            document.getElementById('go-rank').innerText = rank;
            document.getElementById('go-kills').innerText = match.kills;
            document.getElementById('go-dmg').innerText = Math.floor(match.damage);
            document.getElementById('go-time').innerText = `${m}:${s}`;
            document.getElementById('go-rating').innerText = `+${ratingGain}`;
        }

        // --- Save/Load ---
        function saveStats() {
            localStorage.setItem('reg2_stats', JSON.stringify(stats));
            updateMenuStats();
        }
        function loadSave() {
            const saved = localStorage.getItem('reg2_stats');
            if(saved) stats = JSON.parse(saved);
        }
        function updateMenuStats() {
            document.getElementById('menu-level').innerText = stats.level;
            document.getElementById('menu-rating').innerText = stats.rating;
        }

        // --- Main Loop ---
        function animate() {
            requestAnimationFrame(animate);
            let dt = clock.getDelta();
            if(dt > 0.1) dt = 0.1; // cap
            update(dt);
            if(renderer && scene && camera) renderer.render(scene, camera);
        }

        // Start everything
        window.onload = init;

    </script>
</body>
</html>
